#!/usr/bin/env python3
"""orch: thin glue over beads (bd), pueue, tmux, herdr, ssh, rsync and git. Python 3.11+, standard library only.
Reads orch.toml from the current directory or a parent. See docs/DESIGN.md and skill/SKILL.md."""
import argparse, calendar, concurrent.futures as cf, hashlib, json, os, re, shlex, subprocess, sys, time, tomllib
from pathlib import Path

SSH = ["ssh", "-o", "BatchMode=yes", "-o", "ConnectTimeout=5"]
EXCL = ["--exclude", ".git", "--exclude", "target", "--exclude", ".venv", "--exclude", "node_modules"]
WAKE = "read .orch/HANDOFF.md, run orch check, act, update the notes"
LB, LE = "<!-- LIVE:BEGIN (regenerated by orch check; do not edit) -->", "<!-- LIVE:END -->"
NOTES_H = "## Orchestrator notes"
NOTES0 = NOTES_H + "\n(goal and scope; per unit why and what done means; decisions latest first; next steps; things to watch)\n"
DRY = False

class Err(Exception): pass

def now(): return time.time()
def ts(t=None): return time.strftime("%Y-%m-%d %H:%M", time.localtime(t or now()))
def say(*a): print(*a, flush=True)

# ---------------------------------------------------------------- config and state
def find_root(start=None):
    p = Path(start or os.getcwd()).resolve()
    for d in [p, *p.parents]:
        if (d / "orch.toml").is_file(): return d
    r = os.environ.get("ORCH_ROOT")   # tasks and project shims run from a worktree outside the orch root
    return Path(r).resolve() if not start and r and (Path(r) / "orch.toml").is_file() else None

class Cfg:
    def __init__(self, root):
        self.root = root
        self.c = tomllib.loads((root / "orch.toml").read_text())
        pr = self.c.get("project", {})
        self.name = pr.get("name", root.name)
        self.state = root / pr.get("state", ".orch"); self.state.mkdir(exist_ok=True)
        self.beads = root / pr.get("beads", ".")
        self.cycle = pr.get("cycle_min", 15) * 60; self.deadline = pr.get("deadline_min", 30) * 60
        self.silent = pr.get("silent_min", 30) * 60; self.unreach = pr.get("unreachable_min", 20) * 60
        self.reset_tokens = pr.get("reset_tokens", 150000)
        self.hosts = self.c.get("hosts", {}); self.prov = self.c.get("providers", {})
        self.models = self.c.get("models", {}); self.route = self.c.get("routing", {})
        self.paths = self.c.get("paths", {}); self.caps = self.c.get("caps", {})
        self.capc = self.c.get("capacity", {})
        for h in self.hosts.values():   # each host's runs dir: lane job scripts, logs, reservations, history (see cap_lib)
            h["_rd"] = str(self.state / "runs") if h.get("local") else f"{h.get('root', '/tmp')}/runs"
    def p(self, k, d=""): return self.root / self.paths.get(k, d)
    def f(self, n): return self.state / n
    def jget(self, n, d=None):
        try: return json.loads(self.f(n).read_text())
        except Exception: return {} if d is None else d
    ro = False   # read-only: check/status/capacity run by anyone but the registered orchestrator change nothing (audit M15)
    def jput(self, n, v):
        if not self.ro: self.f(n).write_text(json.dumps(v))
    def touch(self, n):
        if not self.ro: self.f(n).touch()
    def mtime(self, n):
        try: return self.f(n).stat().st_mtime
        except OSError: return 0

# Every process orch queues (pueue add) or starts on the Mac gets this allow-listed environment plus explicit ORCH_* values,
# never the caller's: pueue stores a task's whole environment in its state file, so a caller's ANTHROPIC_API_KEY, messaging
# token or HERDR_PANE_ID would be written to disk (audit H1, M2).
ENV_KEEP = ("PATH", "HOME", "USER", "LOGNAME", "SHELL", "LANG", "LC_ALL", "LC_CTYPE", "TMPDIR", "TERM", "SSH_AUTH_SOCK", "TZ", "XDG_RUNTIME_DIR", "XDG_CONFIG_HOME")
SECRET_ENV = re.compile(r"KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL", re.I)

def clean_env(extra=None):
    e = {k: os.environ[k] for k in ENV_KEEP if k in os.environ}
    # /usr/sbin and /sbin always: launchd gives the watcher a PATH without them, and the macOS probe's sysctl lives there
    # (issue 3: the probe read 0.0 GB and an empty load under the watcher)
    e["PATH"] = os.path.expanduser("~/.local/bin") + ":/opt/homebrew/bin:/usr/local/bin:" + e.get("PATH", "/usr/bin:/bin") + ":/usr/bin:/bin:/usr/sbin:/sbin"
    return {**e, **{k: str(v) for k, v in (extra or {}).items()}}

def sh(cmd, cwd=None, inp=None, timeout=25, env=None, clean=False):
    """Run a command. clean=True: an allow-listed environment plus env (see clean_env), never the caller's."""
    try:
        r = subprocess.run(cmd, cwd=cwd, input=inp, capture_output=True, text=True, timeout=timeout,
                           env=clean_env(env) if clean else ({**os.environ, **env} if env else None))
        return r.returncode, r.stdout, r.stderr
    except FileNotFoundError: return 127, "", f"{cmd[0]}: not installed"
    except subprocess.TimeoutExpired: return 124, "", f"{cmd[0]}: timeout"

def hrun(h, script, timeout=25, inp=None, env=None):
    """Run a shell script on host h (local or over ssh). Locally it gets a clean environment (clean_env) plus env; over ssh only
    the remote login environment (ssh forwards no variables here), with env exported in the script."""
    if h.get("local"): return sh(["sh", "-c", script], timeout=timeout, inp=inp, env=env, clean=True)
    pre = "".join(f"export {k}={shlex.quote(str(v))}; " for k, v in (env or {}).items())
    return sh([*SSH, h["ssh"], pre + script], timeout=timeout, inp=inp)

def X(h, script, **k):
    """Run on a host, or print in dry-run."""
    if DRY: say(f"+ [{h.get('ssh', 'local')}] " + "".join(f"{k}=... " for k in (k.get("env") or {})) + script); return 0, "", ""
    return hrun(h, script, **k)

def herdr(*a, timeout=20):
    rc, o, e = sh(["herdr", *a], timeout=timeout)
    try: return json.loads(o).get("result", {}) if rc == 0 else None
    except Exception: return None

def findkey(o, sub):
    if isinstance(o, dict):
        for k, v in o.items():
            if sub in k and isinstance(v, int): return v
            r = findkey(v, sub)
            if r: return r
    elif isinstance(o, list):
        for v in o:
            r = findkey(v, sub)
            if r: return r

# ---------------------------------------------------------------- processes and the registered session
def ps_table():
    """{pid: (ppid, pgid, started, command)} for every process (one ps call)."""
    rc, o, e = sh(["ps", "-Aww", "-o", "pid=,ppid=,pgid=,lstart=,command="], timeout=10)
    t = {}
    for l in o.splitlines():
        f = l.split(None, 8)   # pid ppid pgid + lstart is 5 words (Wed Nov 11 15:31:02 2026) + command
        if len(f) >= 8 and f[0].isdigit(): t[int(f[0])] = (int(f[1]), int(f[2]), " ".join(f[3:8]), f[8] if len(f) > 8 else "")
    return t

def ancestors(t, pid):
    out = []
    while pid in t and pid not in out and pid > 1: out.append(pid); pid = t[pid][0]
    return out

AGENT_RX = re.compile(r"(^|/)(claude|codex)(\s|$)|/(claude|codex)(-code)?/|\bnode\b.*\b(claude|codex)\b")

def session_proc(t=None):
    """(pid, start) of the Claude Code or Codex process this process runs under (hooks and Bash commands are its children)."""
    t = t or ps_table()
    for p in ancestors(t, os.getpid())[1:]:
        if AGENT_RX.search(t[p][3]): return p, t[p][2]
    p = int(os.environ.get("CLAUDE_PID", "0") or 0)
    return (p, t[p][2]) if p in t else (None, None)

def record_session_proc(cfg, t=None):
    p, st = session_proc(t)
    if p: cfg.f("session_pid").write_text(f"{p}\t{st}\n")

def session_alive(cfg, t=None):
    """True while the registered session's process still runs (same pid and start time). None when nothing is recorded."""
    try: p, st = cfg.f("session_pid").read_text().rstrip("\n").split("\t")
    except (OSError, ValueError): return None
    t = t or ps_table(); x = t.get(int(p))
    return bool(x and x[2] == st)

def is_orchestrator(cfg):
    """The caller is the registered orchestrator session: its session id is the registered one, or the registered session's
    process is among the caller's ancestors. Only then do check and status change state (audit M15)."""
    reg = cfg.f("session").read_text().strip() if cfg.f("session").exists() else ""
    if reg and reg in (os.environ.get("CLAUDE_CODE_SESSION_ID"), os.environ.get("CLAUDE_SESSION_ID"), os.environ.get("CODEX_THREAD_ID"), os.environ.get("ORCH_SESSION")):
        return True
    try: p, st = cfg.f("session_pid").read_text().rstrip("\n").split("\t")
    except (OSError, ValueError): return False
    t = ps_table(); return int(p) in ancestors(t, os.getpid()) and t[int(p)][2] == st

def projects():
    pl = Path.home() / ".config/orch/projects"
    return [Path(x) for x in (pl.read_text().split() if pl.exists() else []) if (Path(x) / "orch.toml").is_file()]

def session_root(sid):
    """The project whose registered session is sid (audit H3: hooks never depend on the session's current directory)."""
    for r in projects():
        try: st = r / tomllib.loads((r / "orch.toml").read_text()).get("project", {}).get("state", ".orch")
        except Exception: continue
        if (st / "session").exists() and (st / "session").read_text().strip() == sid: return r
    return None

# ---------------------------------------------------------------- beads
class Beads:
    def __init__(self, cfg): self.cfg = cfg
    def run(self, *a):
        rc, o, e = sh(["bd", *a, "--json"], cwd=self.cfg.beads)
        if rc: raise Err(f"bd {a[0]}: {(e or o).strip()[:120]}")
        try: return json.loads(o) if o.strip() else []
        except Exception: raise Err(f"bd {a[0]}: bad json")
    def issues(self, label, status="open"):
        r = self.run("list", "--label", label, "--status", status)
        return r.get("issues", r) if isinstance(r, dict) else r
    def units(self):
        """Open units: launch marks each in_progress (so `bd ready` never lists a running unit); older ones are still open."""
        out = []
        for i in self.issues("unit", "open,in_progress"):
            t = i.get("title", "")
            if not t.startswith("unit:"): continue
            try: m = json.loads(i.get("notes") or i.get("description") or "{}")
            except Exception: m = {}
            out.append({**m, "id": i["id"], "name": t[5:]})
        return out
    def save(self, u):
        """The unit's record (beads notes). What check computes on the fly (state, verdict, keys starting with _) is never saved."""
        meta = {k: v for k, v in u.items() if k not in ("id", "name", "state", "verdict", "status") and not k.startswith("_")}
        self.run("update", u["id"], "--notes", json.dumps(meta))
    def create(self, title, label, desc=""): 
        r = self.run("create", title, "-l", label, "-d", desc)
        return (r[0] if isinstance(r, list) else r)["id"]
    def comment(self, i, text): sh(["bd", "comments", "add", i, text], cwd=self.cfg.beads)

# ---------------------------------------------------------------- hosts: one probe per host
PROBE = r'''PATH="$HOME/.local/bin:%(bin)s:$PATH:/usr/bin:/bin:/usr/sbin:/sbin"
if [ "$(uname)" = Darwin ]; then
 # Two readings, the larger wins: the kernel's free level (memory_pressure's "free percentage", read straight from sysctl, no
 # tool run under load) and vm_stat's free + inactive + speculative + purgeable pages. Under load one of them can read 0
 # (memory_pressure timing out or the level lagging), which made the Mac look full; an empty reading is reported as empty.
 mem=$(sysctl -n hw.memsize 2>/dev/null); fp=$(sysctl -n kern.memorystatus_level 2>/dev/null)
 [ -n "$fp" ] || fp=$(memory_pressure 2>/dev/null | awk '/free percentage/{gsub(/%%/,"",$NF);print int($NF)}')
 a=0; [ -n "$fp" ] && [ -n "$mem" ] && a=$((mem/1048576*fp/100))
 b=$(vm_stat 2>/dev/null | awk '/page size of/{ps=$(NF-1)} /^Pages (free|inactive|speculative|purgeable):/{gsub(/\./,"",$NF);n+=$NF} END{if (ps) print int(n*ps/1048576)}')
 mb=${b:-0}; [ "$a" -gt "$mb" ] && mb=$a; [ "$mb" -gt 0 ] || mb=
 echo "avail_mb=$mb"; echo "load=$(sysctl -n vm.loadavg | tr -d '{}' | awk '{print $1}')"; echo "os=mac"
else
 echo "avail_mb=$(awk '/MemAvailable/{print int($2/1024)}' /proc/meminfo)"; echo "load=$(cut -d' ' -f1 /proc/loadavg)"
 echo "psi=$(awk '/^some/{sub("avg10=","",$2);print $2}' /proc/pressure/memory 2>/dev/null)"; echo "os=linux"
fi
d=%(root)s; [ -d "$d" ] || d=/; echo "disk_gb=$(df -Pk "$d" 2>/dev/null | awk 'NR==2{print int($4/1048576)}')"
%(extra)s
RD=%(rd)s; CAP_RO=%(ro)s
%(cap)s
cap_report
echo "--pueue"; %(pueue)s status --json 2>/dev/null
echo "--tmux"; tmux ls -F '#S' 2>/dev/null; true'''

def probe_extra(h):
    """Running orch jobs still waiting in their admission (per lane), the old scripts' queue, other job schedulers on the host
    (one scheduler per host, orch-fixes8), and on remote hosts builds or tests an agent runs outside the lanes (issue 22)."""
    rd = h["_rd"]
    # old_rule: waiting jobs whose script sources neither runs/cap.sh nor runs/admit.sh (queued before the measured rule; audit H5)
    w = (f'g=0; j=0; o=0; ol=; for f in {qp(rd)}/*.gwait {qp(rd)}/*.wait; do [ -e "$f" ] && kill -0 "$(cat "$f")" 2>/dev/null || continue; '
         f'b=${{f##*/}}; echo "waitjob=${{b%.*}}"; case $f in *.gwait) g=$((g+1));; *) j=$((j+1));; esac; s=${{f%.*}}.sh; grep -qE "cap.sh|admit.sh" "$s" 2>/dev/null || {{ o=$((o+1)); ol="$ol ${{s##*/}}"; }}; done; '
         f'echo "wait_gates=$g"; echo "wait_jobs=$j"; echo "old_rule=$o"; echo "old_rule_jobs=$ol"')
    # schedulers (orch.toml, per host): extended regexes for the command lines of other job-running processes (an old queue); each
    # running one prints sched=<pid> <command>. legacy_lanes (the Mac): pid-file folders of an old lane; a live pid is one too.
    for rx in h.get("schedulers", []):
        w += f"\nps -A -o pid=,command= | grep -E {shlex.quote(rx)} | grep -v -e grep -e pueued -e 'cap_report' | head -5 | sed 's/^ */sched=/'"
    for s in h.get("legacy_lanes", "").split():
        w += f'\no=$(cat {shlex.quote(s)}/pid 2>/dev/null); [ -n "$o" ] && kill -0 "$o" 2>/dev/null && echo "sched=$o old lane {s}"'
    if not h.get("local"): w += "\n" + DIRECT_PROBE % {"rx": shlex.quote(BUILD_ERE)}
    # legacy_probe (orch.toml, per host): shell that prints legacy_wait=<n> and legacy_run=<n> for a project's older job queue
    # while it drains, so a jammed old queue shows in orch check
    return w + "\n" + h.get("legacy_probe", "")

# Remote lane enforcement (issue 22): processes on a Linux host whose environment carries ORCH_UNIT (an agent and what it starts),
# whose command is a build or test, and that do not run under pueued (a lane job): printed as direct=<pid> <pgid> <unit> <secs> <cmd>.
# Only the topmost such process of a tree is printed; a call of the unit's lane runner (<root>/run/<unit>.lane) is the lane.
BUILD_ERE = "(^|[ /])cargo(-[a-z]+)? (test|nextest|build|clippy|bench)( |$)|(^|[ /])pytest( |$)|(^|[ /])(npm|pnpm) (run )?test( |$)|xcodebuild.* test"
DIRECT_PROBE = r'''if [ -d /proc/1 ]; then
 for f in /proc/[0-9]*/environ; do u=$(tr '\0' '\n' < $f 2>/dev/null | sed -n 's/^ORCH_UNIT=//p'); [ -n "$u" ] && echo "${f#/proc/} $u"; done 2>/dev/null | sed 's#/environ##' > /tmp/.orch-units.$$
 ps -A -o pid=,ppid=,pgid=,etimes=,args= | awk -v rx=%(rx)s 'NR == FNR {u[$1] = $2; next} {pp[$1] = $2; pg[$1] = $3; et[$1] = $4; c = $0; sub(/^ *[0-9]+ +[0-9]+ +[0-9]+ +[0-9]+ +/, "", c); cmd[$1] = c}
   END {for (p in u) {if (!(p in cmd) || cmd[p] !~ rx || cmd[p] ~ /\.lane( |$)|orch(\.py)? (run|gate) /) continue; q = pp[p]; lane = 0; n = 0
          while (q > 1 && n++ < 50) {if (cmd[q] ~ /pueued/ || cmd[q] ~ /cmd\.sh|\/runs\/[^ ]*\.sh/) {lane = 1; break}; if (u[q] != "" && cmd[q] ~ rx) {lane = 1; break}; q = pp[q]}
          if (!lane) print "direct=" p, pg[p], u[p], et[p], substr(cmd[p], 1, 100)}}' /tmp/.orch-units.$$ - 2>/dev/null
 rm -f /tmp/.orch-units.$$
fi'''

def pueue(h):
    c = h.get("pueue_config"); pre = "" if h.get("local") else f'PATH="$HOME/.local/bin:{h.get("bin", "")}:$PATH" '
    return pre + "pueue" + (f" -c {shlex.quote(c)}" if c else "")

LIST_KEYS = ("res", "hist", "sched", "direct", "waitjob")   # probe lines that repeat: kept as lists (waitjob: jobs waiting for admission)

def probe(name, h, ro=True, cfg=None):
    """One ssh (or local sh) per host: memory, load, PSI, disk, waiting jobs, the capacity library's report (reservations, pause,
    history), other schedulers, direct builds, pueue status and tmux sessions. ro: the overload tracker is only read."""
    lib = cap_lib(cfg, name, h) if cfg else ""
    rc, o, e = hrun(h, PROBE % {"bin": h.get("bin", ""), "root": qp(h.get("root", "/")), "pueue": pueue(h), "extra": probe_extra(h),
                                "rd": qp(h["_rd"]), "ro": "1" if ro else "", "cap": lib or "cap_report() { :; }"}, timeout=25)
    if rc: return {"name": name, "ok": False, "err": (e or o).strip().splitlines()[-1][:80] if (e or o).strip() else f"rc {rc}"}
    head, _, rest = o.partition("--pueue\n"); pj, _, tm = rest.partition("--tmux\n")
    p = {"name": name, "ok": True, "tmux": tm.split(), **{k: [] for k in LIST_KEYS}}
    for l in head.splitlines():
        k, _, v = l.partition("=")
        if k in LIST_KEYS: p[k].append(v)
        else: p[k] = v
    try: p["pueue"] = json.loads(pj) if pj.strip() else None
    except Exception: p["pueue"] = None
    return p

def probe_all(cfg):
    with cf.ThreadPoolExecutor(8) as ex:
        ps = list(ex.map(lambda kv: probe(*kv, ro=cfg.ro, cfg=cfg), cfg.hosts.items()))
    d = {p["name"]: p for p in ps}
    un = cfg.jget("hosts.json")
    for n, p in d.items():
        if p["ok"]: un.pop(n, None)
        else: un.setdefault(n, now())
    cfg.jput("hosts.json", un)
    return d

def fl(x, d=0.0):
    try: return float(x)
    except Exception: return d

def margins(h, p, cleanup=False, cfg=None):
    """Why the host is over its disk or memory-pressure margins. A cleanup unit is exempt from the disk floor (it is what frees
    it); memory pressure still counts. Load is judged by back-pressure (cap_paused: sustained, not one reading)."""
    why = []
    if p.get("cap_psi") and fl(p["cap_psi"]) > capv(cfg, h, "psi_pause"): why.append(f"memory pressure {p['cap_psi']}")
    elif not p.get("cap_psi") and p.get("psi") and fl(p["psi"]) >= 5: why.append(f"memory pressure {p['psi']}")
    if not cleanup and p.get("disk_gb") and fl(p["disk_gb"]) < h.get("min_disk_gb", 10): why.append(f"disk {p['disk_gb']}G")
    return why

def room(cfg, name, p, units, cleanup=False):
    """(number of agents that fit now, why not), by reservations: the host's memory for reservations (ram_gb - services_gb)
    minus its jobs' and agents' reservations, over the agent figure (learned: class agent in the host's history, else
    agent_gb); none while admission is paused (back-pressure), and the owner's caps."""
    h = cfg.hosts[name]
    if not p["ok"]: return 0, "unreachable"
    why = margins(h, p, cleanup, cfg); hc = host_cap(cfg, name, p, units)
    n = (hc["memcap"] - hc["rm"] - hc["agents_mb"]) // max(hc["amb"], 1)
    if n < 1: why.append(f"memory reserved: jobs {hc['rm']} MB + {hc['on']} agent(s) {hc['agents_mb']} MB of {hc['memcap']} MB (RAM - services)")
    if hc["pause"] and not cleanup: why.append(f"admission paused: {hc['pause']}")
    caps = cfg.caps
    if caps.get("host", {}).get(name) is not None:
        n = min(n, caps["host"][name] - sum(1 for u in units if u.get("host") == name))
    if caps.get("total") is not None: n = min(n, caps["total"] - len(units))
    return (0, "; ".join(why) or "caps") if why or n < 1 else (int(n), "")

def cap_line(cfg, name, p, units):
    if not p["ok"]: return f"{name} UNREACHABLE ({p['err']})"
    n, why = room(cfg, name, p, units); hc = host_cap(cfg, name, p, units)
    av = f"{fl(p.get('avail_mb')) / 1024:.1f}G" if p.get("avail_mb") else "unknown"
    return (f"{name} room={n} build: {hc['rj']} running ({hc['rc']}/{hc['cores']} cores, {hc['rm']}/{hc['memcap']} MB reserved), "
            f"{hc['queued']} queued, {len(hc['agents'])} agent(s) for {hc['slots']} slot(s), free {hc['free']} x {hc['jmb']} MB; "
            f"avail={av} load={p.get('load') or 'unknown'} psi={p.get('cap_psi') or p.get('psi') or '-'} disk={p.get('disk_gb')}G"
            + (f" PAUSED: {hc['pause']}" if hc["pause"] else "") + (f" FULL: {why}" if n < 1 else ""))

# ---------------------------------------------------------------- capacity: reservations, back-pressure, history (orch-fixes8)
# "Launch as much as we can, but no more." Admission is by reservations, never by a momentary reading: each running job holds
# cores_per_job cores and the memory its job class needed before (the peak resident memory of past runs of that class on that
# host, plus margin_pct), each agent with a reservation file holds the agent class's figure; a job is admitted while the sum
# fits cores and ram_gb - services_gb. Back-pressure pauses admission (memory PSI avg10 over psi_pause, or load over
# load_pause x cores for hold_s); a running job is never killed for it. One shell library per host (runs/cap.sh) holds the
# rule: every waiting job sources it each poll, and every probe carries it inline, so orch check, launch and fill read the
# same numbers the admission uses. Settings: per host, else [capacity], else the default below.
CAP_DEFAULTS = {"cores": 4, "cores_per_job": 1, "ram_gb": 4, "services_gb": 0, "job_gb": 2, "agent_gb": 1.0, "psi_pause": 10,
                "load_pause": 1.25, "hold_s": 60, "history_n": 5, "margin_pct": 15, "min_disk_gb": 10}

def capv(cfg, h, k):
    return h.get(k, (cfg.capc if cfg else {}).get(k, CAP_DEFAULTS[k]))

def cap_nums(cfg, h):
    """The host's capacity in integers: cores, cores per job, memory for reservations (MB), job default/cap (MB), agent (MB)."""
    return {"cores": int(capv(cfg, h, "cores")), "cpj": max(1, int(-(-capv(cfg, h, "cores_per_job") // 1))),
            "memcap": int((capv(cfg, h, "ram_gb") - capv(cfg, h, "services_gb")) * 1024), "capmb": int(capv(cfg, h, "job_gb") * 1024),
            "agmb": int(capv(cfg, h, "agent_gb") * 1024), "hn": int(capv(cfg, h, "history_n")), "margin": int(capv(cfg, h, "margin_pct"))}

CAP_LIB = r'''# orch capacity library for host %(name)s (written by orch, see cap_lib in orch.py; do not edit: the next orch run rewrites it).
# Sourced by every waiting job each poll and sent inline with every probe. Needs RD (the runs dir).
CORES=%(cores)d CPJ=%(cpj)d MEMCAP=%(memcap)d CAPMB=%(capmb)d AGMB=%(agmb)d PSIP=%(psip)s LOADX=%(loadx)s HOLD=%(hold)d DISK=%(disk)d HN=%(hn)d MARGIN=%(margin)d
U=$(id -u); AS=/sys/fs/cgroup/user.slice/user-$U.slice/user@$U.service/app.slice; US=/sys/fs/cgroup/user.slice/user-$U.slice/user@$U.service/user.slice
cap_mb() {  # $1 class, $2 default MB, $3 cap MB (0: none): the max of the class's last HN recorded peaks + MARGIN %%, at least
  # 256 (class agent: the median of its last 3 x HN peaks, at least 128: many light agents seldom peak together)
  [ -f "$RD/history.tsv" ] || { echo "$2"; return; }
  awk -F'\t' -v c="$1" -v n=$HN -v m=$MARGIN -v d="$2" -v cap="$3" 'BEGIN {if (c == "agent") n *= 3} $2 == c && $3 > 0 {p[k++ %% n] = $3}
    END {if (!k) {print d; exit}; j = 0; for (i in p) v_[++j] = p[i] + 0
         for (a = 2; a <= j; a++) {x = v_[a]; b = a - 1; while (b > 0 && v_[b] > x) {v_[b + 1] = v_[b]; b--}; v_[b + 1] = x}
         mx = (c == "agent") ? v_[int((j + 1) / 2)] : v_[j]; lo = (c == "agent") ? 128 : 256
         v = int(mx * (100 + m) / 100); if (v < lo) v = lo; if (cap > 0 && v > cap) v = cap; print v}' "$RD/history.tsv"
}
cap_class() {  # the job class of a command: the first [capacity.classes] pattern it matches, else its first command words
  c=$1
%(classes)s  printf '%%s\n' "$c" | awk '{n = split($0, seg, /&&|;|\|\|/)
    for (s = 1; s <= n; s++) {m = split(seg[s], w, " "); i = 1; wr = 0
      while (i <= m && (w[i] ~ /^[A-Za-z_][A-Za-z0-9_]*=/ || w[i] ~ /^(env|nice|ionice|timeout|nohup|time|exec|command|stdbuf|systemd-run)$/ || (wr && (w[i] ~ /^-/ || w[i] ~ /^[0-9.]+[smhd]?$/)))) {if (w[i] !~ /=/ || w[i] ~ /^-/) wr = 1; i++}
      if (i > m || w[i] ~ /^(cd|export|source|\.|set|true|:|\(|\)|echo|printf)$/) continue
      out = ""; k = 0
      for (; i <= m && k < 3; i++) {x = w[i]; if (x ~ /^-/ || x ~ /=/ || x ~ /^[<>|&]/ || x ~ /^[0-9.:]+$/) break
        if (x ~ /\//) {sub(/.*\//, "", x); out = out (k ? "_" : "") x; k++; break}
        out = out (k ? "_" : "") x; k++}
      gsub(/[^A-Za-z0-9_.+-]/, "", out); if (out != "") {print out; exit}}
    print "job"}'
}
res_sum() {  # live reservations: RJ jobs holding RC cores and RM MB, RA agents holding RAM MB; RL lists them. A reservation
  # whose process is gone is removed (not by a read-only probe). Jobs without one (older scripts, another scheduler) count at CAPMB.
  RJ=0 RC=0 RM=0 RA=0 RAM=0 RL=
  for f in "$RD"/*.res; do
    [ -e "$f" ] || continue
    p= c= m= t= k=; { read -r p c m t k < "$f"; } 2>/dev/null
    case "$p$c$m" in *[!0-9]*|"") continue;; esac
    if ! kill -0 "$p" 2>/dev/null; then [ -n "$CAP_RO" ] || rm -f "$f"; continue; fi
    case $k in agent*) RA=$((RA + 1)); RAM=$((RAM + m));; *) RJ=$((RJ + 1)); RC=$((RC + c)); RM=$((RM + m));; esac
    RL="$RL
res=$p $c $m $t $k ${f##*/}"
  done
  for j in $( { %(jobids)s; } 2>/dev/null); do
    [ -e "$RD/$j.res" ] && continue
    RJ=$((RJ + 1)); RC=$((RC + CPJ)); RM=$((RM + CAPMB)); RL="$RL
res=- $CPJ $CAPMB - untracked $j"
  done
}
cap_measure() {  # PSI (macOS: the kernel's pressure level, warn = 50, critical = 100), LOAD (1 min), DF (GB free in RD)
  if [ "$(uname)" = Darwin ]; then
    case $(sysctl -n kern.memorystatus_vm_pressure_level 2>/dev/null) in 4) PSI=100;; 2) PSI=50;; *) PSI=0;; esac
    LOAD=$(sysctl -n vm.loadavg 2>/dev/null | tr -d '{}' | awk '{print $1}')
  else
    PSI=$(awk '/^some/{sub("avg10=", "", $2); print $2}' /proc/pressure/memory 2>/dev/null); LOAD=$(awk '{print $1}' /proc/loadavg)
  fi
  PSI=${PSI:-0}; LOAD=${LOAD:-0}; DF=$(df -Pk "$RD" 2>/dev/null | awk 'NR==2{print int($4/1048576)}'); DF=${DF:-0}
}
cap_paused() {  # back-pressure: PAUSE is why admission waits (memory PSI over PSIP; load over LOADX x CORES for HOLD s, tracked in RD/overload)
  PAUSE=; nowt=$(date +%%s)
  awk -v a="$PSI" -v b="$PSIP" 'BEGIN {exit !(a + 0 > b + 0)}' && PAUSE="memory PSI avg10 $PSI over $PSIP"
  if awk -v l="$LOAD" -v c="$CORES" -v x="$LOADX" 'BEGIN {exit !(l + 0 > c * x)}'; then
    since= last=; { read -r since last < "$RD/overload"; } 2>/dev/null
    { [ -n "$last" ] && [ $((nowt - last)) -le $((HOLD + 60)) ]; } || since=$nowt   # a gap in the readings starts a new period
    [ -n "$CAP_RO" ] || { echo "$since $nowt" > "$RD/overload.$$" && mv -f "$RD/overload.$$" "$RD/overload"; }
    [ $((nowt - since)) -ge "$HOLD" ] && PAUSE="${PAUSE:+$PAUSE; }load $LOAD over $LOADX x $CORES cores for $((nowt - since)) s"
  else [ -n "$CAP_RO" ] || rm -f "$RD/overload"; fi
}
admit_ok() {  # $1 the job's class. Sets MB (its reservation) and why; true when it may start now
  MB=$(cap_mb "${1:-job}" $CAPMB $CAPMB); res_sum; cap_measure; cap_paused
  why="reserved $RJ job(s): $RC of $CORES cores, $RM MB + agents $RAM MB + this ${1:-job} $MB MB of $MEMCAP MB (RAM - services); PSI $PSI, load $LOAD, disk $DF GB (floor $DISK)${PAUSE:+; PAUSED: $PAUSE}"
  BLK=; [ -n "$PAUSE" ] && BLK="paused"; [ "$DF" -ge "$DISK" ] || BLK="$BLK disk"
  if [ "$RJ" -gt 0 ]; then [ $((RC + CPJ)) -le "$CORES" ] || BLK="$BLK cores"; [ $((RM + RAM + MB)) -le "$MEMCAP" ] || BLK="$BLK memory"; fi
  [ -z "$BLK" ]
}
job_mb() {  # $1 pid, $2 job id: the job's resident memory now, in MB (empty when it cannot be read)
  v=
%(sample)s
  echo "$v"
}
tree_mb() {  # resident memory of process $1 and all its descendants, MB
  ps -A -o pid=,ppid=,rss= | awk -v r="$1" '{pp[$1] = $2; rs[$1] = $3} END {q[r] = 1; do {ch = 0; for (x in pp) if (!(x in q) && (pp[x] in q)) {q[x] = 1; ch = 1}} while (ch); for (x in q) s += rs[x]; print int(s / 1024)}'
}
cap_record() {  # $1 class $2 peak MB $3 seconds $4 exit code: one line of RD/history.tsv (its last 2000 lines are kept)
  [ "${2:-0}" -gt 0 ] 2>/dev/null || return 0
  printf '%%s\t%%s\t%%s\t%%s\t%%s\n' "$(date +%%s)" "$1" "$2" "$3" "$4" >> "$RD/history.tsv"
  [ "$(wc -l < "$RD/history.tsv")" -gt 2400 ] && tail -n 2000 "$RD/history.tsv" > "$RD/history.tsv.$$" && mv -f "$RD/history.tsv.$$" "$RD/history.tsv"
  return 0
}
cap_report() {  # for orch's probe: the sums, the pause, each reservation, the last 300 history lines
  res_sum; cap_measure; cap_paused
  echo "cap_rj=$RJ"; echo "cap_rc=$RC"; echo "cap_rm=$RM"; echo "cap_ra=$RA"; echo "cap_ram=$RAM"; echo "cap_pause=$PAUSE"; echo "cap_psi=$PSI"
  admit_ok job >/dev/null 2>&1; echo "cap_admit=${BLK:-yes}"   # the admission's own verdict for one more job now (yes, or what blocks it)
  [ -n "$RL" ] && printf '%%s\n' "$RL" | sed '/^$/d'
  [ -f "$RD/history.tsv" ] && tail -n 300 "$RD/history.tsv" | sed 's/^/hist=/'
  true
}
'''

def cap_lib(cfg, hn, h):
    """runs/cap.sh for host h: the rule above with the host's numbers, its [capacity.classes], and how its jobs are seen
    (systemd scopes orch-<jid>.scope; podman containers by container.name_prefixes; the Mac: process trees)."""
    n = cap_nums(cfg, h); pod = h.get("runner") == "podman"
    if pod:
        pre = h.get("container", {}).get("name_prefixes", ["orch-run-"])
        jobids = "podman ps --format '{{.Names}}' | awk '" + " ".join(
            f"/^{re.escape(x)}/ {{" + ("sub(/^orch-run-/, \"\"); " if x == "orch-run-" else "") + "print; next}" for x in pre) + "'"
        sample = ('  i=$(podman ps -q --no-trunc --filter name=orch-run-$2 2>/dev/null | head -1)\n'
                  '  [ -n "$i" ] && v=$(awk \'/^anon /{print int($2/1048576)}\' "$US/libpod-$i.scope/memory.stat" 2>/dev/null)')
    elif h.get("local"):
        jobids, sample = "true", '  v=$(tree_mb "$1")'
    else:
        jobids = "ls -d $AS/orch-*.scope | sed 's#.*/orch-##; s#[.]scope$##'"
        sample = ('  v=$(awk \'/^anon /{print int($2/1048576)}\' "$AS/orch-$2.scope/memory.stat" 2>/dev/null)\n'
                  '  [ -n "$v" ] || v=$(tree_mb "$1")')
    cls = "".join(f"  printf '%s\\n' \"$c\" | grep -Eq {shlex.quote(rx)} && {{ echo {shlex.quote(k)}; return; }}\n"
                  for k, rx in (cfg.capc.get("classes", {}) if cfg else {}).items())
    return CAP_LIB % {**n, "name": hn, "psip": capv(cfg, h, "psi_pause"), "loadx": capv(cfg, h, "load_pause"), "hold": int(capv(cfg, h, "hold_s")),
                      "disk": int(capv(cfg, h, "min_disk_gb")), "jobids": jobids, "sample": sample, "classes": cls}

def class_mb(hist, cls, d, cap, hn=5, margin=15):
    """The reservation of a job class from history lines (time, class, peak MB, secs, rc): the same rule as cap_mb in runs/cap.sh."""
    ag = cls == "agent"
    pk = sorted([int(f[2]) for f in (l.split("\t") for l in hist) if len(f) >= 3 and f[1] == cls and f[2].isdigit() and int(f[2]) > 0][-(hn * 3 if ag else hn):])
    if not pk: return d
    v = max(128 if ag else 256, int((pk[(len(pk) - 1) // 2] if ag else pk[-1]) * (100 + margin) / 100))
    return min(v, cap) if cap > 0 else v

def class_secs(hist, cls):
    """Median run time (s) of a job class from history lines, None without history."""
    s = sorted(int(f[3]) for f in (l.split("\t") for l in hist) if len(f) >= 4 and f[1] == cls and f[3].isdigit())
    return s[len(s) // 2] if s else None

def tree_rss_mb(pid):
    """Resident memory (MB) of process pid and its descendants (one ps call)."""
    rc, o, e = sh(["ps", "-A", "-o", "pid=,ppid=,rss="], timeout=10)
    pp, rs = {}, {}
    for l in o.splitlines():
        f = l.split()
        if len(f) == 3 and f[0].isdigit(): pp[int(f[0])] = int(f[1]); rs[int(f[0])] = int(f[2])
    q, ch = {pid}, True
    while ch:
        ch = False
        for x, y in pp.items():
            if y in q and x not in q: q.add(x); ch = True
    return sum(rs.get(x, 0) for x in q) // 1024

def record_history(rd, cls, peak, secs, rc):
    """One line of <runs>/history.tsv (the format cap_record writes)."""
    with open(Path(rd) / "history.tsv", "a") as f: f.write(f"{int(now())}\t{cls}\t{int(peak)}\t{int(secs)}\t{rc}\n")

def host_cap(cfg, n, p, units):
    """The host's capacity now, from its probe (the numbers the admission sees) and the open units:
    slots: build jobs that fit when nothing runs; free: further jobs that fit now; agents: open units whose builds run here."""
    h = cfg.hosts[n]; c = cap_nums(cfg, h); hist = p.get("hist", [])
    # a typical job here: the largest reservation of the classes run lately (job_gb when nothing is recorded yet)
    recent = {l.split("\t")[1] for l in hist[-50:] if l.count("\t") >= 2}
    jmb = max([class_mb(hist, k, c["capmb"], c["capmb"], c["hn"], c["margin"]) for k in recent] or [c["capmb"]])
    amb = class_mb(hist, "agent", c["agmb"], 0, c["hn"], c["margin"])
    rj, rc, rm, ra, ram = (int(fl(p.get(k))) for k in ("cap_rj", "cap_rc", "cap_rm", "cap_ra", "cap_ram"))
    t = list(((p.get("pueue") or {}).get("tasks") or {}).values())
    qd = sum(1 for x in t if x.get("group") in ("jobs", "gates") and "Queued" in str(x.get("status")))
    qd += int(fl(p.get("wait_jobs"))) + int(fl(p.get("wait_gates")))
    here = [u for u in units if (u.get("build") or u.get("host")) == n and u.get("state") not in ("done", "failed", "gone", "idle")]
    on = [u for u in units if u.get("host") == n and u.get("state") not in ("done", "failed", "gone", "idle", "parked")]
    agents_mb = max(ram, len(on) * amb)   # every open agent on the host holds the agent figure (reservation files of api agents at least)
    slots = max(1, min(c["cores"] // c["cpj"], (c["memcap"] - agents_mb) // max(jmb, 1)))
    pause = p.get("cap_pause", "")
    free = 0 if pause else max(0, min((c["cores"] - rc) // c["cpj"], (c["memcap"] - rm - agents_mb) // max(jmb, 1)))
    if rj == 0 and not pause: free = max(free, 1)
    return {**c, "jmb": jmb, "amb": amb, "rj": rj, "rc": rc, "rm": rm, "ra": ra, "agents_mb": agents_mb, "queued": qd, "slots": slots,
            "free": free, "pause": pause, "agents": [u["name"] for u in here], "on": len(on), "hist": hist, "res": p.get("res", [])}

def next_free(hc):
    """When a build reservation is expected to free: the earliest (start + median run time of its class) of the running jobs."""
    ends = []
    for r in hc["res"]:
        f = r.split()
        if len(f) >= 5 and f[3].isdigit():
            s = class_secs(hc["hist"], f[4])
            if s: ends.append(int(f[3]) + s)
    return min(ends) if ends else None

def build_room(cfg, n, hc, kind="implement"):
    """(ok, why) for one more agent whose builds and tests run on host n (orch-fixes8 item 3): it needs a free build reservation
    there (agents for the host < its build slots), or a bounded queue position: at most one queued job per running job, and
    no more agents than twice the slots. A paused host takes none. Refusals say when to expect room."""
    if kind in cfg.capc.get("no_build_kinds", []): return True, "no builds"
    a = len(hc["agents"]); s = hc["slots"]
    if hc["pause"]: return False, f"{n} admission paused ({hc['pause']}); retry when it clears (running jobs are not killed)"
    if a < s: return True, f"build reservation {a + 1} of {s} on {n}"
    used = max(hc["queued"], a - s)   # queue positions in use: jobs queued now, or agents past the slots (each may queue one)
    if a < 2 * s and used < hc["rj"]: return True, f"queue position on {n} ({used} of {hc['rj']} in use: one queued job per running job)"
    nf = next_free(hc)
    when = (f"a build slot should free about {ts(nf)}" if nf and nf > now() else "a build slot frees when a running job ends") + \
           (f", or when one of {', '.join(hc['agents'][:4])} closes" if hc["agents"] else "")
    return False, (f"{n} build capacity full: {a} agent(s) for {s} build slot(s) + {s} queue position(s); {hc['rj']} running, "
                   f"{hc['queued']} queued; {when}")

# ---------------------------------------------------------------- the API ledger (orch owns it) and the secret store
# One TSV per provider ([providers.<p>] ledger), one row per event:  ts  unit  running|<cost>  <budget>|done rc=<x>  <run id>.
# Every run id has exactly one `running` row (its budget, written when the budget is reserved) and at most one `done` row
# (its cost; the whole budget when the run never reported one). Every write takes the ledger's lock (<ledger>.lock, an fcntl
# lock: the lock zsh's `zsystem flock` takes too) and is idempotent: a second running or done row for a run id is never
# written, so a retry, a re-run or a looping launcher cannot duplicate rows (orch-fixes7: a launcher edited while it ran
# looped and appended ~49,000 done rows; the cap check summed them all). Spend is computed per run id: its done cost, or its
# budget while it runs. A malformed ledger refuses every new run until `orch ledger repair`.
NUM = re.compile(r"^-?\d+(\.\d+)?([eE][-+]?\d+)?$")

class Locked:
    """The ledger's lock: `with Locked(path):` holds an exclusive fcntl lock on <path>.lock."""
    def __init__(self, path): self.p = str(path) + ".lock"
    def __enter__(self):
        import fcntl
        Path(self.p).parent.mkdir(parents=True, exist_ok=True)
        self.f = open(self.p, "a"); fcntl.lockf(self.f, fcntl.LOCK_EX); return self
    def __exit__(self, *e): self.f.close()

def ledger_path(cfg, pv): return cfg.root / pv["ledger"]

def ledger_parse(text):
    """(runs, problems, notes). runs: {run id: {unit, running: [line numbers], done: [...], budget, cost}}. problems make the
    ledger malformed (a launch is refused); notes are only reported."""
    runs, bad, notes = {}, [], []
    for i, l in enumerate(text.splitlines(), 1):
        if not l.strip(): continue
        f = l.split("\t")
        if len(f) != 5 or not f[1].strip() or not f[4].strip():
            bad.append(f"line {i}: {len(f)} field(s), want 5 (ts, unit, running|cost, budget|done rc=, run id): {l[:80]!r}"); continue
        r = runs.setdefault(f[4], {"unit": f[1], "running": [], "done": [], "budget": None, "cost": None, "ts": f[0]})
        if r["unit"] != f[1]: bad.append(f"line {i}: run id {f[4]} belongs to {r['unit']}, not {f[1]}"); continue
        if f[2] == "running":
            if not NUM.match(f[3].strip()): bad.append(f"line {i}: running row without a numeric budget: {f[3][:20]!r}"); continue
            r["running"].append(i)
            if r["budget"] is None: r["budget"] = float(f[3])
        elif NUM.match(f[2].strip()) and f[3].startswith("done"):
            r["done"].append(i)
            if r["cost"] is None: r["cost"] = float(f[2])
        else: bad.append(f"line {i}: neither a running row nor a done row: {l[:80]!r}")
    for k, r in runs.items():
        if len(r["running"]) > 1: bad.append(f"run {k} ({r['unit']}): {len(r['running'])} running rows (lines {', '.join(map(str, r['running'][:5]))}{'...' if len(r['running']) > 5 else ''})")
        if len(r["done"]) > 1: bad.append(f"run {k} ({r['unit']}): {len(r['done'])} done rows (lines {', '.join(map(str, r['done'][:5]))}{'...' if len(r['done']) > 5 else ''})")
        if r["done"] and not r["running"]: notes.append(f"run {k} ({r['unit']}): a done row without a running row (counted)")
    return runs, bad, notes

def ledger_read(cfg, pv):
    try: return ledger_parse(ledger_path(cfg, pv).read_text())
    except FileNotFoundError: return {}, [], []

def spend(runs):
    """Committed dollars: per run id, its done cost, or its budget while it runs."""
    return sum(r["cost"] if r["done"] else (r["budget"] or 0.0) for r in runs.values())

def committed(cfg, pv): return spend(ledger_read(cfg, pv)[0])

def ledger_append(cfg, pv, row):
    """One row, appended with a single write to an O_APPEND descriptor (the caller holds the lock)."""
    p = ledger_path(cfg, pv); p.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(p, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
    try: os.write(fd, ("\t".join(map(str, row)) + "\n").encode())
    finally: os.close(fd)

def tstamp(): return time.strftime("%Y-%m-%d %H:%M:%S")

def reserve_budget(cfg, mc, name, budget, run=None):
    """Under the ledger's lock: refuse when the ledger is malformed or the budget would pass the cap, else write the run's one
    running row. Idempotent: a run id that already has its running row is returned as it is. Returns the run id."""
    pv = cfg.prov[mc["provider"]]; run = run or f"{name}.{os.getpid()}.{int(now())}"
    if DRY: return run
    with Locked(ledger_path(cfg, pv)):
        runs, bad, _ = ledger_read(cfg, pv)
        if bad: raise Err(f"refused: the {mc['provider']} ledger {pv['ledger']} is malformed ({bad[0]}; {len(bad)} problem(s)): run orch ledger check, then orch ledger repair")
        r = runs.get(run)
        if r and r["done"]: raise Err(f"refused: run {run} is already finished (done row at line {r['done'][0]}); a re-run gets a new run id")
        if r and r["running"]: return run
        if "cap_usd" in pv:
            c = spend(runs)
            if c + budget > pv["cap_usd"]: raise Err(f"refused: ${c:.2f} committed + ${budget} would pass the ${pv['cap_usd']} cap of {mc['provider']}")
        ledger_append(cfg, pv, [tstamp(), name, "running", budget, run])
    return run

def ledger_done(cfg, pv, run, name, cost, rc):
    """Write the run's one done row (idempotent: nothing when it already has one). Returns True when written."""
    if DRY: return False
    with Locked(ledger_path(cfg, pv)):
        r = ledger_read(cfg, pv)[0].get(run)
        if r and r["done"]: return False
        ledger_append(cfg, pv, [tstamp(), name, cost, f"done rc={rc}", run])
    return True

def run_cost(path, budget):
    """The cost an API run reported in its json output, else its whole budget (a run stopped before it wrote its cost is
    charged everything, so the cap never undercounts)."""
    try: c = json.loads(Path(path).read_text()).get("total_cost_usd")
    except Exception: c = None
    return (float(c), True) if isinstance(c, (int, float)) else (float(budget or 0), False)

def settle_run(cfg, u, rc):
    """Close an API unit's ledger run (its done row) when it ended without writing one: stopped, killed or closed."""
    mc = cfg.models.get(u.get("model"), {}); pv = cfg.prov.get(mc.get("provider"), {})
    if mc.get("kind") != "api" or not u.get("run") or "ledger" not in pv: return
    cost, _ = run_cost(cfg.p("out", "out") / u["name"] / "api.json", u.get("budget") or pv.get("budget_per_unit", 0))
    if ledger_done(cfg, pv, u["run"], u["name"], cost, rc): say(f"ledger: run {u['run']} closed at ${cost:.2f} ({rc})")

def read_secret(pv):
    """(variable, value) of a provider's API key from the configured secret store, never printed or written anywhere:
    key_keychain (macOS keychain item, `security find-generic-password -s <item> -w`), else key_file (lines VAR=value; refused
    unless only its owner can read it, mode 600)."""
    var = pv.get("key_env", "ANTHROPIC_API_KEY"); tried = []
    if pv.get("key_keychain") and sys.platform == "darwin":
        rc, o, e = sh(["security", "find-generic-password", "-s", pv["key_keychain"], "-w"])
        if rc == 0 and o.strip(): return var, o.strip()
        tried.append(f"keychain item {pv['key_keychain']} (not found)")
    if pv.get("key_file"):
        p = Path(os.path.expanduser(pv["key_file"]))
        try: st = p.stat()
        except OSError: tried.append(f"{p} (missing)")
        else:
            if st.st_mode & 0o077: raise Err(f"{p} can be read by others (mode {oct(st.st_mode & 0o777)}): chmod 600 {p}")
            for l in p.read_text().splitlines():
                k, _, v = l.strip().removeprefix("export ").partition("=")
                if k.strip() == var and v.strip(): return var, v.strip().strip("'\"")
            tried.append(f"{p} (no {var}=)")
    raise Err(f"no API key: " + ("; ".join(tried) or "set key_keychain (macOS) or key_file (mode 600) in the provider's orch.toml table"))

def model_ok(cfg, m):
    c = cfg.models.get(m)
    if not c: return False, "unknown model"
    pv = cfg.prov.get(c["provider"], {})
    if not pv.get("enabled"): return False, f"provider {c['provider']} disabled"
    if "ledger" in pv:
        runs, bad, _ = ledger_read(cfg, pv)
        if bad: return False, f"{c['provider']} ledger malformed ({len(bad)} problem(s); orch ledger check)"
        if "cap_usd" in pv:
            left = pv["cap_usd"] - spend(runs)
            if left < pv.get("budget_per_unit", 0): return False, f"{c['provider']} budget left ${left:.0f}"
    return True, ""

def cmd_ledger(cfg, a):
    """orch ledger check: every provider ledger, exit 1 when one is malformed. orch ledger repair: keep the first running row
    and the first done row of each run id, drop rows that cannot be parsed, after a backup <ledger>.bak-<time>; the file is
    replaced by write-then-rename under the lock."""
    pvs = [(n, pv) for n, pv in cfg.prov.items() if "ledger" in pv and (not a.provider or n == a.provider)]
    if not pvs: raise Err("no provider has a ledger in orch.toml")
    worst = 0
    for n, pv in pvs:
        p = ledger_path(cfg, pv)
        if a.action == "check":
            runs, bad, notes = ledger_read(cfg, pv)
            say(f"{n}: {p}: {sum(len(r['running']) + len(r['done']) for r in runs.values())} rows, {len(runs)} runs, "
                f"${spend(runs):.2f} committed" + (f" of ${pv['cap_usd']}" if "cap_usd" in pv else "") + (f"; MALFORMED, {len(bad)} problem(s):" if bad else "; valid"))
            for x in bad[:20] + notes[:10]: say("  " + x)
            if len(bad) > 20: say(f"  ... {len(bad) - 20} more")
            worst = max(worst, 1 if bad else 0); continue
        if DRY: say(f"+ back up {p}, keep the first running and done row per run id, write-then-rename"); continue
        with Locked(p):
            for _ in range(5):
                try: raw = p.read_bytes()
                except FileNotFoundError: say(f"{n}: no ledger yet"); break
                keep, seen, dropped = [], set(), 0
                for l in raw.decode(errors="replace").splitlines():
                    f = l.split("\t")
                    ok = len(f) == 5 and f[1].strip() and f[4].strip() and ((f[2] == "running" and NUM.match(f[3].strip())) or (NUM.match(f[2].strip()) and f[3].startswith("done")))
                    k = (f[4], "running" if ok and f[2] == "running" else "done") if ok else None
                    if not ok or k in seen: dropped += bool(l.strip()); continue
                    seen.add(k); keep.append(l)
                bak = p.with_name(p.name + time.strftime(".bak-%Y%m%d-%H%M%S")); bak.write_bytes(raw)
                tmp = p.with_name(f".{p.name}.{os.getpid()}.tmp"); tmp.write_text("".join(x + "\n" for x in keep))
                if p.stat().st_size != len(raw): tmp.unlink(); continue   # an unlocked writer appended meanwhile: read again
                os.replace(tmp, p)
                say(f"{n}: repaired {p}: kept {len(keep)} rows, dropped {dropped}; backup {bak}")
                break
            else: raise Err(f"{p} kept changing while it was repaired: stop the writer and retry")
        runs, bad, _ = ledger_read(cfg, pv)
        if bad: say(f"  still malformed: {bad[0]}"); worst = 1
    return worst

# ---------------------------------------------------------------- units
def unit_state(u, ps, agents):
    """working | idle | blocked | queued | done | failed | gone, from the live source the unit runs in."""
    via = u.get("via")
    if via == "herdr":
        a = agents.get(u["name"])
        return a.get("agent_status", "unknown") if a else "gone"
    p = ps.get(u.get("host"), {})
    if not p.get("ok"): return "unknown"
    if via == "tmux": return "working" if f"orch-{u['name']}" in p.get("tmux", []) else "gone"
    if via == "pueue":
        t = ((p.get("pueue") or {}).get("tasks") or {}).get(str(u.get("task")))
        if not t: return "gone"
        s = t.get("status"); k = s if isinstance(s, str) else next(iter(s), "")
        if k == "Done": return "done" if s["Done"].get("result") == "Success" or s["Done"] == "Success" else "failed"
        return {"Queued": "queued", "Running": "working"}.get(k, k.lower())
    return "unknown"

def verdict(cfg, u):
    """The unit's final VERDICT line, from the report it writes (a resumed unit: its original report, report_path). A resumed
    report still holds the earlier run's verdict, so only a verdict written after the resume started counts, and a line 1
    that is still PENDING means not finished."""
    p = report_path(cfg, u)
    try: t = p.read_text().splitlines()
    except OSError: return None
    if u.get("resume") and (p.stat().st_mtime < u.get("started", 0) or (t and "PENDING" in t[0])): return None
    return next((l for l in reversed(t) if l.startswith("VERDICT:") and "PENDING" not in l), None)   # PENDING is not a verdict

def herdr_agents(cfg):
    r = herdr("agent", "list")
    return {a.get("name") or a["pane_id"]: a for a in (r or {}).get("agents", [])} if r else {}

def ws_id(cfg, create=False):
    lab = cfg.c.get("herdr", {}).get("workspace", cfg.name)
    r = herdr("workspace", "list") or {}
    for w in r.get("workspaces", []):
        if w.get("label") == lab: return w["workspace_id"]
    if create and not DRY:
        r = herdr("workspace", "create", "--label", lab, "--no-focus") or {}
        return r.get("workspace", {}).get("workspace_id")

# ---------------------------------------------------------------- check
def board_script(cfg):
    """The message board script: paths.board (a project's own), else the board.sh shipped next to orch.py (orch-swarm item 6)."""
    return cfg.p("board") if cfg.paths.get("board") else ORCH_SELF.parent / "board.sh"
def board_dir(cfg): return cfg.root / cfg.paths.get("board_dir", "board")
def board(cfg, *args, env=None, timeout=25):
    """Run the board script with BOARD_DIR set (the shipped board keeps its files there; a project's own script may ignore it)."""
    return sh([str(board_script(cfg)), *args], env={"BOARD_DIR": str(board_dir(cfg)), **(env or {})}, timeout=timeout)

def board_rows(cfg):
    """Every open card on the board: {name: {"state", "silent", "gone", "text"}} (audit H8: all cards, not only orch's units)."""
    rc, o, e = board(cfg, "summary", env={"BOARD_SILENT_MIN": str(cfg.silent // 60)})
    rows = {}
    for l in (o.splitlines()[1:] if rc == 0 else []):
        f = l.split()
        if len(f) < 3 or l[:1] in (" ", "=", "\t"): continue   # the shipped board's group headings and its needs-answer lines
        rows[f[0]] = {"state": f[2], "silent": bool(re.search(r"\bSILENT \d+m", l)), "gone": "GONE" in l,
                      "text": re.sub(r"\s+", " ", l.split(None, 4)[-1] if len(f) > 4 else "")[:140]}
    return rows

def board_questions(cfg):
    """Open questions [(id, agent, asked, text)] from the shipped board (board.sh questions); None when the board script has no
    question ids (a project's own script: its question cards are judged by state)."""
    rc, o, e = board(cfg, "questions")
    if rc: return None
    return [tuple((l.split("\t") + ["", "", ""])[:4]) for l in o.splitlines() if l.strip()]

def learned_posts(cfg):
    """[(id <agent>:<n>, text)] of every learned post on the board's log (n counts that agent's learned posts, oldest first)."""
    try: lines = (board_dir(cfg) / "log.md").read_text(errors="replace").splitlines()
    except OSError: return []
    n, out = {}, []
    for l in lines:
        m = re.match(r"^\S+ \S+ ([A-Za-z0-9._-]+) learned: (.*)$", l)
        if m: n[m.group(1)] = n.get(m.group(1), 0) + 1; out.append((f"{m.group(1)}:{n[m.group(1)]}", m.group(2)))
    return out

def board_findings(cfg, names):
    """question:<id> (stays until answered), learned:<agent>:<n> (until remembered or rejected)."""
    F = []
    for q, ag, at, tx in board_questions(cfg) or []:
        try: age = int((now() - time.mktime(time.strptime(at, "%Y-%m-%d %H:%M"))) / 60)
        except ValueError: age = 0
        F.append((f"question:{q}", f"{ag}{'' if ag in names else ' (not a unit)'} asks [{q}] ({age} min): {tx[:160]}; check MEMORY.md (orch memory), then board.sh answer {q} <text>"))
    done = cfg.jget("learned.json")
    F += [(f"learned:{i}", f"{i.split(':')[0]} proposes for the session memory: {t[:160]}; orch remember --fact|--decision|--pitfall <text> --learned {i}, or orch learned --reject {i}")
          for i, t in learned_posts(cfg) if i not in done]
    return F

def cmd_learned(cfg, a):
    if a.reject:
        refuse_agent("orch learned --reject")
        if not any(i == a.reject.removeprefix("learned:") for i, _ in learned_posts(cfg)): raise Err(f"no learned post {a.reject}")
        learned_mark(cfg, a.reject, "rejected" + (f": {a.why}" if a.why else "")); say(f"rejected {a.reject}"); return
    done = cfg.jget("learned.json")
    for i, t in learned_posts(cfg): say(f"{i:24} {done.get(i, {}).get('how', 'open'):10} {t}")

def board_upkeep(cfg, units):
    """The shipped board's own files (a writer only): .master (this machine's host name), .hosts (other hosts from orch.toml,
    for sync and rule) and .notify (a new question or block runs `orch watch --alert` at once); cards of closed units archived."""
    if cfg.ro or DRY or cfg.paths.get("board"): return
    bd = board_dir(cfg); bd.mkdir(exist_ok=True)
    me = next((n for n, h in cfg.hosts.items() if h.get("local")), "local")
    if not (bd / ".master").exists(): (bd / ".master").write_text(me + "\n")
    hosts = "".join(f"{n} {h['ssh']} {h['root']}\n" for n, h in cfg.hosts.items() if not h.get("local") and h.get("ssh") and h.get("root"))
    if not (bd / ".hosts").exists() or (bd / ".hosts").read_text() != hosts: atomic_write(bd / ".hosts", hosts)
    nt = f"cd {shlex.quote(str(cfg.root))} && ORCH_ROOT={shlex.quote(str(cfg.root))} {shlex.quote(sys.executable)} {shlex.quote(str(ORCH_SELF))} watch --alert\n"
    if not (bd / ".notify").exists() or (bd / ".notify").read_text() != nt: atomic_write(bd / ".notify", nt)
    names = {u["name"] for u in units}; au = all_units(cfg)
    for c in (bd / "agents").glob("*.md") if (bd / "agents").is_dir() else []:
        if c.stem not in names and au.get(c.stem, {}).get("status") == "closed": board(cfg, "close", c.stem)

def board_alerts(cfg, log):
    """Prompt the orchestrator at once on a new board question or block (orch-swarm item 6): each is told once."""
    qs = board_questions(cfg)
    items = [(f"q:{q}", f"QUESTION [{q}] from {ag}: {tx[:200]}") for q, ag, at, tx in (qs or [])]
    items += [(f"b:{c}:{hashlib.md5(r['text'].encode()).hexdigest()[:8]}", f"BLOCKED {c}: {r['text'][:200]}") for c, r in board_rows(cfg).items()
              if r["state"] == "blocked" or (qs is None and r["state"] == "question")]
    seen = cfg.jget("alerted.json"); new = [(k, t) for k, t in items if k not in seen]
    if not new: return None
    pane = cfg.f("pane").read_text().strip() if cfg.f("pane").exists() else ""
    msg = (ORCH_MARK + "Board needs you now: " + " | ".join(t for _, t in new) + ". Check MEMORY.md (orch memory) first; answer with "
           "board.sh answer <id> <text> (a block: board.sh direct <agent> <text>); orch remember what every agent should know.")
    if not pane or herdr("agent", "prompt", pane, msg) is None: log(f"board alert not delivered (no orchestrator pane): {msg[:300]}"); return None
    log(f"board alert: {msg[:600]}"); cfg.jput("alerted.json", {**{k: v for k, v in seen.items() if now() - v < 7 * 86400}, **{k: now() for k, _ in new}})
    return msg

def gate_findings(cfg, hs=None):
    """Failed gates of the last 12 h: only each gate's latest result counts, and none while a newer run of that gate is queued or
    running (a superseded failure never comes back after its ack expires)."""
    try: lines = cfg.p("gate_log").read_text().splitlines()[-200:]
    except OSError: return []
    busy = {(t.get("label") or "")[5:] for p in (hs or {}).values() for t in ((p.get("pueue") or {}).get("tasks") or {}).values()
            if (t.get("label") or "").startswith("gate:") and any(k in str(t.get("status")) for k in ("Queued", "Running"))}
    latest = {}
    for l in lines:
        if "RESULT:" in l and len(l) > 20: latest[l[20:].split()[0]] = l
    fails, cut = [], now() - 12 * 3600
    for n, l in latest.items():
        if "RESULT: FAIL" not in l or n in busy: continue
        try:
            if time.mktime(time.strptime(l[:19], "%Y-%m-%d %H:%M:%S")) < cut: continue
        except ValueError: continue
        fails.append((l[:19], n, [t.split("=")[0] for t in l.split() if re.match(r"EXIT_\w+=(?!0$)", t)]))
    out = [(f"gate:{n}@{t[11:]}", f"gate {n} FAILED at {t[11:]} ({' '.join(x[5:] for x in k[:4])}{'...' if len(k) > 4 else ''}); re-queue or classify")
           for t, n, k in fails]
    cnt = {}
    for t, n, ks in fails:
        for k in set(ks): cnt.setdefault(k, set()).add(n)
    out += [(f"gate-common:{k}", f"{k[5:]} fails in {len(v)} gates ({', '.join(sorted(v)[:3])}): suspect the test or fixture, not the units")
            for k, v in cnt.items() if len(v) >= 2]
    return out

def handoff_path(cfg): return cfg.f("HANDOFF.md")

def notes_state(cfg):
    """Updated-time of the notes part: tracked by hash, so regenerating the live part never refreshes it."""
    t = handoff_path(cfg).read_text() if handoff_path(cfg).exists() else ""
    notes = t.split(LE, 1)[-1] if LE in t else NOTES0
    h = hashlib.md5(notes.encode()).hexdigest(); s = cfg.jget("notes.json")
    if s.get("hash") != h: s = {"hash": h, "ts": now() if not cfg.ro else s.get("ts", now())}; cfg.jput("notes.json", s)
    return s["ts"], notes.count("\n")

def handoff_stale(cfg, running):
    t, lines = notes_state(cfg); r = []
    if t < cfg.mtime("changed") or (running and now() - t > cfg.cycle): r.append("handoff stale: update the Orchestrator notes in .orch/HANDOFF.md")
    if lines > 150: r.append(f"handoff notes are {lines} lines; move old ones to .orch/history.md")
    return r

def ready_work(cfg):
    """Ready work items in beads: not units (launched work), not orch's decision log, not owner instructions (audit H7)."""
    skip = {"unit", "orch-log", "instruction", "backlog"}   # backlog items have their own finding (idle with backlog)
    return [i for i in Beads(cfg).run("ready") if not skip & set(i.get("labels") or [])
            and not str(i.get("title", "")).startswith(("unit:", "orch:", "instr:"))]

TEST_RX = re.compile(r"\bcargo(-\w+)? (test|nextest|build|clippy|bench)\b|\bpytest\b|\b(npm|pnpm) (run )?test\b|\bxcodebuild\b.*\btest\b")

VIA_LANE = re.compile(r"orch(\.py)? (run|gate)\b|\bssh\b|\bpueue\b|\bgrep\b|\brg\b")   # plus paths.lane_scripts (project wrappers)

def via_lane(cfg, c):
    return bool(VIA_LANE.search(c)) or any(os.path.basename(x) in c for x in cfg.paths.get("lane_scripts", []))

def secs(et):
    d, _, r = et.rpartition("-"); p = [int(x) for x in r.split(":")]
    while len(p) < 3: p.insert(0, 0)
    return (int(d) if d else 0) * 86400 + p[0] * 3600 + p[1] * 60 + p[2]

def proc_findings(cfg, ps_text=None):
    """On this machine (the Mac): CPU burners an agent started (busy over 10 min, under an agent or orphaned from one), and test
    or build runs outside the pueue lanes (orch run / orch gate put them in a lane). ps_text: a ps table (tests)."""
    o = ps_text if ps_text is not None else sh(["ps", "-Aww", "-o", "pid=,ppid=,pgid=,pcpu=,etime=,command="], timeout=10)[1]
    t, pg = {}, {}
    for l in o.splitlines():
        f = l.split(None, 5)
        if len(f) == 6 and f[0].isdigit(): t[int(f[0])] = (int(f[1]), fl(f[3]), f[4], f[5]); pg[int(f[0])] = int(f[2])
    up = lambda p: [q for q in ancestors({k: (v[0],) for k, v in t.items()}, p)[1:]]
    kids = {}
    for k, v in t.items(): kids.setdefault(v[0], []).append(k)
    def lane_below(p, depth=0):   # a descendant runs orch run/gate: the build goes through a lane (a shim, a wrapper script)
        return depth < 6 and any(re.search(r"orch(\.py)? (run|gate)\b", t[c][3]) or lane_below(c, depth + 1) for c in kids.get(p, []))
    launchers = {os.path.basename(m["launcher"]) for m in cfg.models.values() if m.get("launcher")}   # older project launchers
    F = []
    for p, (pp, cpu, et, c) in t.items():
        if AGENT_RX.search(c) or "pueued" in c: continue
        anc = up(p); agent = next((q for q in anc if AGENT_RX.search(t[q][3]) or "orch.py api-run" in t[q][3] or any(x in t[q][3] for x in launchers)), None)
        lane = any("pueued" in t[q][3] for q in anc)
        if cpu >= 80 and secs(et) >= 600 and not lane and (agent or pp == 1) and not re.search(r"^/(System|usr/libexec|usr/sbin)|\.app/", c):
            F.append((f"burner:{p}", f"CPU burner pid {p} ({cpu:.0f}% for {et}) {'started by agent pid ' + str(agent) if agent else 'orphaned'}: {c[:70]}"))
            cfg._viol.append({"key": f"burner:{p}", "kind": "burner", "host": next((n for n, h in cfg.hosts.items() if h.get("local")), "local"),
                              "pid": p, "pgid": pg.get(p, 0), "agent_pgid": pg.get(agent or -1), "unit": env_unit(p)})
        if TEST_RX.search(c) and not lane and not via_lane(cfg, c) and not any(TEST_RX.search(t[q][3]) or via_lane(cfg, t[q][3]) for q in anc) and not lane_below(p):
            F.append((f"localtest:{p}", f"test/build run on this machine outside the pueue lanes (pid {p}, {et}): {c[:70]}; use orch run"))
    return F

def env_unit(pid):
    """ORCH_UNIT of a local process (macOS ps -E appends the environment after the command), or None."""
    rc, o, e = sh(["ps", "-Eww", "-p", str(pid), "-o", "command="], timeout=10)
    rc2, c, e2 = sh(["ps", "-ww", "-p", str(pid), "-o", "command="], timeout=10)
    m = re.search(r"(?:^|\s)ORCH_UNIT=(\S+)", o[len(c.rstrip("\n")):] if o.startswith(c.rstrip("\n")) else "")
    return m.group(1) if m else None

# Stop a process group after one warning (register item 23): TERM the group, KILL what is left after 5 s. When the group also
# holds an agent (claude, codex) or pueued, only the process and its descendants are stopped, never the agent.
STOP_GROUP = r'''p=%(pid)d g=%(pgid)d
kids() { ps -A -o pid=,ppid= | awk -v r=$p '{pp[$1] = $2} END {q[r] = 1; do {c = 0; for (x in pp) if (!(x in q) && (pp[x] in q)) {q[x] = 1; c = 1}} while (c); for (x in q) print x}'; }
if [ "$g" -gt 1 ] && ! ps -A -o pgid=,args= | awk -v g=$g '$1 == g' | grep -Eq '(^|/)(claude|codex)( |$)|node .*(claude|codex)|pueued'; then
  kill -TERM -$g 2>/dev/null; sleep 5; kill -KILL -$g 2>/dev/null; echo "group $g stopped"
else
  t=$(kids); kill -TERM $t 2>/dev/null; sleep 5; kill -KILL $t 2>/dev/null; echo "process $p and its children stopped (group $g holds the agent)"
fi'''

def enforce(cfg, F):
    """Warn, then stop (orch-fixes8; register items 22, 23). The first time a violation is seen its unit gets a board direction;
    when it is still there [enforce] grace_min (default 5) later, a CPU burner's process group is stopped (stop_burners,
    default true) and a remote direct build's (stop_direct, default false: flagged and warned only). Running lane jobs are
    never touched. Only the registered orchestrator's check and the watcher act; anyone else only reports."""
    ec = cfg.c.get("enforce", {}); grace = ec.get("grace_min", 5) * 60; st = cfg.jget("enforce.json"); new = {}; notes = {}
    for v in getattr(cfg, "_viol", []):
        s = st.get(v["key"]) or {}; stop_ok = ec.get("stop_burners", True) if v["kind"] == "burner" else ec.get("stop_direct", False)
        u = v.get("unit")
        if not s.get("warned"):
            if u: board(cfg, "direct", u, f"orch: your process {v['pid']} ({v['kind']}) on {v['host']} breaks the lane rule: "
                      + ("stop it now and run builds and tests through the lane" if v["kind"] == "direct" else "stop this CPU burner now") +
                      (f"; orch stops it at {ts(now() + grace)}" if stop_ok else ""))
            s = {"warned": now(), "unit": u}; notes[v["key"]] = f"warned {u or 'no unit'} at {ts()}" + (f"; stops at {ts(now() + grace)}" if stop_ok else "")
        elif stop_ok and not s.get("stopped") and now() - s["warned"] >= grace:
            h = cfg.hosts[v["host"]]
            rc, o, e = hrun(h, STOP_GROUP % {"pid": v["pid"], "pgid": v["pgid"] if v["pgid"] != v.get("agent_pgid") else 0}, timeout=30)
            s["stopped"] = now(); notes[v["key"]] = f"STOPPED after the warning at {ts(s['warned'])}: {o.strip() or e.strip()[:80]}"
            try: cfg.f("watch.log").open("a").write(f"{ts()} enforce: {v['key']} {notes[v['key']]}\n")
            except OSError: pass
            if u:
                x = all_units(cfg).get(u)
                if x and x.get("id"): Beads(cfg).comment(x["id"], f"{ts()} orch stopped {v['kind']} pid {v['pid']} on {v['host']} after one warning")
        else: notes[v["key"]] = (f"warned at {ts(s['warned'])}" + (f"; stopped at {ts(s['stopped'])}" if s.get("stopped") else f"; stops at {ts(s['warned'] + grace)}" if stop_ok else ""))
        new[v["key"]] = s
    cfg.jput("enforce.json", new)
    return [(k, t + (f" [{notes[k]}]" if k in notes else "")) for k, t in F]

SCRIPT_RX = re.compile(r"^(?:\S*/)?(?:bash|sh|zsh|dash|ksh)\s+(?:-\S+\s+)*(/\S+)")

def held_inodes(pid):
    """Inodes of the files process pid has open (Linux /proc, else lsof); None when it cannot be told."""
    fd = Path(f"/proc/{pid}/fd")
    if fd.is_dir():
        out = set()
        for x in fd.iterdir():
            try: out.add(x.stat().st_ino)
            except OSError: pass
        return out
    rc, o, e = sh(["lsof", "-n", "-P", "-a", "-p", str(pid), "-Fi"], timeout=10)
    return {int(l[1:]) for l in o.splitlines() if l.startswith("i") and l[1:].isdigit()} if rc in (0, 1) and o else None

def script_findings():
    """Running shell scripts whose file was changed after they started (orch-fixes7, failure class 26): a shell reads its script
    as it goes, so an in-place edit makes it run from the old byte offset of the new text (a loop of 49,000 ledger rows). A
    file replaced by write-then-rename is safe (the shell keeps the old inode); only an edit of the inode it holds is flagged."""
    rc, o, e = sh(["ps", "-ww", "-U", str(os.getuid()), "-o", "pid=,lstart=,command="], timeout=10)
    F = []
    for l in o.splitlines():
        f = l.split(None, 6)
        if len(f) < 7 or not f[0].isdigit(): continue
        m = SCRIPT_RX.match(f[6])
        if not m: continue
        try: start = time.mktime(time.strptime(" ".join(f[1:6]), "%a %b %d %H:%M:%S %Y")); st = os.stat(m.group(1))
        except (ValueError, OSError): continue
        if st.st_mtime <= start + 1: continue
        held = held_inodes(int(f[0]))
        if held is not None and st.st_ino not in held: continue   # replaced by rename: the old text keeps running, safe
        F.append((f"script:{f[0]}:{int(st.st_mtime)}", f"running script {m.group(1)} (pid {f[0]}) was changed after it started"
                  f" ({ts(st.st_mtime)}){' in place' if held else ''}: the shell may run from a wrong offset of the new text; stop it and relaunch,"
                  " and replace scripts by write-then-rename, never in place"))
    return F

def collect_findings(cfg, hs, units, ag, bd_err):
    F = []; cfg._viol = []
    if bd_err: F.append(("beads", f"beads unavailable: {bd_err}"))
    ws = ws_id(cfg); names = {u["name"] for u in units}
    for u in units: u["state"] = unit_state(u, hs, ag)   # finished units hold no build position (host_cap)
    un = cfg.jget("hosts.json")
    ready = 0
    try: ready = len(ready_work(cfg))
    except Err: pass
    for n, p in hs.items():
        if not p["ok"]:
            qd = [u["name"] for u in units if u.get("host") == n]
            F.append((f"host:{n}", f"host {n} unreachable since {ts(un.get(n))} ({p['err']}); units there: {', '.join(qd) or 'none'}"))
            continue
        r, why = room(cfg, n, p, units)
        mg = margins(cfg.hosts[n], p, cfg=cfg)
        low = r < 1 and p.get("avail_mb") and fl(p.get("avail_mb")) / 1024 < cfg.hosts[n].get("reserve_gb", 2) * 0.6
        if mg or low:   # the key names the kinds (load, memory, disk), so an ack of one never hides another (H12)
            kinds = sorted({w.split()[0] for w in mg} | ({"memory"} if low else set()))
            F.append((f"margin:{n}:{'+'.join(kinds)}", f"host {n} over its margins: {'; '.join(mg) or why}"))
        elif r > 0 and ready: F.append((f"idle:{n}", f"host {n} has room for {r} but {ready} unit(s) are ready: orch launch"))
        hc = host_cap(cfg, n, p, units)
        if hc["pause"]:   # back-pressure (orch-fixes8 item 2): reported, never acted on by killing
            F.append((f"pressure:{n}", f"host {n} admission PAUSED ({hc['pause']}): new jobs wait; its {hc['rj']} running job(s) are not killed; it resumes below the limits"))
        # one scheduler per host (item 1): any other job-running process, or an old queue that still runs or holds work
        sch = list(p.get("sched", []))
        lg, lr = int(fl(p.get("legacy_wait"))), int(fl(p.get("legacy_run")))
        if lg or lr: sch.append(f"old queue: {lr} running, {lg} waiting (legacy_probe)")
        unt = [x for x in p.get("res", []) if " untracked " in x]
        if unt: sch.append(f"{len(unt)} job(s) running without an orch reservation ({', '.join(x.split()[-1] for x in unt[:3])})")
        if sch: F.append((f"scheduler:{n}", f"host {n} has job-running work outside its orch lanes, which must be the only admission: "
                          + "; ".join(sch[:4])[:300] + ": retire the old queue (or move its jobs to orch run)"))
        for d in p.get("direct", []):   # remote lane enforcement (register item 22)
            f = d.split(None, 4)
            if len(f) < 4 or not f[0].isdigit(): continue
            F.append((f"direct:{n}:{f[0]}", f"agent {f[2]} runs a build or test directly on {n} (pid {f[0]}, {int(fl(f[3])) // 60} min, outside the lanes): "
                      f"{(f[4] if len(f) > 4 else '')[:80]}; it must use {cfg.hosts[n].get('root', '~')}/run/{f[2]}.lane"))
            cfg._viol.append({"key": f"direct:{n}:{f[0]}", "kind": "direct", "host": n, "pid": int(f[0]), "pgid": int(fl(f[1])), "unit": f[2]})
        for t in ((p.get("pueue") or {}).get("tasks") or {}).values():
            st = t.get("status"); k = st if isinstance(st, str) else next(iter(st), "")
            lab = t.get("label") or ""
            owned = lab in names or (lab.startswith("unit:") and lab[5:] in names) or (t.get("group") in LANES and ":" in lab and not lab.startswith("unit:"))
            if k in ("Running", "Queued") and not owned:   # a lane job labelled unit:<name> whose unit is closed is an orphan too (M3)
                F.append((f"orphan:job:{n}:{t.get('id')}", f"orphan job {t.get('id')} on {n} ({lab or t.get('command', '')[:40]}) has no open unit"))
        for s in p.get("tmux", []):
            if s.startswith("orch-") and s[5:] not in names: F.append((f"orphan:tmux:{n}:{s}", f"orphan tmux session {s} on {n} has no open unit"))
    orch_pane = cfg.f("pane").read_text().strip() if cfg.f("pane").exists() else ""
    pane_units = {u.get("pane") for u in units}
    for k, a in ag.items():
        if ws and a.get("workspace_id") != ws: continue
        if k in names or a.get("pane_id") in pane_units or a.get("pane_id") == orch_pane or k == "orchestrator": continue
        F.append((f"orphan:pane:{a['pane_id']}", f"orphan agent {k} in pane {a['pane_id']} ({a.get('agent_status')}) has no open unit"))
    board = board_rows(cfg); running = 0
    BF = board_findings(cfg, names); F += BF; qids = board_questions(cfg) is not None
    for card, r in board.items():   # every card, including those other launchers posted (marked "not a unit")
        tag = "" if card in names else " (not a unit)"
        if r["state"] == "blocked" or (r["state"] == "question" and not qids):
            F.append((f"board:{card}:{r['state']}", f"{card}{tag} is {r['state'].upper()} on the board: {r['text']}; answer with board.sh direct"))
        if r["gone"]: F.append((f"board:{card}:gone", f"{card}{tag} GONE: its process ended without a done post"))
        elif r["silent"] and r["state"] not in ("question", "blocked"):
            F.append((f"board:{card}:silent", f"{card}{tag} silent over {cfg.silent // 60} min on the board"))
    for u in units:
        st = unit_state(u, hs, ag); v = verdict(cfg, u); u["state"] = st; u["verdict"] = v
        age = now() - u.get("started", now())
        # parked (orch-fixes9 item 1): recorded, or its turn ended with a WAITING line; no verdict yet
        pk = [] if v else ((u.get("parked") or {}).get("jobs") or (waiting_line_jobs(cfg, u) if st in ENDED or u.get("via") == "tmux" else []))
        if pk:
            u["_park"] = pk; u["state"] = st = "parked"
            js = {j: job_state(hs, j)[0] for j in pk}
            if any(x in ("paused", "stashed", "locked") for x in js.values()):
                F.append((f"parked:{u['name']}", f"{u['name']} is parked on {', '.join(f'{j} {x}' for j, x in js.items())}: a job that is not queued or running never resumes it"))
        elif st == "working":   # alive while its own jobs wait for admission: it pays to wait (cannot be acked)
            jw = [j for j in unit_jobs(hs, u["name"]) if job_state(hs, j)[0] in ("queued", "admission")]
            if jw:
                sp, how = unit_spend(cfg, u); hrs = max((now() - max(u.get("started", now()), u.get("resumed_at", 0))) / 3600, 1 / 60)
                rate = f"about ${sp / hrs:.2f}/h ({how})" if sp is not None else f"cost per hour unknown ({how})"
                F.append((f"waiting:{u['name']}", f"{u['name']} is alive while its job(s) {', '.join(jw[:4])} wait for admission, {rate}: "
                          f"orch park {u['name']} (stops it; it resumes, same session, when its jobs finish)"))
        if st in ("working", "queued", "parked"): running += 1
        if st == "blocked":
            r = herdr("agent", "read", u["name"], "--source", "detection") or {}
            F.append((f"unit:{u['name']}:blocked", f"{u['name']} blocked: {json.dumps(r)[:160]}"))
        elif st in ("done", "failed", "gone", "idle"):
            F.append((f"unit:{u['name']}:finished", f"{u['name']} finished ({st}; {v or 'no verdict'}); collect/close or relaunch"))
            aj = api_out(cfg, u)   # issue 32: another limit than the budget (turns) before the report; the budget cap is waste:<unit>
            if str(aj.get("subtype", "")).startswith("error") and aj.get("subtype") != "error_max_budget_usd" and not v:
                F.append((f"unit:{u['name']}:limit", f"{u['name']} stopped by its limit ({aj.get('subtype')}, ${aj.get('total_cost_usd', '?')}) without a final verdict: "
                          "resume it (orch resume --message, or --resume-of keeps its report)"))
        if not cfg.prov.get(cfg.models.get(u.get("model"), {}).get("provider"), {}).get("enabled", True):
            F.append((f"provider:{u['name']}", f"{u['name']} uses disabled provider of {u.get('model')}"))
    cfg._hs = hs; F += peer_findings(cfg, units)   # peers.md, overlap:<a>:<b> (orch-swarm item 4)
    board_upkeep(cfg, units)
    seen = {k for k, _ in F}
    for r, why in orphan_jobs(cfg, hs, units):   # the watcher cancels these (item 3); check only reports them
        k = f"orphan:job:{r}"
        if k not in seen: F.append((k, f"orphan job {r}: {why}; the watcher cancels it (orch cancel {r})"))
    cfg.jput("running.json", {"n": running})
    if cfg.caps.get("total") is not None and len(units) > cfg.caps["total"]: F.append(("cap:total", f"{len(units)} agents over total cap {cfg.caps['total']}"))
    for n, c in cfg.caps.get("host", {}).items():
        k = sum(1 for u in units if u.get("host") == n)
        if k > c: F.append((f"cap:{n}", f"{k} agents on {n} over its cap {c}"))
    F += gate_findings(cfg, hs)
    F += lane_findings(cfg, hs, units)
    if any(h.get("local") for h in cfg.hosts.values()): F += proc_findings(cfg) + script_findings()
    for n, pv in cfg.prov.items():
        if "ledger" in pv:
            bad = ledger_read(cfg, pv)[1]
            if bad: F.append((f"ledger:{n}", f"{n} ledger {pv['ledger']} is malformed ({len(bad)} problem(s): {bad[0][:90]}); every launch is refused: orch ledger check, orch ledger repair"))
            runs = ledger_read(cfg, pv)[0]; odd = [k for k, r in runs.items() if r["done"] and r["budget"] and r["cost"] > 2 * r["budget"] + 1]
            if odd or ("cap_usd" in pv and spend(runs) > 1.5 * pv["cap_usd"]):   # issue 39: a spend reading that cannot be right
                F.append((f"ledger:{n}:implausible", f"{n} spend reading implausible: ${spend(runs):.2f} committed" + (f" vs cap ${pv['cap_usd']}" if "cap_usd" in pv else "")
                          + (f"; runs costing over twice their budget: {', '.join(odd[:3])}" if odd else "") + ": orch ledger check"))
    F += backlog_findings(cfg, hs, units) + landing_findings(cfg, units, hs) + budget_findings(cfg, units) + report_findings(cfg, units)
    sk = cfg.f("session_kind").read_text().strip() if cfg.f("session_kind").exists() else ""
    if sk and sk != cfg.c.get("orchestrator", {}).get("kind", "claude"):
        F.append(("orchestrator:kind", f"the registered orchestrator is {sk}, but orch.toml [orchestrator] kind is {cfg.c.get('orchestrator', {}).get('kind')}: set it to {sk}"))
    F += git_findings(cfg) + memory_findings(cfg) + rule_findings(cfg)
    try:
        ins = Beads(cfg).issues("instruction")
        if ins: F.append(("instructions", f"{len(ins)} unclassified owner instruction(s) (close as done, or bd remember --key <subject>: same subject replaces): " + "; ".join(i['title'][:50] for i in ins[:3])))
    except Err: pass
    for s in handoff_stale(cfg, running): F.append(("handoff", s))
    if sys.platform == "darwin" and sh(["launchctl", "list", "com.orch.watch"])[0]: F.append(("watcher", "watcher com.orch.watch is not running: run install"))
    for n, pv in cfg.prov.items():
        if "cap_usd" in pv and committed(cfg, pv) >= pv["cap_usd"]: F.append((f"spend:{n}", f"{n} spend at its ${pv['cap_usd']} cap"))
    if not cfg.ro and not DRY: F = enforce(cfg, F)
    return F

def git_findings(cfg):
    """git:dirty, git:unpushed, git:noupstream of the project's own repository."""
    F = []
    rc, o, e = sh(["git", "status", "--porcelain", "-uall"], cwd=cfg.root)
    if rc == 0:
        dirty = o.splitlines()
        # orch's own state files (acks, notes, open, stops, running, hosts, stamps, job runs, the pueue shim) change on every
        # check and ack: never a finding. The orchestrator's notes (.md files in the state dir) still count.
        sd = cfg.state.resolve().relative_to(cfg.root.resolve()).as_posix() + "/" if cfg.state.resolve().is_relative_to(cfg.root.resolve()) else None
        if sd: dirty = [l for l in dirty if not (l[3:].strip().strip('"').startswith(sd) and not l[3:].strip().strip('"').endswith(".md"))]
        hp = handoff_path(cfg).relative_to(cfg.root) if handoff_path(cfg).is_relative_to(cfg.root) else None
        if hp and any(l[3:].strip() == str(hp) for l in dirty):   # check's own rewrite of the Live block is not a change (row 50)
            rc2, old, _ = sh(["git", "show", f"HEAD:{hp}"], cwd=cfg.root)
            if rc2 == 0 and old.split(LE, 1)[-1] == handoff_path(cfg).read_text().split(LE, 1)[-1]: dirty = [l for l in dirty if l[3:].strip() != str(hp)]
        if dirty: F.append(("git:dirty", f"{len(dirty)} uncommitted path(s) in {cfg.root.name}"))
        rc, o, e = sh(["git", "rev-list", "--count", "@{u}..HEAD"], cwd=cfg.root)
        if rc == 0 and o.strip() != "0": F.append(("git:unpushed", f"{o.strip()} unpushed commit(s)"))
        elif rc: F.append(("git:noupstream", "git has no upstream: add a remote, then orch commit-state (it pushes with --set-upstream)"))
    return F

def tune_pueue(cfg, hs, units):
    """Set each reachable host's pueue limits: jobs = cores // cores_per_job (admission by reservations decides what starts),
    agents = running agents plus the agents that fit by reservations (room), capped by the owner's caps."""
    for n, p in hs.items():
        t = p.get("pueue")
        if not p["ok"] or not t: continue
        h = cfg.hosts[n]; groups = t.get("groups") or {}
        run = lambda grp: sum(1 for x in (t.get("tasks") or {}).values() if x.get("group") == grp and "Running" in str(x.get("status")))
        want = {"jobs": slots(h, cfg), "agents": run("agents") + room(cfg, n, p, units)[0]}
        for grp, w in want.items():
            w = max(1, w); g = groups.get(grp)
            if g and g.get("parallel_tasks") != w: hrun(h, f"{pueue(h)} parallel -g {grp} {w}")

def live_state(cfg, hs, units, F):
    L = ["## Live state (" + ts() + ")", "Hosts:"] + ["- " + cap_line(cfg, n, p, units) for n, p in hs.items()]
    L.append("Units:")
    for u in units:
        L.append(f"- {u['name']} | {u.get('host')} | {u.get('model')} | {u.get('state', '?')}" + (f" on {' '.join(u['_park'][:4])}" if u.get("_park") else "")
                 + f" | {int((now() - u.get('started', now())) / 60)}m | {u.get('verdict') or 'no verdict'}")
    if not units: L.append("- none")
    try: rd = ready_work(cfg); L.append("Queue: " + (", ".join(i.get("title", "")[:40] for i in rd[:8]) or "empty"))
    except Err as e: L.append(f"Queue: unavailable ({e})")
    for n, pv in cfg.prov.items():
        if "cap_usd" in pv: L.append(f"Spend {n}: ${committed(cfg, pv):.2f} of ${pv['cap_usd']}")
    L.append("Problems:"); L += [f"- [{k}] {t}" for k, t in F] or ["- none"]
    return "\n".join(L)

def write_handoff(cfg, live):
    p = handoff_path(cfg); t = p.read_text() if p.exists() else ""
    notes = t.split(LE, 1)[1] if LE in t else "\n" + NOTES0
    new = f"# HANDOFF: {cfg.name}\n{LB}\n{live}\n{LE}{notes}"
    if new != t and not cfg.ro: p.write_text(new)

ACK_TTL = {"margin": 30 * 60}   # margin acks last 30 min, others 4 h, and every ack ends when its finding clears (audit H12)

def live_acks(cfg, keys=None):
    """Acks still in force. keys: the findings seen now; an ack whose finding is gone is dropped (only a writer saves that)."""
    acks = {k: (v if isinstance(v, dict) else {"t": v}) for k, v in cfg.jget("acks.json").items()}
    return {k: v for k, v in acks.items() if now() - v["t"] < ACK_TTL.get(k.split(":")[0], 4 * 3600) and (keys is None or k in keys)}

def run_check(cfg, cycle=True, writer=None):
    """Returns (findings not acknowledged, live text, probes, units). writer (default: the caller is the registered orchestrator,
    or the watcher) regenerates the Live part of HANDOFF.md, saves acks and open problems and sets pueue limits; anyone else
    only reads. The cycle stamp (last_cycle) is touched only for the orchestrator's own check."""
    cfg.ro = not (writer if writer is not None else is_orchestrator(cfg))
    hs = probe_all(cfg); bd_err = None; units = []
    try: units = Beads(cfg).units()
    except Err as e: bd_err = str(e)
    ag = herdr_agents(cfg)
    F = collect_findings(cfg, hs, units, ag, bd_err)
    if not cfg.ro: tune_pueue(cfg, hs, units)
    acks = live_acks(cfg, {k for k, _ in F}); cfg.jput("acks.json", acks)
    F = [(k, t) for k, t in F if k not in acks or k.startswith(NO_ACK)]
    op = cfg.jget("open.json"); op = {k: op.get(k, now()) for k, _ in F}; cfg.jput("open.json", op)
    live = live_state(cfg, hs, units, F); write_handoff(cfg, live)
    if cycle: cfg.touch("last_cycle")
    return F, live, hs, units

def cmd_check(cfg, a):
    F, live, hs, units = run_check(cfg)
    op = cfg.jget("open.json")
    if a.escalate: F = [(k, t) for k, t in F if now() - op.get(k, now()) > cfg.deadline]
    if a.brief and len(F) > 8: F = F[:8] + [("more", f"+{len(F) - 8} more: run orch check")]
    for k, t in F: say(f"[{k}] {t}")
    if cfg.ro: say("(read-only: not the registered orchestrator session, so nothing was saved, tuned or stamped)")

def cmd_capacity(cfg, a):
    cfg.ro = True; hs = probe_all(cfg)
    try: units = Beads(cfg).units()
    except Err: units = []
    ag = herdr_agents(cfg)
    for u in units: u["state"] = unit_state(u, hs, ag)   # finished units hold no agent or build position
    for n, p in hs.items(): say(cap_line(cfg, n, p, units))

def cmd_status(cfg, a):
    F, live, *_ = run_check(cfg, cycle=False); say(live)

def cmd_board_close(cfg, a):
    """Archive a board card that is not an open unit (cards from other launchers); an open unit is closed with orch close."""
    try: open_units = {u["name"] for u in Beads(cfg).units()}
    except Err as e: raise Err(f"beads unavailable, so it cannot tell whether {a.agent} is an open unit: {e}")
    if a.agent in open_units: raise Err(f"{a.agent} is an open unit: use orch close {a.agent}")
    if DRY: say(f"+ board.sh close {a.agent}"); return
    rc, o, e = board(cfg, "close", a.agent)
    if rc: raise Err(f"board.sh close {a.agent}: {(e or o).strip()[:120]}")
    cfg.touch("changed"); say(f"board card {a.agent} archived")

def cmd_ack(cfg, a):
    k, d = a.problem, a.decision
    if k.startswith(NO_ACK): raise Err(f"{k} cannot be acked: it costs money every hour; act on it (orch park {k.split(':', 1)[1]})")
    acks = live_acks(cfg); acks[k] = {"t": now()}; cfg.jput("acks.json", acks); cfg.touch("last_ack")
    try:
        bd = Beads(cfg); m = re.match(r"unit:([^:]+)", k)
        u = next((u for u in bd.units() if m and u["name"] == m.group(1)), None)
        if u: i = u["id"]
        else:
            ex = bd.issues("orch-log"); i = ex[0]["id"] if ex else bd.create("orch: decisions", "orch-log")
        bd.comment(i, f"{ts()} ack {k}: {d}")
    except Err as e: say(f"ack kept locally; beads: {e}")
    say(f"acked {k}")

def cmd_register(cfg, a):
    """The only way to change the registered orchestrator session (with the watcher's pending claim for a new one it started)."""
    if os.environ.get("ORCH_ROLE") == "agent": raise Err("refused: an agent (ORCH_ROLE=agent) cannot register as the orchestrator (issue 2)")
    sid = a.session or next((os.environ[k] for k in ("ORCH_SESSION", "CLAUDE_CODE_SESSION_ID", "CLAUDE_SESSION_ID", "CODEX_THREAD_ID") if os.environ.get(k)), None)
    kind = "codex" if os.environ.get("CODEX_THREAD_ID") and not os.environ.get("CLAUDECODE") else "claude"
    old = cfg.f("session").read_text().strip() if cfg.f("session").exists() else ""
    if old and sid and old != sid and session_alive(cfg): say(f"note: replacing registered session {old}, whose process is still alive")
    if DRY: say(f"+ register {sid or 'pending'} ({kind})"); return
    cfg.f("session").write_text(sid or f"pending:{int(now())}"); cfg.f("session_kind").write_text(kind + "\n")
    if sid: record_session_proc(cfg)
    # the caller's own pane only (HERDR_PANE_ID): `herdr pane current` is the focused pane, which is often another (issue 2)
    pid = os.environ.get("HERDR_PANE_ID")
    if pid: cfg.f("pane").write_text(pid)
    else: say("note: no HERDR_PANE_ID, so no pane recorded (the watcher then judges by the session's process and transcript)")
    cfg.touch("last_cycle"); cfg.touch("last_ack")
    say("registered " + (sid or "(pending: the next hook event from this session claims it)") + f" ({kind})")
    if cfg.c.get("orchestrator", {}).get("kind", "claude") != kind:
        say(f"warning: orch.toml [orchestrator] kind is {cfg.c.get('orchestrator', {}).get('kind')}, but this session is {kind}: set it to {kind}")
    ws = ws_id(cfg, create=True)
    if ws:   # plain shell loops: `watch` is not installed on the Mac (M10)
        have = {t.get("label") for t in (herdr("tab", "list", "--workspace", ws) or {}).get("tabs", [])}
        for lab, cmd in (("status", "while :; do clear; orch status; sleep 60; done"),
                         ("board", f"while :; do clear; BOARD_DIR={shlex.quote(str(board_dir(cfg)))} {shlex.quote(str(board_script(cfg)))} summary; sleep 60; done"),
                         ("watcher", f"tail -f {shlex.quote(str(cfg.f('watch.log')))}")):
            if lab in have: continue
            r = herdr("tab", "create", "--workspace", ws, "--label", lab, "--cwd", str(cfg.root), "--no-focus")
            if r: herdr("pane", "run", r["root_pane"]["pane_id"], cmd)

# ---------------------------------------------------------------- launch / stop / collect / close
def pick_model(cfg, tier, kind, of_vendor, host=None):
    lst = cfg.route.get("review" if kind == "review" else tier, [])
    why = []
    for m in lst:
        c = cfg.models.get(m, {})
        if host and host not in c.get("hosts", list(cfg.hosts)): why.append(f"{m}: not allowed on {host}"); continue
        if kind == "review" and of_vendor and c.get("vendor") == of_vendor: why.append(f"{m}: same vendor as implementer"); continue
        ok, w = model_ok(cfg, m)
        if ok: return m
        why.append(f"{m}: {w}")
    raise Err("no model available for " + tier + "/" + kind + " (" + "; ".join(why) + ")")

def agent_prompt(cfg, unit, brief, hn, report=None):
    """The first prompt of a unit. It names the report path the unit must keep (row 26: a resumed unit continues its original
    report, which orch reads; the agent must not guess it from the brief)."""
    rc, o, e = board(cfg, "rule", unit, *([] if cfg.hosts[hn].get("local") else [hn]))
    rp = f"your report {report}" if report else "REPORT.md (path in the brief)"
    return (f"Read {brief} and carry out every instruction exactly. Keep {rp} current after every step (a run "
            f"stopped by its budget must leave its state written): line 1 'VERDICT: PENDING' "
            f"until done, then end with 'VERDICT: DONE' (or BLOCKED) and the real exit codes. {o.strip()}")

def wait_shell(pane, unit):
    for _ in range(30):
        herdr("pane", "run", pane, f"echo ready-'{unit}'")
        rc, *_ = sh(["herdr", "pane", "wait-output", pane, "--match", f"ready-{unit}", "--timeout", "2000"], timeout=10)
        if rc == 0: return

def new_tab(cfg, label, cwd):
    ws = ws_id(cfg, create=True) or ""
    r = herdr("tab", "create", *(["--workspace", ws] if ws else []), "--label", label, "--cwd", str(cwd))
    if not r: raise Err("herdr tab create failed")
    return r["root_pane"]["pane_id"], r["tab"].get("tab_id")

def deliver_key(h, fifo, key):
    """Send the key into the task's fifo from a detached ssh with no time limit, so a full agents group queues the task instead
    of failing the launch (M13). The key goes over the pipe only: never a file or argv."""
    p = subprocess.Popen([*SSH, h["ssh"], f"cat > {qp(fifo)}"], stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         start_new_session=True, env=clean_env())
    p.stdin.write(key.encode() + b"\n"); p.stdin.close()

API_CMD = ["claude", "--bare", "-p", "--model", "{api_id}", "--max-budget-usd", "{budget}", "--output-format", "json",
           "--dangerously-skip-permissions", "{prompt}"]   # [providers.<p>] cmd overrides; --bare: the key only, never a login

def api_argv(pv, mc, budget, prompt, session=None):
    """The agent's command line ([providers.<p>] cmd, default API_CMD). session: continue that session ([providers.<p>]
    resume_cmd, e.g. ["codex", "exec", "resume", "{session}", "{prompt}"]; default: API_CMD with --resume {session})."""
    t = pv.get("cmd", API_CMD)
    if session:
        if pv.get("resume_cmd"): t = pv["resume_cmd"]
        elif "cmd" in pv: raise Err("the provider has its own cmd and no resume_cmd: set [providers.<p>] resume_cmd to resume a session")
        else: t = [*API_CMD[:3], "--resume", "{session}", *API_CMD[3:]]
    return [x.format(api_id=mc.get("api_id", mc.get("model", "")), model=mc.get("model", ""), budget=budget, prompt=prompt, session=session or "") for x in t]

def pq(cmd):
    """The command part of `pueue add -- <command>`, as one word of the caller's shell. pueue joins its arguments with spaces and
    runs the result with sh -c, so a command must reach it already shell-quoted: cmd is a list of words (quoted here) or shell
    text, and the whole is quoted once more for the caller's shell. Never `-- {words}` unquoted (a path with a space, a quote
    or a backtick broke a launch, and is an injection)."""
    return shlex.quote(cmd if isinstance(cmd, str) else shlex.join(cmd))

def qp(p):
    """A path as one shell word: shlex-quoted, except that a leading $HOME/ or ~/ (a remote root or worktree from orch.toml,
    default $HOME/orch) still expands."""
    p = str(p)
    for pre in ("$HOME/", "~/", "${HOME}/"):
        if p.startswith(pre): return '"$HOME"/' + (shlex.quote(p[len(pre):]) if p[len(pre):] else "")
    return shlex.quote(p)

def confirm_started(cfg, h, tid, secs=8):
    """Watch a just-queued agent task for a few seconds: (state, detail). "running" or "queued" (waiting for an agents slot) is
    fine, and "finished" a run that already ended with exit 0; "died" is a run that failed at once (a broken command line, a
    missing tool): its exit code and the end of its log."""
    t0 = now(); t = None
    while now() - t0 < secs:
        t = task_status(h, tid)
        if t is not None and task_rc(t) == 0: return "finished", "exit 0"
        if t is not None and task_rc(t) is not None:
            log = hrun(h, f"{pueue(h)} log {int(tid)} --lines 12", timeout=30)[1].strip()
            return "died", f"exit {task_rc(t)}: " + " | ".join(l.strip() for l in log.splitlines()[-8:] if l.strip())[-400:]
        time.sleep(1)
    k = (t or {}).get("status"); k = k if isinstance(k, str) else next(iter(k or {}), "unknown")
    return {"Running": "running", "Queued": "queued"}.get(k, str(k).lower()), ""

def put_script(h, path, text, mode="755"):
    """Write a script on host h by write-then-rename: a script that is running keeps reading its old file (orch-fixes7: a shell
    rereads its script at the old byte offset when the file is edited in place)."""
    if h.get("local"): atomic_write(Path(path), text, int(mode, 8)); return 0, "", ""
    f, d, m = qp(path), qp(os.path.dirname(str(path)) or "."), "%o" % int(mode, 8)
    return X(h, f"mkdir -p {d} && cat > {f}.tmp.$$ && chmod {m} {f}.tmp.$$ && mv -f {f}.tmp.$$ {f}", inp=text)

def atomic_write(p, text, mode=0o644):
    p = Path(p); p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(f".{p.name}.{os.getpid()}.tmp"); tmp.write_text(text); tmp.chmod(mode); os.replace(tmp, p)

def api_remote(cfg, h, name, mc, rbrief, rcwd, budget, prompt, env, session=None, run=None):
    """Headless agent as a pueue task on host h. The key goes over ssh stdin into a fifo that only that task reads: never a file,
    argv or pueue's environment."""
    pv = cfg.prov[mc["provider"]]; var, key = read_secret(pv)
    q = shlex.quote; R = h["root"]; root = qp(R); kf = f"{R}/run/{name}.key"; fifo = qp(kf); od = qp(f"{R}/out/{name}"); sp = f"{R}/run/{name}.sh"
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", var): raise Err(f"provider key variable {var!r} is not a variable name")
    mm = h.get("memory_max"); sd = f"systemd-run --user --scope -q -p {q(f'MemoryMax={mm}')} -- " if mm else ""
    ex = "".join(f"export {k}={q(v)}\n" for k, v in env.items())
    rd = qp(h["_rd"]); amb = int(cap_nums(cfg, h)["agmb"])
    # the agent's reservation (runs/agent-<unit>.res, its pid: exec keeps it) and a sampler that records the agent class's peak
    res = (f"RD={rd}; if [ -f $RD/cap.sh ]; then . $RD/cap.sh; echo \"$$ 0 $(cap_mb agent {amb} 0) $(date +%s) agent\" > $RD/agent-{name}.res\n"
           f"  ( t0=$(date +%s); pk=0; while kill -0 $$ 2>/dev/null; do v=$(tree_mb $$); [ \"${{v:-0}}\" -gt $pk ] && pk=$v; sleep 10; done\n"
           f"    cap_record agent $pk $(( $(date +%s) - t0 )) 0; rm -f $RD/agent-{name}.res ) </dev/null >/dev/null 2>&1 &\nfi\n")
    script = (f"{h.get('agent_env', 'export PATH=$HOME/.local/bin:$PATH')}\nexport PATH={root}/run/bin:$PATH\n{ex}read -r K < {fifo}; rm -f {fifo}; export {var}=$K; unset K\n"
              f"cd {qp(rcwd)} || exit 1\n{res}{sd}{shlex.join(api_argv(pv, mc, budget, prompt, session))} < /dev/null > {od}/api.json 2> {od}/api.err; rc=$?\n"
              + (f"cp {od}/api.json {od}/{q(f'api-{run}.json')} 2>/dev/null\n" if run else "") + "exit $rc\n")
    if DRY: return X(h, f"mkfifo {fifo}; write {qp(sp)}; {pueue(h)} add -g agents -l {name} -w {qp(rcwd)} --print-task-id -- {pq('sh ' + qp(sp))}; key | ssh cat > {fifo}")
    rc, o, e = hrun(h, f"mkdir -p {root}/run/bin {od} && rm -f {fifo} && mkfifo -m 600 {fifo}")
    if rc: return rc, o, e
    rc, o, e = put_script(h, sp, script)
    if rc: return rc, o, e
    rc, o, e = put_script(h, f"{R}/run/bin/pueue", clean_pueue_script(h))
    if rc: return rc, o, e
    rc, o, e = hrun(h, f"{pueue(h)} add -g agents -l {name} -w {qp(rcwd)} --print-task-id -- {pq('sh ' + qp(sp))}")
    if rc: return rc, o, e
    deliver_key(h, kf, key)
    return 0, o, ""

ORCH_SELF = Path(__file__).resolve()   # the installed release when run as `orch`: a queued task runs the version that queued it

def cmd_api_run(cfg, a):
    """One API agent run on this machine, as a pueue task that `orch launch` queued (orch-fixes7: orch runs API agents itself,
    no project launcher). The key is read here from the secret store and given only to the agent's process: never to pueue,
    a file or argv. Ledger: the run's running row (reserved at launch; written here when missing) and exactly one done row,
    both idempotent; a malformed ledger or a finished run id refuses the run."""
    mc = cfg.models.get(a.model) or {}
    if mc.get("kind") != "api": raise Err(f"model {a.model} is not an api model")
    pv = cfg.prov[mc["provider"]]; name = a.unit; od = cfg.p("out", "out") / name; od.mkdir(parents=True, exist_ok=True)
    run = reserve_budget(cfg, mc, name, a.budget, a.run)
    hn = next((n for n, h in cfg.hosts.items() if h.get("local")), "local")
    try: var, key = read_secret(pv)
    except Err as e: ledger_done(cfg, pv, run, name, 0, "no-key"); raise
    shim = cfg.f("bin"); put_script({"local": True}, str(shim / "pueue"), clean_pueue_script({"local": True}))
    env = clean_env({"ORCH_ROLE": "agent", "ORCH_UNIT": name, "ORCH_ROOT": str(cfg.root), "ORCH_REPORT": a.report or str(od / "REPORT.md"), "BOARD_DIR": str(board_dir(cfg)), var: key})
    env["PATH"] = f"{shim}:{env['PATH']}"   # the agent's own `pueue add` never stores the key in pueue's state file
    prompt = Path(a.prompt_file).read_text() if a.prompt_file else agent_prompt(cfg, name, a.brief, hn, a.report or str(od / "REPORT.md"))
    argv = api_argv(pv, mc, a.budget, prompt, a.resume_session)
    say(f"orch api-run {name}: run {run}, model {mc.get('api_id', a.model)}, budget ${a.budget}, cwd {a.cwd}" + (f", resuming session {a.resume_session}" if a.resume_session else ""))
    import signal
    with open(od / "api.json", "w") as fo, open(od / "api.err", "w") as fe:
        p = subprocess.Popen(argv, cwd=a.cwd, env=env, stdin=subprocess.DEVNULL, stdout=fo, stderr=fe)
    del key, env
    fwd = lambda s, _f: p.send_signal(s)   # pueue kill / orch stop: the agent stops too, and its done row is still written
    for s in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP): signal.signal(s, fwd)
    # the agent's reservation on this host (runs/agent-<unit>.res) while it runs; its peak memory goes to the history (class agent)
    h = cfg.hosts.get(hn, {"_rd": str(cfg.f("runs"))}); rd = Path(h["_rd"]); rd.mkdir(parents=True, exist_ok=True); t0 = now(); peak = 0
    try: hist = (rd / "history.tsv").read_text().splitlines()
    except OSError: hist = []
    n = cap_nums(cfg, h); resf = rd / f"agent-{name}.res"
    atomic_write(resf, f"{p.pid} 0 {class_mb(hist, 'agent', n['agmb'], 0, n['hn'], n['margin'])} {int(t0)} agent\n")
    while True:
        try: rc = p.wait(timeout=10); break
        except subprocess.TimeoutExpired: peak = max(peak, tree_rss_mb(p.pid))
        except InterruptedError: continue
    resf.unlink(missing_ok=True)
    if peak: record_history(rd, "agent", peak, int(now() - t0), rc)
    cost, reported = run_cost(od / "api.json", a.budget); how = ""
    if reported:
        try: atomic_write(od / f"api-{run}.json", (od / "api.json").read_text())   # every run's own json (orch report, resumes)
        except OSError: pass
    else:   # stopped before it wrote its cost (orch park, stop): its transcript since this run started, + 25 %, at most the budget
        f = transcript_of(cfg, {"rcwd": a.cwd, "started": t0 - 5, "brief": a.brief}) if not a.resume_session else \
            next(iter(sorted((Path.home() / ".claude/projects").glob(f"*/{a.resume_session}.jsonl"))), None)
        est = transcript_cost(cfg, f, since=t0 - 5)[0] if f else None
        if est is not None: cost, how = min(float(a.budget), round(est * 1.25, 4)), " (no cost reported: transcript estimate + 25 %)"
        else: how = " (no cost reported: charged the whole budget)"
    ledger_done(cfg, pv, run, name, cost, rc)
    say(f"orch api-run {name}: exit {rc}, cost ${cost:.4f}{how}")
    return rc

# A pueue that never stores the caller's environment: an agent holds ANTHROPIC_API_KEY in its own environment (claude passes
# it to every tool command), and pueue stores a task's whole environment in its state file. The lane runner uses it, and
# remote API agents get it first on PATH as `pueue` (orch-fixes6: found when a remote agent's lane job stored the key).
CLEAN_PUEUE = r'''#!/bin/sh
# pueue with an allow-listed environment (written by orch): a task never stores the caller's ANTHROPIC_API_KEY or tokens
real=%(real)s
# an agent's own `pueue add` gets its unit's label, so orch check never calls it an orphan (issue 24)
if [ "$1" = add ] && [ -n "$ORCH_UNIT" ]; then case " $* " in *" -l "*|*" --label "*|*" --label="*) ;; *) shift; set -- add -l "unit:$ORCH_UNIT" "$@";; esac; fi
exec env -i HOME="$HOME" USER="$USER" LOGNAME="${LOGNAME:-$USER}" PATH="$PATH" LANG="${LANG:-C.UTF-8}" SHELL="${SHELL:-/bin/sh}" \
  TMPDIR="${TMPDIR:-/tmp}" ${XDG_RUNTIME_DIR:+XDG_RUNTIME_DIR="$XDG_RUNTIME_DIR"} ${XDG_CONFIG_HOME:+XDG_CONFIG_HOME="$XDG_CONFIG_HOME"} ${ORCH_UNIT:+ORCH_UNIT="$ORCH_UNIT"} ${ORCH_ROLE:+ORCH_ROLE="$ORCH_ROLE"} "$real" "$@"
'''

def clean_pueue_script(h):
    if h.get("local"):
        import shutil
        real = shutil.which("pueue", path=clean_env()["PATH"]) or "pueue"
    else: real = f"{h['bin']}/pueue" if h.get("bin") else "$HOME/.local/bin/pueue"
    return CLEAN_PUEUE % {"real": real}

def lane_runner(cfg, hn, h, name, rcwd):
    """<root>/run/<unit>.lane on host h: `lane <command>` runs the command in the agent's tree through this host's pueue jobs lane,
    with orch's admission (runs/cap.sh: reservations) and MemoryMax, waits, prints the log and exits with its code (M9; fixes5 item 2).
    `lane --detach <command>` queues it, prints <host>:<task> and returns at once (orch-fixes9: agents never wait)."""
    a = argparse.Namespace(lane="jobs", subdir=None, usb=False, wt=rcwd)
    rd = runs_dir(cfg, h); q = shlex.quote
    crd = in_container(h, rd)   # the runs dir as the job sees it
    js = job_script(cfg, hn, h, a, name, f"bash {qp(crd + '/__JID__.cmd')}", "__JID__", wd=rcwd, clsrc='"$(cat "$R.cmd")"')
    return ("#!/bin/bash\n# orch lane runner for unit " + name + f" on {hn}: lane <command>\nRD={qp(rd)}; mkdir -p \"$RD\"\n"
            f"det=; [ \"$1\" = --detach ] && {{ det=1; shift; }}\n"
            f"jid={name}-$(date +%m%d-%H%M%S)-$$; R=\"$RD/$jid\"\nprintf '%s\\n' \"$*\" > \"$R.cmd\"\n"
            f"cat > \"$R.sh\" <<'ORCH_JOB_EOF'\n{js}ORCH_JOB_EOF\nsed -i \"s/__JID__/$jid/g\" \"$R.sh\"\n"
            f"{pueue(h)} group add -p 1 jobs >/dev/null 2>&1\n"
            f"tid=$(env -i HOME=\"$HOME\" USER=\"$USER\" PATH=\"$PATH\" ${{XDG_RUNTIME_DIR:+XDG_RUNTIME_DIR=\"$XDG_RUNTIME_DIR\"}} LANG=\"${{LANG:-C.UTF-8}}\" {pueue(h)} add -g jobs -l unit:{name} -w \"$RD\" --print-task-id -- \"bash $(printf %q \"$R.sh\")\") || exit 125\n"
            f"echo \"lane: queued {hn}:$tid ($jid)\" >&2\n[ -n \"$det\" ] && {{ echo \"{hn}:$tid\"; exit 0; }}\n"
            f"{pueue(h)} wait -q $tid; cat \"$R.log\"; exit $(cat \"$R.rc\" 2>/dev/null || echo 255)\n")

PARK_RULE = ("**Never wait for a build or test (orch rule).** Submit it with `{submit}`: it prints the job id (`<host>:<task>`) at once. "
             "Then write a line `WAITING <job ids>` in your report ({report}) and end your turn. Do not poll, sleep or wait for a job: "
             "orch resumes this same session with each job's exit code and log path when all of them have finished. A turn spent "
             "waiting costs money and can end the run at its budget cap with nothing written.\n\n")

BOARD_RULE = ("**Board:** post only state changes (status when you start, `waiting <job ids>` when you park, `blocked` or `question` when "
              "stuck, `learned <fact, with its source>` when you found something every agent should know, `done <VERDICT line>` at the end); "
              "your steps go in your report, not on the board.")

def swarm_header(cfg, hn, h, name, rcwd, local):
    """What every agent gets at start besides its brief (orch-swarm item 2): the session memory, then pointers (never content)
    to the project's agent instructions, the reports index, the peers file and how to read another agent's transcript."""
    es = memory_read(cfg); L = []
    if es:
        L.append("## Session memory (curated by the orchestrator; your brief wins on conflict)")
        for sec in MEM_SECTIONS.values():
            sel = [mem_line(e) for e in es if e[0] == sec]
            if sel: L += [f"{sec}:", *sel]
        L.append("")
    bdir = str(board_dir(cfg)) if local else f"{h['root']}/board"
    docs = mset(cfg, "agent_docs"); docs = [docs] if isinstance(docs, str) else docs
    L += ["## Other agents and shared knowledge (orch)",
          f"- Project instructions: read the root {' / '.join(docs)} of your tree ({rcwd}) and the one in each folder you touch, where present.",
          f"- Reports index: {bdir}/index.md (one line per unit: verdict, result, report path).",
          f"- Peers: {bdir}/peers.md (each running unit: host, model, branch, files it changed, step, jobs it waits on, report, transcript).",
          ("- Another agent's transcript: `orch transcript <unit> --grep '<regex>'` or `orch transcript <unit> --tail 20` (condensed)." if local else
           "- Another agent's transcript: peers.md names where it is; when it is on this host, grep or tail it (never read it whole); "
           "otherwise ask with a board question and the orchestrator reads it for you."),
          "- Rule: read peers.md and the index when your task touches another unit's area; read a transcript only to solve a problem "
          "another unit met, by grep or tail, never whole.",
          "- " + BOARD_RULE, "", ""]
    return "\n".join(L)

def brief_header(cfg, hn, h, name, rcwd, local, build=None, report=None):
    """The header every unit's brief gets: where it runs, how it submits builds and tests (detached, then WAITING), its report,
    then the session memory and the swarm pointers (swarm_header)."""
    if local:
        b = build or hn
        return (f"<!-- orch: unit {name} runs on {hn} -->\n" + PARK_RULE.format(
            submit=f"orch run --detach --host {shlex.quote(b)} --wt {shlex.quote(str(rcwd))} -- '<command>'", report=report or "REPORT.md")
            + swarm_header(cfg, hn, h, name, rcwd, True))
    lane = qp(f"{h['root']}/run/{name}.lane")
    return (f"<!-- orch: unit {name} runs on {hn} -->\n**Where you run (orch):** you are on host `{hn}`, in `{rcwd}` (a copy of the worktree; `orch collect` "
            f"brings back a patch of your changes, your REPORT and logs). Run every build and test through this host's pueue lane: "
            f"`{lane} --detach '<command>'` (for example `{lane} --detach 'cargo test -p <crate>'`); it waits for admission and runs there. "
            f"Do not run builds, tests or other heavy commands directly.\n" + PARK_RULE.format(submit=f"{lane} --detach '<command>'", report=report or "REPORT.md")
            + swarm_header(cfg, hn, h, name, rcwd, False))

def place(cfg, a, brief, mc, units, hs):
    """Host for the agent: --host; else where its builds and tests run (--test-host, a 'TEST-HOST: <h>' line in the brief, the
    first matching [placement] rule of orch.toml (regex over unit name and brief text = host), or the worktree's sticky host in
    out/linux-host/<unit>), when the model may run there; else the allowed host with the most measured room."""
    allowed = [n for n in cfg.hosts if n in mc.get("hosts", list(cfg.hosts))]
    if a.host: return [a.host], "--host", (a.test_host if a.test_host in cfg.hosts else None)   # (hosts, why, build host): review-fixes8 #1
    txt = brief.read_text() if brief.is_file() else ""
    want = a.test_host
    if not want:
        m = re.search(r"^TEST-HOST:\s*(\S+)", txt, re.M); want = m.group(1) if m else None
    if not want:
        for rx, hn in cfg.c.get("placement", {}).items():
            if re.search(rx, a.unit + "\n" + txt): want = hn; break
    if not want:
        st = cfg.p("out", "out") / "linux-host" / a.unit
        want = st.read_text().strip() if st.is_file() else None
    if want and want in allowed: return [want], f"tests run on {want}", want
    if want and want not in cfg.hosts: want = None
    return allowed, ("tests run on " + want + ", but " + a.unit + "'s model is not allowed there; " if want else "") + "most room", want

def choose(cfg, a, brief, mc, units, hs):
    """(agent host, build host, why) for a new unit, or Err saying why not and when to expect room. The agent host has room for
    one more agent by reservations (room); the build host (where its builds and tests run: placement, else the agent host) has
    a free build reservation or a bounded queue position (build_room, orch-fixes8 item 3)."""
    if a.host and a.host not in cfg.hosts: raise Err(f"unknown host {a.host}")
    hosts, why_place, want = place(cfg, a, brief, mc, units, hs)
    best, bn, notes = None, 0, []
    for n in hosts:
        r, why = room(cfg, n, hs[n], units, a.kind == "cleanup")
        if r < 1: notes.append(f"{n}: {why}"); continue
        b = want or n
        if not hs.get(b, {}).get("ok"): notes.append(f"{n}: build host {b} unreachable"); continue
        ok, bw = build_room(cfg, b, host_cap(cfg, b, hs[b], units), a.kind)
        if not ok: notes.append(bw); continue
        if r > bn: best, bn = (n, b, f"{why_place}; {bw}"), r
    if not best: raise Err("refused, no room (" + "; ".join(dict.fromkeys(notes)) + ")")
    return best

def resume_report(cfg, a, brief):
    """The report a resumed unit continues: --report, else out/<--resume-of>/REPORT.md. None for a new unit (it writes
    out/<unit>/REPORT.md). Never parsed from the brief's prose (a path cut out of prose broke a launch, orch-fixes9); the path
    must be a REPORT file whose folder exists."""
    p = a.report or (str(cfg.p("out", "out") / a.resume_of / "REPORT.md") if a.resume_of else None)
    if not p: return None
    p = Path(os.path.expanduser(p)); p = (p if p.is_absolute() else cfg.root / p).resolve()
    if a.resume_of and not re.fullmatch(r"[a-z][a-z0-9_-]{0,31}", a.resume_of): raise Err(f"--resume-of {a.resume_of!r} is not a unit name")
    if not p.parent.is_dir(): raise Err(f"report {p}: its folder does not exist")
    return None if p == (cfg.p("out", "out") / a.unit / "REPORT.md").resolve() else p

def report_path(cfg, u): return Path(u["report"]) if u.get("report") else cfg.p("out", "out") / u["name"] / "REPORT.md"

def main_checkout(cwd):
    """True when cwd is the main working tree of a repository that has linked worktrees (agents get a worktree, H9)."""
    rc, o, e = sh(["git", "-C", str(cwd), "rev-parse", "--show-toplevel", "--git-dir", "--git-common-dir"])
    if rc: return False
    top, gd, cd = o.split("\n")[:3]
    if Path(top).resolve() != Path(cwd).resolve() or Path(cwd, gd).resolve() != Path(cwd, cd).resolve(): return False
    rc, o, e = sh(["git", "-C", str(cwd), "worktree", "list", "--porcelain"])
    return rc == 0 and o.count("\nworktree ") + o.startswith("worktree ") > 1

DIALOGS = [   # startup dialogs orch gets past (fixes5 item 10): (text in the pane, keys to send)
    (r"trust the (files|contents) (in|of) this (folder|directory)|Do you trust", ["Enter"]),
    (r"Update available|new version of Codex|Skip until next version", ["Down", "Enter"]),
    (r"Press Enter to continue", ["Enter"])]

def past_dialogs(name, pane):
    for _ in range(6):
        r = herdr("pane", "read", pane, "--source", "visible", "--lines", "40") or {}
        txt = json.dumps(r)
        hit = next((k for rx, k in DIALOGS if re.search(rx, txt, re.I)), None)
        st = ((herdr("agent", "get", name) or {}).get("agent") or {}).get("agent_status")
        if not hit: return None if st in ("idle", "working", "done", None) else f"agent {st} at start: {txt[-200:]}"
        herdr("pane", "send-keys", pane, *hit); time.sleep(2)
    return "startup dialog still shown after 6 tries"

def unit_tab(cfg, u, mname, hn, h):
    """One labelled tab per running unit (<unit> · <model> · <host>) that follows its pueue log (fixes5 item 3)."""
    if u.get("via") != "pueue" or DRY: return
    try: pane, tab = new_tab(cfg, f"{u['name']} · {mname} · {hn}", cfg.root)
    except Err: return
    f = f"{pueue(h)} follow {int(u['task'])}"
    herdr("pane", "run", pane, f if h.get("local") else f"ssh -t {shlex.quote(h['ssh'])} {shlex.quote(f)}"); u.update(pane=pane, tab=tab)

def cmd_launch(cfg, a):
    name = a.unit
    if not re.fullmatch(r"[a-z][a-z0-9_-]{0,31}", name): raise Err("unit must match [a-z][a-z0-9_-]{0,31}")
    bd = Beads(cfg); units = bd.units(); prev = next((u for u in units if u["name"] == name), None)
    if prev and a.kind != "review": raise Err(f"{name} already launched on {prev.get('host')}")
    wp = waste_paused(cfg)
    if wp: raise Err(f"refused (waste pause): {wp}")
    brief = Path(a.brief) if a.brief else cfg.p("briefs", "briefs") / f"{name}.md"
    if not brief.is_file(): raise Err(f"brief {brief} not found")
    of = next((u for u in units if u["name"] == (a.of or name)), None)
    if a.model:   # an explicit model passes the same enabled and budget checks as a routed one (M1)
        if a.model not in cfg.models: raise Err(f"unknown model {a.model}")
        ok, w = model_ok(cfg, a.model)
        if not ok: raise Err(f"model {a.model}: {w}")
    mname = a.model or pick_model(cfg, a.tier, a.kind, of.get("vendor") if of else None, a.host)
    mc = cfg.models[mname]
    hs = getattr(a, "probes", None) or probe_all(cfg)
    ag = herdr_agents(cfg) if not getattr(a, "probes", None) else {}
    for x in units: x.setdefault("state", unit_state(x, hs, ag))   # finished units hold no build position
    hn, build, why_place = choose(cfg, a, brief, mc, units, hs)
    h = cfg.hosts[hn]; local = h.get("local", False)
    cwd = cfg.p("worktrees", "worktrees") / name
    cwd = (Path(a.cwd) if a.cwd else cwd if cwd.is_dir() else cfg.root).resolve()
    shared = [u["name"] for u in units if u.get("cwd") and Path(u["cwd"]).resolve() == cwd and u["name"] != name and cwd != cfg.root.resolve()]
    if shared and getattr(a, "share_with", None): shared = [x for x in shared if x != a.share_with]   # orch land's merge unit
    if shared and not (local and a.kind in ("review", "audit")):
        raise Err(f"refused: {cwd} is the cwd of open unit(s) {', '.join(shared)}; give the unit its own worktree (H9)")
    if main_checkout(cwd) and not a.allow_main: raise Err(f"refused: {cwd} is a main checkout with linked worktrees; use a worktree (or --allow-main)")
    outd = cfg.p("out", "out") / name; outd.mkdir(parents=True, exist_ok=True)
    rbrief, rcwd = str(brief), str(cwd)
    budget = None
    if mc["kind"] == "api":
        budget, bwhy = (a.budget, "--budget") if a.budget is not None else budget_for(cfg, mc, a.kind, a.tier)
        why_place += f"; budget ${budget:g} ({bwhy})"
    say(f"launch {name}: model={mname} host={hn} builds on {build} ({why_place}) cwd={cwd}")
    if mc["kind"] == "api":
        read_secret(cfg.prov[mc["provider"]])   # the secret store answers before anything is reserved or recorded
        ok, w = model_ok(cfg, mname)
        if not ok and "ledger" in w: raise Err(f"refused: {w}")
    # A resumed unit continues its original report (--report or --resume-of only, never a path from the brief's prose); the
    # unit records it, so check and the Stop hook read that report.
    report = resume_report(cfg, a, brief)
    if report and report.exists():
        t = report.read_text().split("\n", 1)
        if t[0].startswith("VERDICT:") and "PENDING" not in t[0] and not DRY: atomic_write(report, "VERDICT: PENDING\n" + (t[1] if len(t) > 1 else ""))
    # Record the unit before anything starts (fixes5 item 10), claimed in_progress so bd ready never lists it (H7).
    u = {"host": hn, "build": build, "model": mname, "vendor": mc.get("vendor"), "kind": a.kind, "tier": a.tier, "brief": str(brief),
         "cwd": str(cwd), "rcwd": rcwd, "started": int(now()), "via": "starting", "budget": budget}
    if report: u["report"] = str(report); u["resume"] = True
    item = a.item or (re.search(r"^ITEM:\s*(\S+)", brief.read_text(), re.M) or [None, None])[1]
    if item: u["item"] = item
    if DRY: say(f"+ bd create unit:{name}; bd update --status in_progress")
    else:
        u["id"] = bd.create(f"unit:{name}", "unit", f"{a.kind} on {hn} with {mname}"); u["name"] = name
        bd.run("update", u["id"], "--status", "in_progress"); bd.save(u)
    env = {"ORCH_ROLE": "agent", "ORCH_REPORT": str(report or outd / "REPORT.md"), "ORCH_UNIT": name, "ORCH_ROOT": str(cfg.root),
           **({"BOARD_DIR": str(board_dir(cfg))} if local else {})}   # remote: <root>/bin/board.sh finds <root>/board itself
    try:
        if not local:
            root = h["root"]; rcwd = f"{root}/worktrees/{name}"; rbrief = f"{root}/briefs/{name}.md"
            env["ORCH_REPORT"] = f"{root}/out/{name}/REPORT.md"
            X(h, "mkdir -p " + " ".join(qp(x) for x in (rcwd, f"{root}/briefs", f"{root}/out/{name}", f"{root}/run", f"{root}/base")))
            cmd = ["rsync", "-a", "--delete", "-e", " ".join(SSH), *EXCL, f"{cwd}/", f"{h['ssh']}:{rcwd}/"]
            if DRY: say("+ " + shlex.join(cmd))
            elif sh(cmd, timeout=900)[0]: raise Err("rsync to " + hn + " failed")
            # base/<unit>: the tree as sent, so collect can bring back only the agent's changes as a patch (H9)
            X(h, f"rm -rf {qp(f'{root}/base/{name}')} && cp -a {qp(rcwd)} {qp(f'{root}/base/{name}')}", timeout=300)
            put_script(h, f"{root}/run/{name}.lane", lane_runner(cfg, hn, h, name, rcwd))
            if not cfg.paths.get("board"): put_script(h, f"{root}/bin/board.sh", board_script(cfg).read_text())   # the shipped board there (outbox)
            if not DRY: write_cap(cfg, hn, h)   # the lane runner's admission and the agent's reservation use it
            put_script(h, rbrief, brief_header(cfg, hn, h, name, rcwd, local, build, env["ORCH_REPORT"]) + brief.read_text(), "644")
            if report and report.exists():   # a resumed unit continues its original report there; collect copies it back
                put_script(h, f"{root}/out/{name}/REPORT.md", report.read_text(), "644")
            else: X(h, f"[ -s {qp(env['ORCH_REPORT'])} ] || echo 'VERDICT: PENDING' > {qp(env['ORCH_REPORT'])}")
        rep = outd / "REPORT.md"
        if not report and not rep.exists() and not DRY: rep.write_text("VERDICT: PENDING\n")
        if local:   # the brief with orch's header (the park rule) as the agent reads it: out/<unit>/<brief name>
            rbrief = str(outd / (brief.name if (outd / brief.name).resolve() != brief.resolve() else "orch-" + brief.name))
            if not DRY: atomic_write(Path(rbrief), brief_header(cfg, hn, h, name, rcwd, True, build, env["ORCH_REPORT"]) + brief.read_text())
        u["rbrief"] = rbrief
        prompt = agent_prompt(cfg, name, rbrief, hn, env["ORCH_REPORT"])
        u["rcwd"] = rcwd
        if mc["kind"] == "api":
            X(h, ensure_lanes(h, cfg))
            if local and not DRY: write_cap(cfg, hn, h)
            # the budget is reserved (cap check and the run's running row, under the ledger's lock) before anything is queued
            run = reserve_budget(cfg, mc, name, budget); u["run"] = run
            if local:
                cmd = shlex.join([sys.executable, str(ORCH_SELF), "api-run", name, "--run", run, "--model", mname, "--budget", str(budget),
                                  "--brief", rbrief, "--cwd", rcwd, "--report", env["ORCH_REPORT"]])
                rc, o, e = X(h, f"{pueue(h)} add -g agents -l {name} -w {shlex.quote(rcwd)} --print-task-id -- {pq(cmd)}", env=env)
            else:
                rc, o, e = api_remote(cfg, h, name, mc, rbrief, rcwd, budget, prompt, env, run=run)
            if rc and not DRY: ledger_done(cfg, cfg.prov[mc["provider"]], run, name, 0, "launch-failed")
            if rc: raise Err("pueue add failed: " + (e or o).strip()[:100])
            u.update(via="pueue", task=int(o.strip() or 0))
            if not DRY:   # launched means started (or queued for a slot, or already done), never a run that died at once
                st, why = confirm_started(cfg, h, u["task"])
                if st == "died":
                    ledger_done(cfg, cfg.prov[mc["provider"]], run, name, 0, "died-at-start")
                    raise Err(f"the run died at once ({why}); nothing is running")
                u["start_state"] = st
                say(f"{name}: run {st}" + (" (waiting for an agents slot)" if st == "queued" else " (exit 0)" if st == "finished" else
                                            "" if st == "running" else f": not confirmed running (pueue {hn}:{u['task']} is {st})"))
            unit_tab(cfg, u, mname, hn, h)
        elif local:
            pane, tab = new_tab(cfg, f"{name} · {mname} · {hn}", cwd) if not DRY else ("pane", "tab")
            u.update(pane=pane, tab=tab)
            if not DRY:
                wait_shell(pane, name)
                envs = {**env, **({"OPENCODE_CONFIG_CONTENT": json.dumps({"model": mc["model"]})} if mc["kind"] == "opencode" else {})}
                # the pane's shell inherited herdr's environment: drop what must not reach an agent, then set the unit's own
                herdr("pane", "run", pane, "unset ANTHROPIC_API_KEY CLAUDE_CODE_MESSAGING_TOKEN HERDR_PANE_ID CLAUDE_CODE_SESSION_ID; "
                      + "; ".join(f"export {k}={shlex.quote(v)}" for k, v in envs.items()) + f"; echo env-'{name}'")
                sh(["herdr", "pane", "wait-output", pane, "--match", f"env-{name}", "--timeout", "10000"], timeout=15)
                r = sh(["herdr", "agent", "start", name, "--kind", mc["kind"], "--pane", pane, "--timeout", "90000", "--", *mc.get("args", [])], timeout=100)
                d = past_dialogs(name, pane)
                if r[0] and d: raise Err("herdr agent start failed: " + (r[2] or d)[:160])
                if d: raise Err(f"{name}: {d}")
                herdr("agent", "prompt", name, prompt)
                u.update(via="herdr", pid=findkey(herdr("pane", "process-info", "--pane", pane), "pid"))
                agent_res(cfg, hn, h, name, u.get("pid"))
            else: say(f"+ herdr tab create / agent start {name} --kind {mc['kind']} / agent prompt")
        else:
            cli = {"claude": "claude", "codex": "codex", "opencode": "opencode run"}[mc["kind"]]
            e = " ".join(f"{k}={shlex.quote(v)}" for k, v in env.items())
            if mc["kind"] == "opencode": e += " OPENCODE_CONFIG_CONTENT=" + shlex.quote(json.dumps({"model": mc["model"]}))
            mm = h.get("memory_max"); sd = f"systemd-run --user --scope -q -p {shlex.quote(f'MemoryMax={mm}')} -- " if mm else ""   # fixes5 item 7
            inner = f"cd {qp(rcwd)} && exec env {e} {sd}{cli} {shlex.join(mc.get('args', []))} {shlex.quote(prompt)}"
            pre = f'PATH="$HOME/.local/bin:{h.get("bin", "")}:$PATH"; '
            rc, o, er = X(h, pre + f"tmux new -d -s orch-{name} {shlex.quote(inner)} && tmux display -p -t orch-{name} '#{{pane_pid}}'")
            if rc: raise Err("tmux start failed: " + er.strip()[:100])
            u.update(via="tmux", pid=int(o.strip() or 0))
            if not DRY:   # launched means the agent's session is alive a moment later (a broken command line ends it at once)
                time.sleep(3)
                if hrun(h, pre + f"tmux has-session -t orch-{name}")[0] or not u["pid"]:
                    raise Err(f"the agent's tmux session orch-{name} ended at once; nothing is running")
                u["start_state"] = "running"
            if not DRY: agent_res(cfg, hn, h, name, u["pid"])
            if not DRY:
                pane, tab = new_tab(cfg, f"{name} · {mname} · {hn}", cwd)
                herdr("pane", "run", pane, f"ssh -t {shlex.quote(h['ssh'])} tmux attach -t orch-{name}"); u.update(pane=pane, tab=tab)
    except Err as ex:
        if not DRY:
            u["via"] = "failed"; bd.save(u); bd.comment(u["id"], f"{ts()} launch failed: {ex}")
            bd.run("close", u["id"], "--reason", "launch failed")
            if u.get("tab"): herdr("tab", "close", u["tab"])
        raise
    if DRY: return
    bd.save(u); bd.comment(u["id"], f"{ts()} launched {a.kind} on {hn} model {mname} via {u['via']}"); cfg.touch("changed")
    chk = f"herdr {name}" if u["via"] == "herdr" else f"pueue {hn}:{u['task']}" if u["via"] == "pueue" else f"tmux {hn}:orch-{name}"
    board(cfg, "post", name, "status", f"launched ({mname}, {hn})",
       env={"BOARD_MACHINE": hn, "BOARD_BRIEF": str(brief), "BOARD_CHECK": chk, "BOARD_REPORT": str(report_path(cfg, u))})   # row 26: a resumed unit's own report
    st = u.get("start_state", "running" if u["via"] == "herdr" else "unknown")
    say((f"launched {name} on {hn} via {u['via']}" if st in ("running", "queued", "finished") else f"queued {name} on {hn} via {u['via']}, NOT confirmed running ({st})")
        + (f" (task {u['task']}{', waiting for an agents slot' if st == 'queued' else ''})" if u.get("task") is not None else ""))

def get_unit(cfg, name):
    bd = Beads(cfg); u = next((u for u in bd.units() if u["name"] == name), None)
    if not u: raise Err(f"no open unit {name}")
    return bd, u

# Every process of a unit: the tree under its task or pane, every process group in it, and any process anywhere whose
# environment has ORCH_UNIT=<unit> (detached children: nohup, setsid, & disown). Printed as "pid pgid" lines (M12).
UNIT_PROCS = r'''u=%(unit)s; me=$$; roots="%(roots)s"
if [ -d /proc/1 ]; then
  env_pids=$(grep -lsaz "^ORCH_UNIT=$u\$" /proc/[0-9]*/environ 2>/dev/null | cut -d/ -f3)
fi   # macOS: the caller passes those pids in roots (mac_env_pids)
ps -A -o pid=,ppid=,pgid= | awk -v seeds="$env_pids $roots" -v me=$me '
  {p[$1] = $2; g[$1] = $3; kids[$2] = kids[$2] " " $1}
  END {n = split(seeds, s, " "); for (i = 1; i <= n; i++) if (s[i] in p) q[s[i]] = 1
       do {ch = 0; for (x in q) {m = split(kids[x], k, " "); for (j = 1; j <= m; j++) if (!(k[j] in q)) {q[k[j]] = 1; ch = 1}}} while (ch)
       for (x in q) if (x != me && x > 1) print x, g[x]}'
'''

def mac_env_pids(unit):
    """pids whose environment has ORCH_UNIT=<unit>. macOS ps -E appends the environment to the command line, so the command
    (from plain ps) is cut off first: a command line that merely mentions the variable never matches."""
    tab = lambda *f: {int(l.split(None, 1)[0]): (l.split(None, 1) + [""])[1] for l in sh(["ps", "-Aww", *f, "-o", "pid=,command="], timeout=10)[1].splitlines() if l.strip()}
    P, E = tab(), tab("-E")
    return [p for p, c in E.items() if p in P and c.startswith(P[p]) and f"ORCH_UNIT={unit}" in c[len(P[p]):].split()]

def unit_procs(h, unit, roots=""):
    if h.get("local"): roots = " ".join([roots, *map(str, mac_env_pids(unit))])
    rc, o, e = hrun(h, UNIT_PROCS % {"unit": shlex.quote(unit), "roots": roots}, timeout=30)
    return [tuple(map(int, l.split())) for l in o.splitlines() if re.fullmatch(r"\d+ \d+", l.strip())]

def kill_unit(h, unit, roots=""):
    """TERM every process group of the unit, then KILL what is left after 5 s. Never the caller's or pueued's group."""
    ps = unit_procs(h, unit, roots)
    if not ps: return 0
    t = ps_table() if h.get("local") else {}
    safe = {os.getpgid(0)} | {g for p, (pp, g, s, c) in t.items() if "pueued" in c}
    groups = sorted({g for p, g in ps if g > 1 and g not in safe}); pids = sorted({p for p, g in ps})
    for sig in ("TERM", "KILL"):
        hrun(h, f"kill -{sig} {' '.join('-' + str(g) for g in groups)} {' '.join(map(str, pids))} 2>/dev/null; sleep {5 if sig == 'TERM' else 1}; true", timeout=30)
        ps = unit_procs(h, unit, roots)
        if not ps: return 0
        pids = sorted({p for p, g in ps}); groups = sorted({g for p, g in ps if g > 1 and g not in safe})
    return len(ps)

def task_pid_roots(h, u):
    """Root processes of a unit started before ORCH_UNIT was set: its pueue task's process (children of pueued whose command
    names the unit), or its tmux/herdr pane process."""
    if u.get("via") in ("herdr", "tmux") and u.get("pid"): return str(u["pid"])
    rc, o, e = hrun(h, "ps -A -o pid=,ppid=,command= | awk -v u=" + shlex.quote(u["name"]) + " '$3 ~ /pueued$/ {d[$1]} {p[$1] = $2; for (i = 3; i <= NF; i++) if ($i == u) m[$1]} "
                       "END {for (x in m) if (p[x] in d) print x}'")
    return " ".join(o.split())

def cmd_stop(cfg, a):
    bd, u = get_unit(cfg, a.unit); h = cfg.hosts[u["host"]]; via = u.get("via"); p = pueue(h)
    why = None if a.force else uncollected(cfg, u)
    if why: raise Err(f"refused: {u['name']}: {why}")
    say(f"stop {u['name']} ({via} on {u['host']})")
    roots = task_pid_roots(h, u) if not DRY else ""
    if DRY: say(f"+ pueue kill / tmux kill-session; TERM then KILL every process group of {u['name']} (roots {roots or '-'}, env ORCH_UNIT)"); return
    if via == "pueue": hrun(h, f"{p} kill {int(u['task'])}")
    elif via == "tmux": hrun(h, f"tmux kill-session -t orch-{u['name']}")
    # its lane jobs (label unit:<name>) belong to it too
    hrun(h, f"{p} status --json | python3 -c \"import json,sys; [print(i) for i, t in json.load(sys.stdin)['tasks'].items() if t.get('label') == 'unit:{u['name']}' and ('Running' in str(t['status']) or 'Queued' in str(t['status']))]\" | xargs -r {p} kill 2>/dev/null; true")
    left = kill_unit(h, u["name"], roots)
    if left: raise Err(f"{u['name']}: {left} process(es) still alive after TERM and KILL")
    for _ in range(10):
        ps = probe(u["host"], h)
        if ps["ok"] and unit_state(u, {u["host"]: ps}, herdr_agents(cfg)) in ("gone", "done", "failed", "idle", "unknown"): break
        time.sleep(1)
    else: raise Err(f"{u['name']} is still alive after stop")
    if u.get("pane") and via != "herdr": herdr("pane", "close", u["pane"])
    if h.get("local"): settle_run(cfg, u, "stopped")   # remote: collect brings back the cost first, close settles the rest
    bd.comment(u["id"], f"{ts()} stopped (every process group of the unit ended)"); cfg.touch("changed"); say("stopped: no process of the unit is left")

DIFF_X = " ".join(f"-x {x}" for x in ("target", ".venv", "node_modules", "__pycache__", ".git"))

def remote_patch(h, n, fname):
    """Write out/<unit>/<fname> on host h: the agent's changes as a patch against the tree it was sent (base/<unit>)."""
    return X(h, f"cd {qp(h['root'])} && [ -d base/{n} ] && {{ diff -ruN {DIFF_X} base/{n} worktrees/{n} | sed -e 's#^--- base/{n}/#--- a/#' -e 's#^+++ worktrees/{n}/#+++ b/#' "
                f"-e 's#^diff -ruN .* base/{n}/\\(.*\\) worktrees/{n}/.*#diff --git a/\\1 b/\\1#' > out/{n}/{fname}; true; }}", timeout=300)

# A remote copy's fingerprint: the checksum of the agent's changes and of its output folder (orch's own files left out), the
# number of output files and the report's lines other than PENDING. collect records it; stop and close compare (item 4).
FINGERPRINT = r'''cd %(root)s 2>/dev/null || exit 3
d=$( { [ -d base/%(n)s ] && diff -ruN %(ex)s base/%(n)s worktrees/%(n)s 2>/dev/null; } | cksum)
f() { cd out/%(n)s 2>/dev/null && find . -type f ! -name changes.patch ! -name backup.patch ! -name 'task-*.log' ! -name '*.key' "$@"; }
o=$(f -exec cksum {} + | sort | cksum); n=$(f | wc -l); p=$(grep -cv '^VERDICT: PENDING$' out/%(n)s/REPORT.md 2>/dev/null)
echo "fp=$d|$o"; echo "n=$n"; echo "p=${p:-0}"'''

def fingerprint(cfg, u):
    h = cfg.hosts[u["host"]]
    rc, o, e = hrun(h, FINGERPRINT % {"root": qp(h["root"]), "n": u["name"], "ex": DIFF_X}, timeout=120)
    if rc: return None
    return dict(l.split("=", 1) for l in o.splitlines() if "=" in l)

def uncollected(cfg, u):
    """Why removing or stopping a remote unit now would lose work (None when nothing would): its copy has changes or output
    that differ from what orch collect last brought here, or its host cannot be asked."""
    h = cfg.hosts.get(u.get("host"), {})
    if h.get("local") or u.get("via") in ("failed", "starting") or DRY: return None
    kv = fingerprint(cfg, u)
    if kv is None: return f"cannot read its copy on {u['host']} (unreachable?), so cannot tell whether work would be lost"
    if kv.get("fp") == u.get("collected"): return None
    d = kv.get("fp", "").split("|")[0].split()
    if len(d) > 1 and d[1] == "0" and int(kv.get("n", "0").strip() or 0) <= 1 and int(kv.get("p", "0").strip() or 0) == 0: return None   # nothing written yet
    return (f"its copy on {u['host']} has changes or output not collected " + (f"since {ts(u['collected_at'])}" if u.get("collected_at") else "yet")
            + f": orch collect {u['name']} first, or --force")

def cmd_collect(cfg, a):
    if ":" in a.unit: return collect_job(cfg, a.unit)
    bd, u = get_unit(cfg, a.unit); h = cfg.hosts[u["host"]]
    if h.get("local"): say("local unit: nothing to collect"); return
    root = h["root"]; n = u["name"]; od = cfg.p("out", "out") / n
    # The agent's changes come back as a patch against the tree it was sent (base/<unit>), never as an rsync over the Mac
    # checkout, which may have moved on or be shared (H9). Apply it with git apply --3way in the unit's worktree.
    remote_patch(h, n, "changes.patch")
    if not save_output(cfg, u): raise Err(f"collect from {u['host']} failed (unreachable?)")   # out/<unit>/, the task log
    if not DRY and not save_transcript(cfg, u): say(f"note: no transcript of {n} saved (none found on {u['host']})")   # out/<unit>/transcript.md
    st = task_status(h, u["task"]) if u.get("via") == "pueue" and u.get("task") is not None and not DRY else None
    if not (st and task_rc(st) is None): X(h, f"rm -f {qp(f'{root}/run/{n}.key')}")   # the key fifo, once no task can still read it (row 52)
    mc = cfg.models.get(u.get("model"), {})
    if not DRY and u.get("via") == "pueue" and mc.get("kind") == "api" and u.get("run"):
        cost, reported = run_cost(od / "api.json", None)
        if reported: ledger_done(cfg, cfg.prov[mc["provider"]], u["run"], n, cost, "collected")   # idempotent: once per run id
    if not DRY and u.get("report"): say(f"report -> {u['report']}")
    kv = fingerprint(cfg, u) if not DRY else None
    if kv: u["collected"] = kv.get("fp"); u["collected_at"] = int(now()); bd.save(u)   # stop and close compare against it
    if not DRY: bd.comment(u["id"], f"{ts()} collected from {u['host']}"); cfg.touch("changed")
    p = od / "changes.patch"
    say(f"collected: {p} ({p.stat().st_size if p.exists() else 0} bytes; apply in {u['cwd']} with git apply --3way)")

def own_tree(cfg, u, units):
    """The unit has a worktree of its own: not the project root, not shared with another open unit."""
    c = Path(u["cwd"]).resolve()
    return c != cfg.root.resolve() and not any(Path(x.get("cwd", "/")).resolve() == c for x in units if x["id"] != u["id"])

def unit_dirty(cfg, cwd):
    """(uncommitted paths the unit owns, whether its tree lies in the project's own repo). Only the unit's cwd subtree counts,
    never orch's state dir or the board's folder (paths.board_dir, default board/): a unit whose cwd is inside the project's
    repo could otherwise never close while other agents' board posts keep that repo dirty. The project's repo is committed and
    pushed by orch commit-state, so its unpushed commits are not the unit's either."""
    rc, top, _ = sh(["git", "-C", str(cwd), "rev-parse", "--show-toplevel"])
    if rc: return [], False
    top = Path(top.strip()).resolve()
    rc, o, e = sh(["git", "status", "--porcelain", "-uall", "--", "."], cwd=cwd)
    if rc: return [], False
    skip = [cfg.state.resolve(), (cfg.root / cfg.paths.get("board_dir", "board")).resolve()]
    out = []
    for l in o.splitlines():
        f = l[3:].split(" -> ")[-1].strip().strip('"'); p = (top / f).resolve()
        if not any(p.is_relative_to(s_) for s_ in skip): out.append(f)
    rc2, ptop, _ = sh(["git", "-C", str(cfg.root), "rev-parse", "--show-toplevel"])
    return out, rc2 == 0 and Path(ptop.strip()).resolve() == top and Path(cwd).resolve() != top

def cmd_close(cfg, a):
    bd, u = get_unit(cfg, a.unit); h = cfg.hosts[u["host"]]; units = bd.units()
    mine = own_tree(cfg, u, units)
    if a.force and not mine: raise Err(f"--force refused: {u['cwd']} is shared (project root or another open unit's cwd)")
    if mine:
        dirty, state_repo = unit_dirty(cfg, u["cwd"])
        if dirty and not a.force: raise Err(f"{u['cwd']} has uncommitted changes ({', '.join(dirty[:3])}); commit and push, or --force")
        rc, o, e = sh(["git", "rev-list", "--count", "@{u}..HEAD"], cwd=u["cwd"])
        if rc == 0 and o.strip() != "0" and not a.force and not state_repo: raise Err("unpushed commits; push first, or --force")
    elif not verdict(cfg, u) and u.get("via") != "failed":   # no tree of its own (H10): the git state is not the unit's; its REPORT is
        raise Err(f"{u['name']} has no final VERDICT line in {report_path(cfg, u)}")
    why = None if a.force else uncollected(cfg, u)
    if why: raise Err(f"refused: {u['name']}: {why}")
    say(f"close {u['name']}" + ("" if mine else " (no worktree of its own: git checks skipped)"))
    if u.get("tab") or u.get("pane"):
        if DRY: say(f"+ herdr tab close {u.get('tab') or u.get('pane')}")
        elif u.get("tab"): herdr("tab", "close", u["tab"])
        else: herdr("pane", "close", u["pane"])
    if not h.get("local"):
        root = h["root"]; n = u["name"]
        others = [x["name"] for x in units if x["id"] != u["id"] and x.get("host") == u["host"] and x.get("rcwd") == u.get("rcwd")]
        if others: say(f"keeping {u.get('rcwd')} on {u['host']}: open unit(s) {', '.join(others)} use it")
        else: X(h, f"cd {qp(root)} && rm -rf worktrees/{n} base/{n} briefs/{n}.md out/{n} run/{n}.* && rmdir worktrees base briefs out run 2>/dev/null; true")
    if u.get("via") == "pueue":   # the task's log is kept under out/<unit>/ before the task is removed
        if not DRY: save_task_log(cfg, h, u, u["task"])
        X(h, f"{pueue(h)} remove {int(u['task'])} 2>/dev/null; true")
    X({"local": True}, f"BOARD_DIR={shlex.quote(str(board_dir(cfg)))} {shlex.quote(str(board_script(cfg)))} close {u['name']} 2>/dev/null; true")
    if DRY: return
    if u.get("run") and unit_state(u, {u["host"]: probe(u["host"], h)}, {}) not in ("working", "queued", "unknown"): settle_run(cfg, u, "closed")
    bd.comment(u["id"], f"{ts()} closed"); bd.run("close", u["id"], "--reason", a.reason or "done"); cfg.touch("changed")
    say("closed")

# ---------------------------------------------------------------- park and resume (orch-fixes9 items 1, 2)
# Agents never pay to wait. An agent submits its builds and tests detached (`orch run --detach`, or its lane runner's
# `--detach`), which prints each job id (<host>:<task>) at once, writes `WAITING <job ids>` in its report and ends its turn.
# The unit is then parked on those jobs (or `orch park <unit>` parks a live agent: its turn is stopped, its jobs keep running).
# When every job has finished, the watcher resumes the same session with each job's exit code and log path: API units get a
# new run (`claude -p --resume <session id>`, or the provider's resume_cmd, e.g. `codex exec resume`) with its own ledger
# rows and the rest of the unit's budget; interactive agents get a prompt (herdr) or the text typed in (tmux). A run that
# ends at its budget cap without a final verdict is resumed once with [budget] wrapup_usd (default 0.5) to write its report.
ENDED = ("done", "failed", "gone", "idle")
WAIT_RX = re.compile(r"^[\s*>-]*WAITING\b\**:?\s*(.*)$", re.M)
JOBREF = re.compile(r"(?<![\w/.-])([A-Za-z0-9][\w.-]*):(\d+)\b")
NO_ACK = ("waiting:",)   # findings an ack cannot hide: they cost money every hour until acted on
WRAPUP = ("Your budget is used up. Do no more work: write your report now ({report}): what is done, the state it is in, what is "
          "left, the real exit codes of everything you ran, and the final line 'VERDICT: BLOCKED' (or DONE if it is done). Then stop.")

def report_text(cfg, u):
    try: return report_path(cfg, u).read_text()
    except OSError: return ""

def waiting_line_jobs(cfg, u):
    """The jobs (<host>:<task>) named on the latest WAITING line of the unit's report that it has not been resumed for yet.
    A resumed unit's report counts only once written after the unit started."""
    try:
        if u.get("resume") and report_path(cfg, u).stat().st_mtime < u.get("started", 0): return []
    except OSError: return []
    m = WAIT_RX.findall(report_text(cfg, u))
    if not m: return []
    done = set(u.get("handled_jobs", []))
    return [j for j in dict.fromkeys(f"{h}:{t}" for h, t in JOBREF.findall(m[-1]) if h in cfg.hosts) if j not in done]

def job_state(hs, ref):
    """(state, exit code) of job <host>:<task> from the probes: queued | admission (running, waiting in orch's admission) |
    running | done | gone (no such task any more) | unknown (host unreachable) | paused, stashed, locked."""
    hn, _, tid = ref.partition(":"); p = hs.get(hn) or {}
    if not p.get("ok"): return "unknown", None
    t = ((p.get("pueue") or {}).get("tasks") or {}).get(tid)
    if not t: return "gone", None
    rc = task_rc(t)
    if rc is not None: return "done", rc
    k = t["status"] if isinstance(t["status"], str) else next(iter(t["status"]), "")
    if k == "Running": return ("admission" if job_of(t) in p.get("waitjob", []) else "running"), None
    return k.lower(), None

def unit_jobs(hs, name):
    """The unit's own jobs that have not finished (pueue label unit:<name>, any host): ['<host>:<task>']."""
    return [f"{hn}:{tid}" for hn, p in hs.items() for tid, t in ((p.get("pueue") or {}).get("tasks") or {}).items()
            if t.get("label") == f"unit:{name}" and task_rc(t) is None]

def unit_runs(u): return list(dict.fromkeys([*u.get("runs", []), *([u["run"]] if u.get("run") else [])]))

def unit_spent(cfg, u, wrapup=False):
    """Dollars the unit's runs have used (ledger: each run's done cost, its budget while it runs), over all its resumes; the
    wrap-up run is outside the unit's budget and counted only with wrapup=True."""
    pv = cfg.prov.get(cfg.models.get(u.get("model"), {}).get("provider"), {})
    if "ledger" not in pv: return 0.0
    runs = ledger_read(cfg, pv)[0]
    return sum((r["cost"] or 0.0) if r["done"] else (r["budget"] or 0.0) for k in unit_runs(u)
               if (r := runs.get(k)) and (wrapup or k != u.get("wrapup")))

def api_out(cfg, u):
    try: return json.loads((cfg.p("out", "out") / u["name"] / "api.json").read_text())
    except Exception: return {}

def session_of(cfg, u):
    """The agent's session id: its api.json (session_id; Codex: thread_id), else its newest transcript (a run stopped before
    it wrote its json): here ~/.claude/projects/<cwd>, on a remote host the same under that host's agent_env HOME."""
    d = api_out(cfg, u); sid = d.get("session_id") or d.get("thread_id")
    if sid: return sid
    h = cfg.hosts.get(u.get("host"), {})
    if h.get("local"):
        f = transcript_of(cfg, u); return f.stem if f else None
    esc = re.sub(r"[^A-Za-z0-9-]", "-", u.get("rcwd") or "")
    rc, o, e = hrun(h, f"{h.get('agent_env', '')}\nls -t \"$HOME/.claude/projects/{esc}\"/*.jsonl 2>/dev/null | head -1")
    return Path(o.strip()).stem if rc == 0 and o.strip() else None

def job_result(cfg, hs, ref, agent_host):
    """(exit code or None, log path the agent can read) of a finished job. A remote job's files are copied here first when
    the agent runs here (orch collect <host>:<task> does the same)."""
    hn, _, tid = ref.partition(":"); h = cfg.hosts[hn]; p = hs.get(hn) or {}
    t = ((p.get("pueue") or {}).get("tasks") or {}).get(tid); jid = job_of(t); rc = task_rc(t); rd = runs_dir(cfg, h)
    here = cfg.hosts.get(agent_host, {}).get("local")
    if not jid:   # a task without a job script (a gate): its pueue log is the log
        loc = cfg.f("runs") / f"task-{hn}-{tid}.log"; loc.parent.mkdir(exist_ok=True)
        r = hrun(h, f"{pueue(h)} log {int(tid)} --full", timeout=60)
        if r[0] == 0 and not DRY: loc.write_text(r[1])
        return rc, str(loc) if here or h.get("local") else f"{hn}: {pueue(h)} log {tid}"
    if rc is None or t is None:
        o = hrun(h, f"cat {qp(f'{rd}/{jid}.rc')} 2>/dev/null")[1].strip()
        rc = int(o) if o.lstrip("-").isdigit() else rc
    if hn == agent_host or (h.get("local") and here): return rc, f"{rd}/{jid}.log"
    if here:
        loc = cfg.f("runs"); loc.mkdir(exist_ok=True)
        sh(["rsync", "-a", "-e", " ".join(SSH), f"{h['ssh']}:{rd}/{jid}.*", f"{loc}/"], timeout=300)
        return rc, str(loc / f"{jid}.log")
    return rc, f"{hn}:{rd}/{jid}.log"

def resume_message(cfg, hs, u, jobs):
    L = [f"Your jobs finished (orch resumed you; you used ${unit_spent(cfg, u):.2f} of ${u.get('budget') or 0:g} so far):"]
    for j in jobs:
        rc, log = job_result(cfg, hs, j, u.get("host"))
        L.append(f"- {j}: exit {rc if rc is not None else 'unknown (the task is gone and left no exit code)'}; log {log}")
    L.append("Read the logs you need, then continue the brief from where your report stands. Same rule as before: submit "
             "builds and tests detached, write 'WAITING <job ids>' in the report and end your turn; keep the report current; "
             "end with the VERDICT line and the real exit codes.")
    return "\n".join(L)

def resume_unit(cfg, u, msg, wrapup=False):
    """Continue the unit's own agent session with msg (see above). The caller saves u. Returns a line saying what was done."""
    name = u["name"]; h = cfg.hosts[u["host"]]; mc = cfg.models.get(u.get("model"), {}); via = u.get("via"); text = ORCH_MARK + msg
    if via == "herdr":
        if not DRY: herdr("agent", "prompt", name, text)
        return f"{name}: prompted in its herdr pane"
    if via == "tmux":
        X(h, f"tmux send-keys -t orch-{name} -l {shlex.quote(text)} && tmux send-keys -t orch-{name} Enter")
        return f"{name}: resumed in tmux orch-{name} on {u['host']}"
    if via != "pueue" or mc.get("kind") != "api": raise Err(f"{name}: a unit run via {via} cannot be resumed")
    pv = cfg.prov[mc["provider"]]; od = cfg.p("out", "out") / name
    sid = session_of(cfg, u)
    if not sid: raise Err(f"{name}: no session id (api.json or transcript) to resume")
    if u.get("run"):   # the run before is closed first (idempotent): its reported cost, else its budget
        cost, _ = run_cost(od / "api.json", (u.get("budget") or pv.get("budget_per_unit", 0)) if u.get("run") != u.get("wrapup") else bset(cfg, "wrapup_usd"))
        ledger_done(cfg, pv, u["run"], name, cost, "resumed")
    if wrapup: budget = bset(cfg, "wrapup_usd")
    else:
        budget = round((u.get("budget") or pv.get("budget_per_unit", 0)) - unit_spent(cfg, u), 2)
        if budget < bset(cfg, "resume_min_usd"):
            raise Err(f"{name}: ${budget:.2f} of its ${u.get('budget')} budget left (under [budget] resume_min_usd); resume it with orch launch --resume-of and a new budget")
    k = len(unit_runs(u)) + 1; run = f"{name}.r{k}.{int(now())}"
    run = reserve_budget(cfg, mc, name, budget, run)
    local = h.get("local", False); old = u.get("task")
    report = str(report_path(cfg, u)) if local else f"{h['root']}/out/{name}/REPORT.md"
    env = {"ORCH_ROLE": "agent", "ORCH_REPORT": report, "ORCH_UNIT": name, "ORCH_ROOT": str(cfg.root)}
    if local:
        pf = od / f"resume-{k}.md"
        if not DRY: atomic_write(pf, text)
        cmd = shlex.join([sys.executable, str(ORCH_SELF), "api-run", name, "--run", run, "--model", u["model"], "--budget", str(budget),
                          "--brief", u.get("rbrief") or u["brief"], "--cwd", u["rcwd"], "--report", report, "--resume-session", sid, "--prompt-file", str(pf)])
        rc, o, e = X(h, f"{pueue(h)} add -g agents -l {name} -w {shlex.quote(u['rcwd'])} --print-task-id -- {pq(cmd)}", env=env)
    else:
        rc, o, e = api_remote(cfg, h, name, mc, u.get("rbrief") or f"{h['root']}/briefs/{name}.md", u["rcwd"], budget, text, env, session=sid, run=run)
    if rc:
        if not DRY: ledger_done(cfg, pv, run, name, 0, "resume-failed")
        raise Err(f"{name}: resume failed: {(e or o).strip()[:120]}")
    if DRY: return f"{name}: would resume session {sid} as run {run} (${budget:g})"
    st, why = confirm_started(cfg, h, int(o.strip() or 0))
    if st == "died":
        ledger_done(cfg, pv, run, name, 0, "died-at-start")
        raise Err(f"{name}: the resumed run died at once ({why})")
    if old is not None: save_task_log(cfg, h, u, old, remove=True)   # the finished task's log is kept, then the task removed
    u.update(task=int(o.strip() or 0), run=run, runs=[*unit_runs(u), run], resumes=u.get("resumes", 0) + 1, resumed_at=int(now()))
    if wrapup: u["wrapup"] = run
    return f"{name}: resumed session {sid[:8]} as run {run} (${budget:g}{', wrap-up' if wrapup else ''}), task {u['task']}"

def save_task_log(cfg, h, u, tid, remove=False):
    """Keep a pueue task's log under out/<unit>/task-<id>.log (the agent's stdout and stderr), then optionally remove the task."""
    rc, o, e = hrun(h, f"{pueue(h)} log {int(tid)} --full", timeout=60)
    if rc == 0 and not DRY:
        od = cfg.p("out", "out") / u["name"]; od.mkdir(parents=True, exist_ok=True); atomic_write(od / f"task-{tid}.log", o)
        if remove: hrun(h, f"{pueue(h)} remove {int(tid)} 2>/dev/null; true")
    return rc == 0

def cmd_park(cfg, a):
    """Stop a live agent's turn while its jobs wait or run (the remedy for waiting:<unit>); the watcher resumes it, same session,
    when they finish. API units: the run is ended (SIGTERM: its cost is still recorded); herdr and tmux agents: Escape."""
    bd, u = get_unit(cfg, a.unit); h = cfg.hosts[u["host"]]; n = u["name"]
    hs = probe_all(cfg); jobs = unit_jobs(hs, n)
    if not jobs: raise Err(f"{n} has no queued or running job of its own: nothing to wait for (orch stop {n} to stop it)")
    say(f"park {n}: its jobs {', '.join(jobs)} keep running; it resumes when they finish")
    if DRY: return
    via = u.get("via")
    if via == "pueue":
        hrun(h, f"{pueue(h)} kill -s SIGTERM {int(u['task'])} 2>/dev/null; true")
        for _ in range(30):
            if task_rc(task_status(h, u["task"])) is not None: break
            time.sleep(2)
        else: hrun(h, f"{pueue(h)} kill {int(u['task'])} 2>/dev/null; true")
        if h.get("local"): settle_run(cfg, u, "parked")
    elif via == "herdr": herdr("pane", "send-keys", u["pane"], "Escape")
    elif via == "tmux": X(h, f"tmux send-keys -t orch-{n} Escape")
    u["parked"] = {"jobs": jobs, "since": int(now()), "by": "orch park"}; bd.save(u)
    bd.comment(u["id"], f"{ts()} parked on {', '.join(jobs)}"); cfg.touch("changed"); say(f"parked {n}")

def cmd_resume(cfg, a):
    """Resume a unit's own session now: parked (its jobs' results, when they finished), or with --message."""
    bd, u = get_unit(cfg, a.unit); hs = probe_all(cfg)
    jobs = (u.get("parked") or {}).get("jobs") or waiting_line_jobs(cfg, u)
    if a.message: msg = a.message
    elif jobs:
        left = [j for j in jobs if job_state(hs, j)[0] not in ("done", "gone")]
        if left and not a.force: raise Err(f"{u['name']} waits on {', '.join(left)}, not finished (--force to resume now)")
        msg = resume_message(cfg, hs, u, jobs)
    else: raise Err(f"{u['name']} is not parked: give --message")
    say(resume_unit(cfg, u, msg))
    if DRY: return
    u["handled_jobs"] = [*u.get("handled_jobs", []), *jobs]; u.pop("parked", None); bd.save(u)
    bd.comment(u["id"], f"{ts()} resumed"); cfg.touch("changed")

def save_output(cfg, u):
    """Bring a remote unit's output folder here (out/<unit>/: REPORT.md, api.json and each run's api-<run>.json, logs; never the
    key fifo) and keep its pueue task's log; a resumed unit's report also goes back to its original path. True when done."""
    h = cfg.hosts[u["host"]]; n = u["name"]; od = cfg.p("out", "out") / n
    cmd = ["rsync", "-a", "--exclude", "*.key", "-e", " ".join(SSH), f"{h['ssh']}:{h['root']}/out/{n}/", str(od) + "/"]
    if DRY: say("+ " + shlex.join(cmd)); return True
    od.mkdir(parents=True, exist_ok=True)
    if sh(cmd, timeout=600)[0]: return False
    if u.get("via") == "pueue" and u.get("task") is not None: save_task_log(cfg, h, u, u["task"])
    if u.get("report") and (od / "REPORT.md").is_file(): atomic_write(Path(u["report"]), (od / "REPORT.md").read_text())
    return True

def refresh_remote(cfg, u, bd, log):
    """A remote unit's output is read here: saved once when its agent's turn ended (then its verdict, WAITING line and api.json
    are judged here), and every [collect] backup_min while it runs (item 4)."""
    if cfg.hosts[u["host"]].get("local") or u.get("via") in ("failed", "starting"): return
    fin = u.get("state") in ENDED
    if not ((fin and u.get("saved") != u.get("task")) or now() - u.get("saved_at", 0) > cfg.c.get("collect", {}).get("backup_min", 30) * 60): return
    remote_patch(cfg.hosts[u["host"]], u["name"], "backup.patch")   # the agent's changes so far, as a patch (out/<unit>/backup.patch)
    if not save_output(cfg, u): log(f"{u['name']}: saving its output from {u['host']} failed"); return
    u["saved_at"] = int(now())
    if fin: u["saved"] = u.get("task")
    bd.save(u)
    u["verdict"] = v = verdict(cfg, u)
    if not v and not u.get("_park") and (fin or u.get("via") == "tmux"):
        pk = waiting_line_jobs(cfg, u)
        if pk: u["_park"] = pk; u["state"] = "parked"

def tend_parked(cfg, hs, units, log):
    """The watcher's part: record parked units, resume those whose jobs all finished, wrap up capped runs (item 2)."""
    bd = Beads(cfg)
    for u in units:
        try:
            refresh_remote(cfg, u, bd, log)
            jobs = u.get("_park")
            if jobs:
                if (u.get("parked") or {}).get("jobs") != jobs:
                    u["parked"] = {"jobs": jobs, "since": int(now()), "by": "report"}; bd.save(u); log(f"park {u['name']} on {', '.join(jobs)}")
                    if card_fields(cfg, u["name"]).get("state") != "waiting": board(cfg, "post", u["name"], "waiting", " ".join(jobs))   # never SILENT/GONE
                st = [job_state(hs, j)[0] for j in jobs]
                if all(x in ("done", "gone") for x in st):
                    log(resume_unit(cfg, u, resume_message(cfg, hs, u, jobs)))
                    u["handled_jobs"] = [*u.get("handled_jobs", []), *jobs]; u.pop("parked", None); bd.save(u)
                    bd.comment(u["id"], f"{ts()} resumed: jobs {', '.join(jobs)} finished")
                continue
            if wrap_due(cfg, u):
                log(resume_unit(cfg, u, WRAPUP.format(report=report_path(cfg, u) if cfg.hosts[u["host"]].get("local") else f"{cfg.hosts[u['host']]['root']}/out/{u['name']}/REPORT.md"), wrapup=True))
                bd.save(u); bd.comment(u["id"], f"{ts()} ended at its budget cap without a verdict: resumed once to write its report")
        except Err as e: log(f"{u['name']}: {e}")

def wrap_due(cfg, u):
    """A run that ended at its budget cap without a final verdict, not yet wrapped up (item 2)."""
    mc = cfg.models.get(u.get("model"), {})
    return (u.get("via") == "pueue" and mc.get("kind") == "api" and u.get("state") in ENDED and not u.get("verdict") and not u.get("wrapup")
            and api_out(cfg, u).get("subtype") == "error_max_budget_usd" and not u.get("_park"))

# ---------------------------------------------------------------- backlog and landing (orch-fixes7)
# The backlog lives in beads: `orch backlog import` turns every unfinished item of the project's status checklist into a beads
# issue labelled backlog and status:<its status>, keyed by external ref backlog:<item id> (idempotent: a re-import updates
# status labels, closes items that became done, reopens ones that came back). check then raises "idle with backlog" when a host
# has room while backlog items have no open unit, and "finished, not landing" when a finished unit has no gate, or its gates
# passed and it is not on the landing branch.
def slug(t): return re.sub(r"[^a-z0-9]+", "-", t.lower()).strip("-")[:40]

def backlog_cfg(cfg):
    b = dict(cfg.c.get("backlog", {})); b.setdefault("file", cfg.paths.get("checklist"))
    return b

def backlog_items(cfg, actors=None):
    """[(id, title, status, done, ready)] from the checklist ([backlog] file, default paths.checklist): markdown table rows (the
    header row names the columns: id_col '#', title_col 'item', status_col 'status') and '- [ ] item' / '- [x] item' lines.
    done: status starts with one of [backlog] done (default DONE). ready: not done, and the status starts with one of
    [backlog] ready (default: every status), so items waiting on the owner can be left out of 'idle with backlog'."""
    b = backlog_cfg(cfg)
    if not b.get("file"): return None
    try: text = (cfg.root / b["file"]).read_text()
    except OSError: return None
    idc, tc, sc, ac = (b.get(k, d).lower() for k, d in (("id_col", "#"), ("title_col", "item"), ("status_col", "status"), ("actor_col", "actor")))
    dn = [x.upper() for x in b.get("done", ["DONE"])]; rd = [x.upper() for x in b.get("ready", [])]
    items, hdr, seen = [], None, set()
    def add(i, t, st):
        if not t or i in seen: return
        seen.add(i); d = any(st.upper().startswith(x) for x in dn)
        items.append((i, t, st, d, not d and (not rd or any(st.upper().startswith(x) for x in rd))))
    for l in text.splitlines():
        s = l.strip()
        if s.startswith("#"): hdr = None; continue
        if s.startswith("|"):
            cells = [c.strip() for c in s.strip("|").split("|")]
            if all(re.fullmatch(r":?-*:?", c) for c in cells): continue
            low = [c.lower() for c in cells]
            if tc in low and sc in low: hdr = low; continue
            if hdr and len(cells) >= len(hdr):
                r = dict(zip(hdr, cells)); t = r.get(tc, "")
                add(r.get(idc) or slug(t), t, r.get(sc, ""))
                if actors is not None and r.get(ac, "").strip(): actors[r.get(idc) or slug(t)] = r[ac].strip().lower()
            continue
        m = re.match(r"^[-*] \[( |x|X)\] (.+)$", s)
        if m: add(slug(m.group(2)), m.group(2), "DONE" if m.group(1) != " " else "OPEN")
    return items

def item_actors(cfg):
    """{item id: actor} (row 54): who does the item. The checklist's actor column ([backlog] actor_col, default "actor"), else
    the beads label actor:<x> that `orch backlog set <id> actor=<x>` sets (the label wins). Unset: agent. Only agent items
    count as idle backlog or are filled; owner, hardware and any other actor never are."""
    a = {}; backlog_items(cfg, a)
    try:
        for r, i in backlog_issues(cfg).items():
            x = next((l[6:] for l in (i.get("labels") or []) if l.startswith("actor:")), None)
            if x: a[r[8:]] = x
    except Err: pass
    return a

def backlog_issues(cfg):
    r = Beads(cfg).run("list", "--label", "backlog", "--all", "-n", "0")
    r = r.get("issues", r) if isinstance(r, dict) else r
    return {i.get("external_ref"): i for i in r if str(i.get("external_ref", "")).startswith("backlog:")}

def cmd_backlog(cfg, a):
    if a.action == "set":   # orch backlog set <id> actor=<x>
        if not a.args or len(a.args) != 2 or not a.args[1].startswith("actor="): raise Err("usage: orch backlog set <item id> actor=<agent|owner|hardware|...>")
        x = backlog_issues(cfg).get(f"backlog:{a.args[0]}")
        if not x: raise Err(f"no backlog item {a.args[0]} in beads (orch backlog import first)")
        v = slug(a.args[1][6:]) or "agent"; labels = [l for l in (x.get("labels") or []) if not l.startswith("actor:")] + ([f"actor:{v}"] if v != "agent" else [])
        if DRY: say(f"+ bd update {x['id']} --set-labels {','.join(labels)}"); return
        Beads(cfg).run("update", x["id"], "--set-labels", ",".join(labels)); cfg.touch("changed"); say(f"{a.args[0]}: actor {v}"); return
    items = backlog_items(cfg)
    if items is None: raise Err("no checklist: set [backlog] file (or paths.checklist) in orch.toml")
    if a.action == "list":
        act = item_actors(cfg)
        for i, t, st, d, rd in items: say(f"{'done ' if d else 'ready' if rd else 'wait '} {i:8} {act.get(i, 'agent'):8} {st[:24]:24} {t[:90]}")
        return
    bd = Beads(cfg); ex = backlog_issues(cfg); n = {"created": 0, "updated": 0, "closed": 0, "reopened": 0, "same": 0}
    for i, t, st, d, rd in items:
        ref = f"backlog:{i}"; labels = ["backlog", "status:" + (slug(st) or "none")] + (["backlog-ready"] if rd else [])
        x = ex.get(ref); title = f"backlog: {i} {t}"[:150]
        if DRY: say(f"+ {ref}: {'close' if d and x else 'skip' if d else 'update' if x else 'create'} ({st[:30]})"); continue
        if d:
            if x and x.get("status") != "closed": bd.run("close", x["id"], "--reason", f"checklist: {st[:60]}"); n["closed"] += 1
            continue
        if not x:
            r = bd.run("create", title, "-l", ",".join(labels), "-d", f"From {backlog_cfg(cfg)['file']}: {t}\nstatus: {st}", "--external-ref", ref)
            n["created"] += 1; continue
        if x.get("status") == "closed": bd.run("reopen", x["id"]); n["reopened"] += 1
        labels += [l for l in (x.get("labels") or []) if l.startswith("actor:")]   # set by orch backlog set: kept
        if sorted(x.get("labels") or []) != sorted(labels) or x.get("title") != title:
            bd.run("update", x["id"], "--title", title, "--set-labels", ",".join(labels)); n["updated"] += 1
        else: n["same"] += 1
    if not DRY: cfg.touch("backlog_imported"); cfg.touch("changed")
    say(f"backlog: {len(items)} checklist items; " + ", ".join(f"{v} {k}" for k, v in n.items()))

def unit_items(cfg, units):
    """Backlog item ids that open units cover: their --item / ITEM: line, or an item id named in the first lines of their brief."""
    out = set()
    for u in units:
        if u.get("item"): out.add(u["item"])
        try: out.update(re.findall(r"[A-Za-z0-9][\w.-]*", "\n".join(Path(u["brief"]).read_text().splitlines()[:6])))
        except (OSError, KeyError): pass
    return out

def backlog_findings(cfg, hs, units):
    b = backlog_cfg(cfg)
    if not b.get("file"): return []
    try: iss = backlog_issues(cfg)
    except Err: return []
    if not iss:
        return [("backlog:import", f"the checklist {b['file']} is not in beads: orch backlog import")]
    F = []
    if (cfg.root / b["file"]).exists() and (cfg.root / b["file"]).stat().st_mtime > cfg.mtime("backlog_imported") + 60:
        F.append(("backlog:stale", f"{b['file']} changed since the last orch backlog import: run it again"))
    cov = unit_items(cfg, units); act = item_actors(cfg)
    todo = [(r[8:], i.get("title", "")[9:]) for r, i in iss.items()
            if i.get("status") in ("open", "in_progress") and "backlog-ready" in (i.get("labels") or []) and r[8:] not in cov
            and act.get(r[8:], "agent") == "agent"]   # owner and hardware items are never idle backlog (row 54)
    if not todo: return F
    plan, stops = fill_plan(cfg, hs, units)
    if plan:   # orch-fixes8 item 4: how many ready units with briefs fit now
        per = {}
        for x in plan: per[x[3]] = per.get(x[3], 0) + 1
        F.append(("idle-with-backlog", f"{len(plan)} ready backlog unit(s) with briefs would fit now ({', '.join(f'{k}: {v}' for k, v in per.items())}): "
                  + ", ".join(x[0] for x in plan[:6]) + ("..." if len(plan) > 6 else "") + "; run orch fill (orch fill --dry-run shows why it stops there)"))
    briefed = {x[2] for x in fill_candidates(cfg, units)}
    nob = [(i, t) for i, t in todo if i not in briefed]
    if nob and not plan and any("budget" in s for s in stops):
        F.append(("idle-backlog:budget", f"budget-limited: {'; '.join(s for s in stops if 'budget' in s)[:160]}; {len(nob)} ready item(s) wait"))
    elif nob and any(room(cfg, n, p, units)[0] > 0 for n, p in hs.items() if p.get("ok")):
        F.append(("idle-backlog:nobrief", f"{len(nob)} ready backlog item(s) have no unlaunched brief while hosts have room: write briefs (ITEM: <id> line) for: "
                  + "; ".join(t[:50] for _, t in nob[:6]) + ("..." if len(nob) > 6 else "")))
    return F

def gate_results(cfg):
    """{gate name: (time, PASS|FAIL)}, the latest line of each gate in paths.gate_log."""
    try: lines = cfg.p("gate_log", "out/gates.log").read_text().splitlines()
    except OSError: return {}
    r = {}
    for l in lines:
        m = GATE_LINE.match(l)
        if m: r[m.group(1)] = (l[:19], m.group(2))
    return r

def landed(cfg, u):
    """True when the unit's worktree HEAD is on the landing branch ([landing] branch, default the main repo's HEAD branch):
    an ancestor of it, or (squash-landed, orch land) its tree is the tree of one of the branch's last 200 commits. None when
    it cannot be told (no worktree of its own)."""
    c = Path(u.get("cwd", "/"))
    if c.resolve() == cfg.root.resolve() or not c.is_dir(): return None
    br = cfg.c.get("landing", {}).get("branch")
    if not br:
        rc, o, e = sh(["git", "-C", str(c), "symbolic-ref", "--short", "refs/remotes/origin/HEAD"])
        br = o.strip() if rc == 0 and o.strip() else "main"
    rc, o, e = sh(["git", "-C", str(c), "merge-base", "--is-ancestor", "HEAD", br])
    if rc != 1: return True if rc == 0 else None
    t = sh(["git", "-C", str(c), "rev-parse", "HEAD^{tree}"])[1].strip()
    return t in sh(["git", "-C", str(c), "log", "--format=%T", "-n", "200", br])[1].split()

def landing_findings(cfg, units, hs=None):
    ld = cfg.c.get("landing", {}); mins = ld.get("finished_min", 30); need = ld.get("gates_required", 1)
    pats = ld.get("gate_names", ["{unit}", "land-{unit}", "land-{unit}-*", "{unit}-*"])
    import fnmatch
    res = gate_results(cfg); queued = set()
    for p in (hs or {}).values():
        for t in ((p.get("pueue") or {}).get("tasks") or {}).values():
            lab = t.get("label") or ""
            if lab.startswith("gate:") and any(k in str(t.get("status")) for k in ("Queued", "Running")): queued.add(lab[5:])
    F = []
    for u in units:
        v = u.get("verdict") or ""
        if u.get("state") not in ("done", "failed", "gone", "idle") or "DONE" not in v or u.get("kind", "implement") not in ld.get("kinds", ["implement"]): continue
        try: fin = report_path(cfg, u).stat().st_mtime
        except OSError: continue
        age = (now() - fin) / 60
        if age < mins: continue
        names = set(u.get("gates", [])) | {n for n in set(res) | queued if any(fnmatch.fnmatch(n, x.format(unit=u["name"])) for x in pats)}
        if names & queued: continue
        passed = sorted(n for n in names if res.get(n, ("", ""))[1] == "PASS")
        if not names:
            F.append((f"landing:{u['name']}:nogate", f"{u['name']} finished {age:.0f} min ago (VERDICT DONE) with no gate queued: orch gate <name> --unit {u['name']}"))
        elif len(passed) >= need and landed(cfg, u) is False:
            F.append((f"landing:{u['name']}:unlanded", f"{u['name']}: gate(s) {', '.join(passed)} passed, finished {age:.0f} min ago, not landed: land it, then orch close"))
    return F

# ---------------------------------------------------------------- budgets from history, spend so far (orch-fixes8 item 5)
# A unit's default budget is the median cost of the past finished runs of its kind and tier (ledger done rows joined to the
# units that ran them), plus [budget] margin_pct; with fewer than min_runs runs, the provider's budget_per_unit. A running
# API unit's spend so far is estimated from its Claude Code transcript (tokens per model, priced at the rate learned from
# finished runs' api.json), so check can say when a unit nears its budget with its report not updated.
BUDGET_DEFAULTS = {"margin_pct": 30, "min_runs": 3, "min_usd": 0.5, "max_usd": None, "warn_pct": 80, "report_stale_min": 10,
                   "wrapup_usd": 0.5, "resume_min_usd": 0.1,
                   "token_weights": {"input": 1.0, "output": 5.0, "cache_write": 1.25, "cache_read": 0.1}}

def bset(cfg, k): return cfg.c.get("budget", {}).get(k, BUDGET_DEFAULTS[k])

def all_units(cfg):
    """Every unit ever recorded (open and closed): {name: meta}; the latest record of a name wins."""
    if getattr(cfg, "_all_units", None) is None:
        try:
            r = Beads(cfg).run("list", "--label", "unit", "--all", "-n", "0")
            r = r.get("issues", r) if isinstance(r, dict) else r
        except Err: r = []
        out = {}
        for i in sorted(r, key=lambda i: i.get("created_at", "")):
            t = i.get("title", "")
            if not t.startswith("unit:"): continue
            try: m = json.loads(i.get("notes") or "{}")
            except Exception: m = {}
            out[t[5:]] = {**m, "id": i["id"], "name": t[5:], "status": i.get("status")}
        cfg._all_units = out
    return cfg._all_units

def cost_history(cfg, provider):
    """{(kind, tier): [cost of each finished run]} of a provider, oldest first."""
    pv = cfg.prov[provider]
    if "ledger" not in pv: return {}
    runs = ledger_read(cfg, pv)[0]; us = all_units(cfg); byrun = {u.get("run"): u for u in us.values() if u.get("run")}
    out = {}
    for k, r in runs.items():
        if not r["done"] or r["cost"] is None: continue
        u = byrun.get(k) or us.get(r["unit"])
        if not u or not u.get("kind"): continue
        out.setdefault((u["kind"], u.get("tier") or "normal"), []).append(r["cost"])
    return out

def budget_for(cfg, mc, kind, tier):
    """(budget USD, why) for a new API unit of this kind and tier."""
    pv = cfg.prov[mc["provider"]]; d = pv.get("budget_per_unit", 15)
    c = cost_history(cfg, mc["provider"]).get((kind, tier), [])
    if len(c) < bset(cfg, "min_runs"): return d, f"budget_per_unit; {len(c)} past {kind}/{tier} run(s), {bset(cfg, 'min_runs')} needed to learn"
    s = sorted(c); med = s[len(s) // 2] if len(s) % 2 else (s[len(s) // 2 - 1] + s[len(s) // 2]) / 2
    b = max(bset(cfg, "min_usd"), -(-med * (100 + bset(cfg, "margin_pct")) / 100 * 2 // 1) / 2)   # rounded up to $0.50
    if bset(cfg, "max_usd"): b = min(b, bset(cfg, "max_usd"))
    return b, f"median ${med:.2f} of {len(c)} past {kind}/{tier} run(s) + {bset(cfg, 'margin_pct')}%"

def token_cost(usage, w, rate):
    """Dollars for a usage dict (api.json usage or transcript message usage) at rate $ per weighted token."""
    return rate * (w["input"] * usage.get("input_tokens", usage.get("inputTokens", 0)) + w["output"] * usage.get("output_tokens", usage.get("outputTokens", 0))
                   + w["cache_write"] * usage.get("cache_creation_input_tokens", usage.get("cacheCreationInputTokens", 0))
                   + w["cache_read"] * usage.get("cache_read_input_tokens", usage.get("cacheReadInputTokens", 0)))

def learned_rates(cfg):
    """{model id: $ per weighted token}, from the modelUsage of the newest finished api.json files (cost / weighted tokens)."""
    if getattr(cfg, "_rates", None) is not None: return cfg._rates
    w = bset(cfg, "token_weights"); acc = {}
    fs = sorted(cfg.p("out", "out").glob("*/api.json"), key=lambda p: p.stat().st_mtime, reverse=True)[:60]
    for f in fs:
        try: mu = json.loads(f.read_text()).get("modelUsage") or {}
        except Exception: continue
        for m, x in mu.items():
            wt = token_cost(x, w, 1.0)
            if wt > 0 and isinstance(x.get("costUSD"), (int, float)): a = acc.setdefault(m, [0.0, 0.0]); a[0] += x["costUSD"]; a[1] += wt
    cfg._rates = {m: c / wt for m, (c, wt) in acc.items() if wt}
    return cfg._rates

def transcript_of(cfg, u):
    """The Claude Code transcript of a local API unit: under ~/.claude/projects/<its cwd>, started after the unit, whose first
    prompt names its brief."""
    d = Path.home() / ".claude/projects" / re.sub(r"[^A-Za-z0-9-]", "-", str(u.get("rcwd") or u.get("cwd") or ""))
    try: fs = sorted(d.glob("*.jsonl"), key=lambda p: p.stat().st_mtime, reverse=True)
    except OSError: return None
    for f in fs[:20]:
        if f.stat().st_mtime < u.get("started", 0): break
        try:
            with open(f) as fh: head = "".join(next(fh, "") for _ in range(8))
        except OSError: continue
        if any(b and (b in head or Path(b).name in head) for b in (u.get("rbrief"), u.get("brief"))): return f
    return None

def unit_spend(cfg, u):
    """(dollars so far, how known) of an API unit: its api.json cost when finished, else its transcript priced at the learned
    rate; (None, why) when it cannot be told (remote, no transcript, no learned rate)."""
    try:
        c = json.loads((cfg.p("out", "out") / u["name"] / "api.json").read_text()).get("total_cost_usd")
        if isinstance(c, (int, float)): return float(c), "api.json"
    except Exception: pass
    if not cfg.hosts.get(u.get("host"), {}).get("local"): return None, "remote"
    f = transcript_of(cfg, u)
    if not f: return None, "no transcript"
    return transcript_cost(cfg, f)

def transcript_cost(cfg, f, since=0):
    """(dollars, "transcript") of a Claude Code transcript's assistant messages (those after since, a time), priced at the
    learned rate; (None, why) without a learned rate."""
    rates = learned_rates(cfg); w = bset(cfg, "token_weights"); seen = {}
    for l in open(f, errors="replace"):
        if '"usage"' not in l: continue
        try: d = json.loads(l)
        except Exception: continue
        m = d.get("message") or {}
        if since:
            try:
                if calendar.timegm(time.strptime(d.get("timestamp", "")[:19], "%Y-%m-%dT%H:%M:%S")) < since: continue   # UTC
            except ValueError: pass
        if d.get("type") == "assistant" and isinstance(m, dict) and m.get("usage"): seen[m.get("id") or len(seen)] = (m.get("model"), m["usage"])
    if not seen: return 0.0, "transcript"
    tot = 0.0
    for mdl, us in seen.values():
        r = rates.get(mdl) or (sum(rates.values()) / len(rates) if rates else None)
        if r is None: return None, "no learned rate (no finished api.json yet)"
        tot += token_cost(us, w, r)
    return tot, "transcript"

def budget_findings(cfg, units):
    F = []
    for u in units:
        if u.get("state") not in ("working", "queued") or not u.get("budget"): continue
        sp, how = unit_spend(cfg, u)
        if sp is None or sp < bset(cfg, "warn_pct") / 100 * u["budget"]: continue
        try: age = (now() - report_path(cfg, u).stat().st_mtime) / 60
        except OSError: age = (now() - u.get("started", now())) / 60
        if age >= bset(cfg, "report_stale_min"):
            F.append((f"budget80:{u['name']}", f"{u['name']} has spent about ${sp:.2f} of its ${u['budget']:g} budget ({100 * sp / u['budget']:.0f}%, {how}) "
                      f"and its report has not changed for {age:.0f} min: direct it to write its state to the report now (board.sh direct), "
                      f"or stop it and resume with a larger --budget (--resume-of keeps its report)"))
    return F

# ---------------------------------------------------------------- report: completeness, remaining work, spend by outcome (item 6)
# Every ledger run gets one outcome: "verdict" (its unit ended with a final verdict), "capped-partial" / "capped-nothing" (it
# ended at its budget cap and its unit has no final verdict: with or without work written: report lines, a patch), "open"
# (its unit is still open, no verdict yet), "no-verdict" (ended, not capped, unit closed without a verdict), "unknown" (no done
# row: its end was never recorded). check raises waste:<unit> for an open unit whose run ended at its cap without a verdict,
# report-due at [report] checkpoints, and waste-pause when capped-without-verdict spend passes [report] waste_pause (default
# 25 %) of the spend of the last recent_h hours: launch and fill are refused until the orchestrator acks waste-pause.
OUTCOMES = (("verdict", "finished with a verdict"), ("capped-partial", "capped, partial work"), ("capped-nothing", "capped, nothing written"),
            ("open", "open unit, no verdict yet"), ("no-verdict", "ended without a verdict"), ("unknown", "unknown (no done row)"))
REPORT_DEFAULTS = {"every_h": 4, "at": [], "waste_pause": 25, "recent_h": 24}

def rset(cfg, k): return cfg.c.get("report", {}).get(k, REPORT_DEFAULTS[k])

def work_written(cfg, u, since=0):
    """The unit left work: report lines beyond its VERDICT line, a non-empty patch of its changes, or in its worktree a commit
    made since the run started (since) or uncommitted changes."""
    t = [l for l in report_text(cfg, u).splitlines() if l.strip() and not l.startswith("VERDICT:") and not l.startswith("WAITING")]
    od = cfg.p("out", "out") / u["name"]
    if len(t) >= 2 or any((od / f).is_file() and (od / f).stat().st_size > 0 for f in ("changes.patch", "backup.patch")): return True
    c = Path(u.get("cwd") or "/nonexistent")
    if not c.is_dir() or c.resolve() == cfg.root.resolve(): return False
    if since and sh(["git", "-C", str(c), "log", f"--since={int(since)}", "--format=%H", "-1"])[1].strip(): return True
    return bool(sh(["git", "-C", str(c), "status", "--porcelain", "--untracked-files=no"])[1].strip())

def run_outcomes(cfg):
    """[(provider, run id, unit name, dollars, outcome, time)] for every ledger run."""
    us = all_units(cfg); open_ = {u["name"] for u in us.values() if u.get("status") in ("open", "in_progress")}
    byrun = {k: u for u in us.values() for k in unit_runs(u)}; out = []
    for pn, pv in cfg.prov.items():
        if "ledger" not in pv: continue
        for k, r in ledger_read(cfg, pv)[0].items():
            u = byrun.get(k) or us.get(r["unit"]) or {"name": r["unit"]}
            try: t = time.mktime(time.strptime(r["ts"][:19], "%Y-%m-%d %H:%M:%S"))
            except (ValueError, TypeError): t = 0
            cost = r["cost"] if r["done"] else (r["budget"] or 0.0)
            od = cfg.p("out", "out") / u["name"]
            try: aj = json.loads((od / f"api-{k}.json").read_text())
            except Exception: aj = api_out(cfg, u) if k == (u.get("run") or k) else {}
            v = verdict(cfg, {**u, "resume": False}) if u.get("name") else None
            if v: o = "verdict"
            elif aj.get("subtype") == "error_max_budget_usd": o = "capped-partial" if work_written(cfg, u, t) else "capped-nothing"
            elif not r["done"]: o = "open" if u["name"] in open_ else "unknown"
            elif u["name"] in open_: o = "open"
            else: o = "no-verdict"
            out.append((pn, k, u["name"], float(cost or 0), o, t))
    return out

def waste_state(cfg, outs=None):
    """(capped-without-verdict dollars, all dollars, share %) of the runs of the last [report] recent_h hours."""
    outs = run_outcomes(cfg) if outs is None else outs; cut = now() - rset(cfg, "recent_h") * 3600
    rec = [x for x in outs if x[5] >= cut]; tot = sum(x[3] for x in rec); w = sum(x[3] for x in rec if x[4].startswith("capped"))
    return w, tot, (100 * w / tot if tot else 0.0)

def waste_paused(cfg):
    """Why launch and fill are paused (wasted spend over [report] waste_pause % of recent spend, not acked), or None."""
    w, tot, pct = waste_state(cfg)
    if pct <= rset(cfg, "waste_pause") or "waste-pause" in live_acks(cfg): return None
    return (f"${w:.2f} of ${tot:.2f} ({pct:.0f} %) of the last {rset(cfg, 'recent_h')} h went to runs that ended at their budget cap without a "
            f"verdict (limit {rset(cfg, 'waste_pause')} %): find the cause (orch report), then orch ack waste-pause \"<cause and fix>\"")

def last_checkpoint(cfg):
    """The latest report checkpoint passed: [report] at (local HH:MM times) and every every_h hours from midnight."""
    t = now(); lt = time.localtime(t); mid = time.mktime((*lt[:3], 0, 0, 0, 0, 0, -1)); cps = []
    for x in rset(cfg, "at"):
        try: h, m = map(int, str(x).split(":")); c = mid + h * 3600 + m * 60; cps.append(c if c <= t else c - 86400)
        except ValueError: pass
    if rset(cfg, "every_h"): e = rset(cfg, "every_h") * 3600; cps.append(mid + ((t - mid) // e) * e)
    return max(cps) if cps else None

def report_findings(cfg, units):
    F = []
    for u in units:
        if u.get("state") in ENDED and not u.get("verdict") and api_out(cfg, u).get("subtype") == "error_max_budget_usd":
            w = "a wrap-up resume did not write one either" if u.get("wrapup") else "the watcher resumes it once to write its report"
            F.append((f"waste:{u['name']}", f"{u['name']} ended at its budget cap (${fl(api_out(cfg, u).get('total_cost_usd')):.2f}) without a verdict ({w}); "
                      f"{'work was written' if work_written(cfg, u) else 'nothing was written'}: read its report, resume it with --resume-of and a larger budget, or close it"))
    why = waste_paused(cfg)
    if why: F.append(("waste-pause", "launch and fill PAUSED: " + why))
    cp = last_checkpoint(cfg)
    if cp and cfg.mtime("report_sent") < cp: F.append(("report-due", f"a status report to the owner is due (checkpoint {ts(cp)}): orch report, send it, then orch report --sent"))
    return F

def cmd_report(cfg, a):
    """The owner's status report: backlog completeness and remaining work, spend by outcome, the waste rule, open units.
    --brief: the summary lines only. --sent: record that it was sent (clears report-due until the next checkpoint)."""
    if a.sent: cfg.touch("report_sent"); say("report marked sent"); return 0
    L = [f"orch report: {cfg.name}, {ts()}"]
    items = backlog_items(cfg)
    if items is not None:
        act = item_actors(cfg); done = [x for x in items if x[3]]; left = [x for x in items if not x[3]]
        try: cov = unit_items(cfg, Beads(cfg).units())
        except Err: cov = set()
        L.append(f"Backlog: {len(done)} of {len(items)} items done ({100 * len(done) // max(len(items), 1)} %); {len(left)} left: "
                 + ", ".join(f"{n} {k}" for k, n in sorted(Counter_(act.get(i, 'agent') for i, *_ in left).items())) + f"; {sum(1 for i, *_ in left if i in cov)} in open units")
        if not a.brief:
            for i, t, st, d, rd in left[:40]: L.append(f"  {'*' if i in cov else ' '} {i:10} [{act.get(i, 'agent')}] {st[:20]:20} {t[:80]}")
    outs = run_outcomes(cfg)
    for pn in dict.fromkeys(x[0] for x in outs):
        mine = [x for x in outs if x[0] == pn]; tot = sum(x[3] for x in mine)
        L.append(f"Spend {pn}: ${tot:.2f} in {len(mine)} run(s)")
        for k, lab in OUTCOMES:
            xs = [x for x in mine if x[4] == k]
            if xs: L.append(f"  {lab:28} ${sum(x[3] for x in xs):8.2f}  {len(xs):3} run(s)  {100 * sum(x[3] for x in xs) / max(tot, 1e-9):4.0f} %"
                            + ("" if a.brief or k in ("verdict",) else ": " + ", ".join(dict.fromkeys(x[2] for x in xs))[:120]))
    w, tot, pct = waste_state(cfg, outs)
    L.append(f"Last {rset(cfg, 'recent_h')} h: ${w:.2f} of ${tot:.2f} ({pct:.0f} %) capped without a verdict; limit {rset(cfg, 'waste_pause')} %"
             + (": launch and fill PAUSED until orch ack waste-pause" if waste_paused(cfg) else ""))
    try:
        us = Beads(cfg).units()
        L.append(f"Open units: {len(us)}" + ("" if a.brief else ": " + ", ".join(u["name"] for u in us)[:300]))
    except Err as e: L.append(f"Open units: unavailable ({e})")
    for l in L: say(l)
    return 0

def Counter_(it):
    c = {}
    for x in it: c[x] = c.get(x, 0) + 1
    return c

# ---------------------------------------------------------------- fill: launch ready work up to capacity (orch-fixes8 item 4)
BRIEF_KEYS = re.compile(r"^(ITEM|KIND|TIER|TEST-HOST|PRIORITY):\s*(\S+)", re.M)

def brief_index(cfg):
    """[(path, unit name, {ITEM, KIND, TIER, TEST-HOST, PRIORITY}, head text)] of every brief, newest first."""
    out = []
    for f in sorted(cfg.p("briefs", "briefs").glob("*.md"), key=lambda p: p.stat().st_mtime, reverse=True):
        try:
            with open(f, errors="replace") as fh: head = "".join(next(fh, "") for _ in range(12))
        except OSError: continue
        out.append((f, f.stem, {k: v.rstrip(".,;") for k, v in BRIEF_KEYS.findall(head)}, head))
    return out

def fill_candidates(cfg, units):
    """Ready backlog items with a brief and no unit, highest priority first: [(priority, order, item, brief path, unit name,
    kind, tier)]. Items: the beads backlog (open, backlog-ready; priority from beads), else the checklist (its order). A brief
    is for an item when its ITEM: line names it (an explicit mark: a brief that merely mentions an item may be old or a
    review); a brief whose unit name was ever launched, or that has an out/<name> folder, is spent. The newest brief wins."""
    try: iss = backlog_issues(cfg)
    except Err: iss = {}
    if iss: items = [(int(i.get("priority", 2) if i.get("priority") is not None else 2), n, r[8:], i.get("title", "")[9:]) for n, (r, i) in enumerate(iss.items())
                     if i.get("status") in ("open", "in_progress") and "backlog-ready" in (i.get("labels") or [])]
    else: items = [(int(2), n, i, t) for n, (i, t, st, d, rd) in enumerate(backlog_items(cfg) or []) if rd]
    cov = unit_items(cfg, units); ever = all_units(cfg); out = []; idx = brief_index(cfg); taken = set(); act = item_actors(cfg)
    for pr, order, item, title in sorted(items):
        if item in cov or act.get(item, "agent") != "agent": continue
        for f, name, keys, head in idx:
            if keys.get("ITEM", "").lower() != item.lower(): continue
            if name in ever or name in taken or (cfg.p("out", "out") / name).exists(): continue
            if not re.fullmatch(r"[a-z][a-z0-9_-]{0,31}", name): continue
            tier = "critical" if keys.get("TIER", "").upper() in ("CRITICAL", "HIGH") else "normal"
            kind = keys.get("KIND", "implement").lower()
            pr2 = int(keys["PRIORITY"]) if keys.get("PRIORITY", "").isdigit() else pr
            out.append((pr2, order, item, f, name, kind if kind in ("implement", "review", "audit", "cleanup") else "implement", tier)); taken.add(name)
            break
    return sorted(out, key=lambda x: (x[0], x[1]))

def fill_plan(cfg, hs, units, limit=None):
    """(plan [(name, item, model, agent host, build host, budget, why)], stops [why the rest does not launch now]): candidates
    in priority order, each placed by choose() against the open units plus those planned before it, until the hosts'
    reservations or the provider budgets are used."""
    plan, stops, virt, spent = [], [], [dict(u) for u in units], {}
    cands = fill_candidates(cfg, units)
    if not cands: return plan, ["no ready backlog item has an unlaunched brief (a brief is for an item when it has an ITEM: <id> line)"]
    for pr, order, item, f, name, kind, tier in cands:
        if limit and len(plan) >= limit: stops.append(f"--max {limit} reached; {len(cands) - len(plan)} more candidate(s)"); break
        a = argparse.Namespace(unit=name, host=None, test_host=None, kind=kind, tier=tier)
        try: m = pick_model(cfg, tier, kind, None)
        except Err as e: stops.append(f"{name}: {e}"); continue
        mc = cfg.models[m]; budget, bwhy = budget_for(cfg, mc, kind, tier) if mc.get("kind") == "api" else (None, "")
        pv = cfg.prov.get(mc.get("provider"), {})
        if budget is not None and "cap_usd" in pv:
            left = pv["cap_usd"] - committed(cfg, pv) - spent.get(mc["provider"], 0)
            if left < budget: stops.append(f"budget: {mc['provider']} has ${left:.2f} left, {name} needs ${budget:g}"); break
        try: hn, b, why = choose(cfg, a, f, mc, virt, hs)
        except Err as e: stops.append((name, str(e).removeprefix("refused, "))); continue
        if budget is not None: spent[mc["provider"]] = spent.get(mc["provider"], 0) + budget
        plan.append((name, item, m, hn, b, budget, f"{why}; priority {pr}", kind, tier, f))
        virt.append({"name": name, "host": hn, "build": b, "state": "working", "item": item})
    if not stops: stops.append("every ready candidate is planned")
    grp = {}   # one line per reason: the candidates it holds back
    for s in stops:
        n, w = s if isinstance(s, tuple) else (None, s)
        grp.setdefault(w, []).append(n)
    return plan, [(f"{len(ns)} candidate(s) ({', '.join(ns[:5])}{'...' if len(ns) > 5 else ''}): " if ns[0] else "") + w for w, ns in grp.items()]

def cmd_fill(cfg, a):
    """Launch ready backlog units that have briefs, highest priority first, until every host's reservations or the budget are
    used, and no further. --dry-run lists what it would launch now and why it stops there."""
    if DRY: cfg.ro = True   # a dry run changes nothing anywhere (the probe leaves the hosts' reservation files alone)
    hs = probe_all(cfg); units = Beads(cfg).units(); ag = herdr_agents(cfg)
    for u in units: u["state"] = unit_state(u, hs, ag)
    wp = waste_paused(cfg)
    if wp: say(f"fill: PAUSED: {wp}"); return 1
    plan, stops = fill_plan(cfg, hs, units, a.max)
    say(f"fill: {len(plan)} unit(s) fit now" + (" (dry run: nothing launched)" if DRY else ""))
    for name, item, m, hn, b, budget, why, kind, tier, f in plan:
        say(f"  {name} [{item}] {kind}/{tier} model {m} on {hn}, builds on {b}" + (f", ${budget:g}" if budget is not None else "") + f": {why}")
    say("stops: " + "; ".join(dict.fromkeys(stops)))
    if DRY: return 0
    rc = 0
    for name, item, m, hn, b, budget, why, kind, tier, f in plan:
        la = argparse.Namespace(unit=name, kind=kind, tier=tier, host=None, model=m, brief=str(f), cwd=None, budget=None, test_host=None,
                                allow_main=False, of=None, report=None, resume_of=None, item=item, dry_run=False)
        try: cmd_launch(cfg, la)
        except Err as e: say(f"fill: {name} not launched: {e}"); rc = 1
    cfg.touch("last_fill")
    return rc

# ---------------------------------------------------------------- run / gate: build and test jobs in each host's own pueue
# A job belongs to the host's pueue daemon, never to the ssh connection that queued it: if the caller dies the job keeps running,
# and its log and exit code stay under <root>/runs/<jid>.{log,rc} on that host for `orch collect <host>:<task>`.
LANES = ("gates", "jobs", "land")
AGE_MIN = {"gates": 240, "jobs": 120, "land": 240}   # class age limits (minutes from enqueue); orch.toml [lanes.<lane>] age_min overrides
LSSH = [*SSH, "-o", "ServerAliveInterval=30", "-o", "ServerAliveCountMax=4"]

def lane_age(cfg, lane): return cfg.c.get("lanes", {}).get(lane, {}).get("age_min", AGE_MIN.get(lane, 120))

def slots(h, cfg=None):
    """pueue parallel limit of a host's jobs lane: the jobs its cores hold (cores // cores_per_job). Pueue only orders the
    work; each job still waits for admission by reservations (runs/cap.sh), which also counts memory."""
    n = cap_nums(cfg, h); return max(1, n["cores"] // n["cpj"])

def agent_res(cfg, hn, h, name, pid):
    """An interactive agent's reservation (runs/agent-<unit>.res, its pane's pid), as API agents write theirs: the shell admission
    (cap.sh) then counts it like the launcher does (review-fixes8 #3); it is dropped when the pid is gone."""
    if not pid: return
    mb = class_mb([], "agent", cap_nums(cfg, h)["agmb"], 0)
    write_cap(cfg, hn, h)
    hrun(h, f"mkdir -p {qp(h['_rd'])} && echo '{int(pid)} 0 {int(mb)} {int(now())} agent' > {qp(h['_rd'] + f'/agent-{name}.res')}")

def ensure_lanes(h, cfg=None):
    p = pueue(h); n = slots(h, cfg)
    g = {"agents": 1, "jobs": n, "gates": h.get("gate_slots", n)} | ({"land": 1} if h.get("local") else {})
    return "; ".join(f"{p} group add -p {int(k)} {g_} >/dev/null 2>&1" for g_, k in g.items()) + "; true"

def runs_dir(cfg, h): return h["_rd"]

def write_cap(cfg, hn, h):
    """Write runs/cap.sh on host h (write-then-rename): waiting jobs pick up the current rule at their next poll."""
    rd = h["_rd"]
    if h.get("local"): Path(rd).mkdir(parents=True, exist_ok=True); atomic_write(Path(rd) / "cap.sh", cap_lib(cfg, hn, h)); return 0, "", ""
    d = qp(rd); return hrun(h, f"mkdir -p {d} && cat > {d}/.cap.sh.$$ && mv -f {d}/.cap.sh.$$ {d}/cap.sh", inp=cap_lib(cfg, hn, h))

ADMIT = r'''# Admission (orch-fixes8): by reservations, rule in $RD/cap.sh (re-read each poll). One job is judged at a time under the lock;
# an admitted job writes its reservation ($R.res) before the lock is released. A jobs-lane job yields while a gates job waits.
[ -f "$RD/cap.sh" ] || { echo "orch: no $RD/cap.sh on this host (orch run or orch launch writes it)"; exit 125; }
lane=%(lane)s; . "$RD/cap.sh"; CLS=$(cap_class %(clsrc)s)
if command -v flock >/dev/null 2>&1; then exec 7>>"$RD/admit.lock"; lk() { flock 7; }; ulk() { flock -u 7; }
else   # no flock: a lock dir holding its owner's pid; a dead owner's dir is taken over (a SIGKILL never leaves the host stuck)
  lk() { until mkdir "$RD/admit.d" 2>/dev/null; do o=$(cat "$RD/admit.d/pid" 2>/dev/null); [ -n "$o" ] && ! kill -0 "$o" 2>/dev/null && rm -rf "$RD/admit.d"; sleep 1; done; echo $$ > "$RD/admit.d/pid"; HELD=1; }
  ulk() { rm -rf "$RD/admit.d"; HELD=; }; fi
gates_waiting() { for f in "$RD"/*.gwait; do [ -e "$f" ] && kill -0 "$(cat "$f")" 2>/dev/null && return 0; done; return 1; }
W="$R.wait"; [ "$lane" = gates ] && W="$R.gwait"; echo $$ > "$W"
HELD=; trap 'rm -f "$W" "$R.res"; [ -n "$HELD" ] && rm -rf "$RD/admit.d"' EXIT; trap 'rm -f "$W" "$R.res"; [ -n "$HELD" ] && rm -rf "$RD/admit.d"; exit 143' TERM INT HUP   # a job killed while waiting leaves no files (L1)
said=
while :; do
  if [ "$lane" = gates ] || ! gates_waiting; then
    lk; CAP_RO=; . "$RD/cap.sh"
    if admit_ok "$CLS"; then echo "$$ $CPJ $MB $(date +%%s) $CLS" > "$R.res.$$" && mv -f "$R.res.$$" "$R.res"; ulk; break; fi
    ulk; [ "$said" = "$BLK" ] || { echo "orch: waiting for admission ($CLS; $BLK): $why"; said=$BLK; }
  fi
  sleep ${ORCH_POLL_S:-15}
done
rm -f "$W"; exec 7>&-; trap 'rm -f "$R.res"' EXIT
echo "orch: admitted ($CLS, reserves $CPJ cores and $MB MB): $why"
run_sampled() {  # run "$@", sample its memory every 5 s, then add class, peak MB, seconds and exit code to $RD/history.tsv
  t0=$(date +%%s); "$@" & pid=$!; peak=0
  while kill -0 $pid 2>/dev/null; do v=$(job_mb $pid %(jid)s); [ "${v:-0}" -gt "$peak" ] 2>/dev/null && peak=$v; sleep 5; done
  wait $pid; rc=$?; cap_record "$CLS" "$peak" $(( $(date +%%s) - t0 )) $rc; return $rc
}
'''

def ctr(h):
    """A podman host's container settings ([hosts.<h>.container]): image, mount (host dir, default the host's root), mount_at
    (default /f), args, usb_args, usb_lock, host_dirs, name_prefixes, cpus."""
    c = dict(h.get("container", {})); c.setdefault("mount", h.get("fleet", h.get("root", "/tmp"))); c.setdefault("mount_at", "/f")
    return c

def in_container(h, path):
    """A host path as a podman job sees it (under the mount), or the path itself."""
    if h.get("runner") != "podman": return path
    c = ctr(h); m = c["mount"].rstrip("/")
    return c["mount_at"] + path[len(m):] if path.startswith(m + "/") else path

def remote_wt(h, name):
    """Where `orch run` syncs a worktree on a remote host."""
    if h.get("runner") == "podman": return f"{ctr(h)['mount']}/worktrees/{name}"
    return f"{h.get('worktrees', h.get('root', '$HOME/orch') + '/worktrees')}/{name}"

def job_script(cfg, hn, h, a, name, cmd, jid, wd=None, clsrc=None):
    """The bash script pueue runs on the host. Output is tee'd to <runs>/<jid>.log, the exit code written to <jid>.rc.
    Every lane on every host (the Mac too, register item 5) waits for admission by reservations (ADMIT, runs/cap.sh), holds
    its reservation while it runs, and records its class's peak memory in runs/history.tsv. clsrc: shell text giving the
    command whose class it is (default the command itself). wd: the tree on the host (a remote agent's copy); default the
    synced worktree of that name. Per host (orch.toml): run_env (shell run first), job_setup (shell run in the worktree before
    the command), job_log (a line per job start/end), and for runner = "podman" the [hosts.<h>.container] settings."""
    q = shlex.quote; rd = h["_rd"]; sub = a.subdir or "."; sub_ = lambda x: str(x).replace("{name}", name).replace("{jid}", jid)
    head = f"#!/bin/bash\n# orch run {jid}: host {hn}, lane {a.lane}, worktree {name}\nRD={qp(rd)}; R=\"$RD\"/{q(jid)}\nexport ORCH_WRAP={q(jid)}   # orch run inside records the jobs it queues under this (cancel follows them)\n"
    setup = h.get("job_setup", ""); log = h.get("job_log", h.get("fleet_log", "/dev/null"))
    adm = ADMIT % {"lane": q(a.lane), "clsrc": clsrc or q(cmd), "jid": q(jid)}
    if h.get("local"):
        pre = ""
        if a.lane == "land":   # the local landing lane also waits for: the disk floor, the host's admit_check, no legacy_lanes lane busy
            ck = h.get("admit_check", ""); base = h.get("legacy_lanes", ""); ce = h.get("admit_check_env", "")
            pre = (f"said=\nwhile :; do d=$(df -Pk {q(str(cfg.root))} | awk 'NR==2{{print int($4/1048576)}}'); busy=\n"
                   f"  for s in {base}; do o=$(cat $s/pid 2>/dev/null); [ -n \"$o\" ] && kill -0 $o 2>/dev/null && busy=$s; done\n"
                   f"  [ \"$d\" -ge {h.get('min_disk_gb', 5)} ] && {{ [ -z {q(ck)} ] || {ce + ' ' if ce else ''}sh {q(ck)} >/dev/null 2>&1; }} && [ -z \"$busy\" ] && break\n"
                   f"  [ \"$said\" ] || {{ echo \"orch: land lane waiting (disk ${{d}} GB, floor {h.get('min_disk_gb', 5)}; old lane busy: ${{busy:-none}})\"; said=1; }}; sleep 15; done\n")
        body = f"{pre}cd {q(str(Path(wd or a.wt).resolve()))} && cd {q(sub)} || exit $?\n{adm}run_sampled nice -n 10 bash -c {q(cmd)}\n"
    else:
        cap = int(h.get("job_gb", 2) * 1024)
        scope = f"systemd-run --user --scope -q {q('--unit=orch-' + jid)} -p MemoryMax={cap}M --"
        if h.get("runner") == "podman":   # the job runs in the host's container settings, capped at job_gb
            c = ctr(h)
            if not c.get("image"): raise Err(f"host {hn}: runner podman needs [hosts.{hn}.container] image")
            inner = (f"({setup}) && " if setup else "") + f"cd {q(sub)} && {cmd}"
            hw = " ".join(map(q, map(sub_, c.get("usb_args", [])))) + " " if a.usb else ""
            hw_ = wd or remote_wt(h, name); cw = in_container(h, hw_)
            args = " ".join(q(sub_(x)) for x in c.get("args", []))
            body = (f"[ -d {qp(hw_)} ] || {{ echo {q(f'orch: no worktree {hw_} on {hn}')}; exit 2; }}\n"
                    + "".join(f"mkdir -p {q(sub_(d))}\n" for d in c.get("host_dirs", []))
                    + (f"exec 8>{qp(c['usb_lock'])}; flock 8\n" if a.usb and c.get("usb_lock") else "") + adm +
                    f"printf '%s orch-run start [%s] %s %s\\n' \"$(date '+%F %T')\" {q(name)} {q(jid)} {q(cmd)} >> {qp(log)}\n"
                    f"run_sampled {scope} nice -n 15 ionice -c 3 podman run --rm --init --name {q('orch-run-' + jid)} {hw}"
                    f"--memory={cap}m --memory-swap={cap}m --cpus={q(str(c.get('cpus', h.get('cores_per_job', 2))))} -v {qp(c['mount'])}:{q(c['mount_at'])} -w {qp(cw)} {args} "
                    f"{q(c['image'])} bash -c {q(inner)}; rc=$?\n"
                    f"printf '%s orch-run end [%s] %s exit %s\\n' \"$(date '+%F %T')\" {q(name)} {q(jid)} $rc >> {qp(log)}\nexit $rc\n")
        else:
            wd = wd or remote_wt(h, name)
            body = (f"{h.get('run_env', '')}\ncd {qp(wd)} && " + (f"({setup}) && " if setup else "") + f"cd {q(sub)} || exit $?\n" + adm +
                    f"printf '%s orch-run [%s] %s %s\\n' \"$(date '+%F %T')\" {q(name)} {q(jid)} {q(cmd)} >> {qp(log)}\n"
                    f"run_sampled {scope} nice -n 10 bash -c {q(cmd)}\n")
    return head + "main() {\n" + body + "}\nmain 2>&1 | tee -a \"$R.log\"\nrc=${PIPESTATUS[0]}; echo $rc > \"$R.rc\"; exit $rc\n"

def sync_wt(cfg, hn, h, src, name):
    """Sync a worktree to the host: --checksum and no -t (a changed file gets the transfer time as its mtime, so cargo never
    reuses an artifact built from older content), without the host's sync_exclude list (default .git, target, .venv,
    node_modules; anchor an entry with a leading / so nested folders of that name are still synced). A podman host first clones
    its container.clone_base (cp --reflink) when the worktree is new. Every path in paths.sync_require that exists here must
    arrive (a missing one has broken gates before)."""
    ex = [y for x in h.get("sync_exclude", [".git", "target", ".venv", "node_modules"]) for y in ("--exclude", x)]
    dst = remote_wt(h, name)
    if h.get("runner") == "podman" and ctr(h).get("clone_base"):
        rc, o, e = hrun(h, f"[ -d {qp(dst)} ] || cp -a --reflink=always {qp(ctr(h)['clone_base'])} {qp(dst)}", timeout=300)
        if rc: raise Err(f"reflink clone on {hn} failed: {(e or o).strip()[-120:]}")
    rdst = dst.replace("$HOME/", "")   # rsync resolves a relative path under the remote home
    cmd = ["rsync", "-rlpgoD", "--checksum", "--delete", "-e", " ".join(SSH), *ex, f"{src}/", f"{h['ssh']}:{rdst}/"]
    r = subprocess.run(cmd)
    if r.returncode: raise Err(f"rsync to {hn} failed (exit {r.returncode})")
    for x in cfg.paths.get("sync_require", []):
        if (Path(src) / x).exists() and hrun(h, f"test -e {qp(dst + '/' + x)}")[0]: raise Err(f"{x} did not arrive on {hn}")

def task_status(h, tid):
    rc, o, e = hrun(h, f"{pueue(h)} status --json", timeout=30)
    if rc: return None
    try: return (json.loads(o).get("tasks") or {}).get(str(tid))
    except Exception: return None

def task_rc(t):
    s = (t or {}).get("status"); k = s if isinstance(s, str) else next(iter(s or {}), "")
    if k != "Done": return None
    r = s["Done"].get("result") if isinstance(s, dict) else None
    if r == "Success": return 0
    if isinstance(r, dict) and "Failed" in r: return int(r["Failed"])
    return 137 if r == "Killed" else 1

def finish_job(cfg, hn, h, tid, jid, quiet=False):
    """Wait for the task (retrying through ssh drops), print its log, return its exit code."""
    miss = 0
    while True:
        if h.get("local"): rc = subprocess.run(["sh", "-c", f"{pueue(h)} wait -q {int(tid)}"]).returncode
        else: rc = subprocess.run([*LSSH, h["ssh"], f"{pueue(h)} wait -q {int(tid)}"], stdin=subprocess.DEVNULL).returncode
        t = task_status(h, tid)
        if task_rc(t) is not None: break
        miss = miss + 1 if t is None and rc != 255 else 0
        if miss >= 5:   # the task is gone (removed or cleaned): its rc file, else give up (M16)
            r2, o2, _ = hrun(h, f"cat {qp(f'{runs_dir(cfg, h)}/{jid}.rc')} 2>/dev/null")
            if o2.strip().lstrip("-").isdigit(): return int(o2.strip())
            print(f"orch: {hn} task {tid} is gone and left no exit code", file=sys.stderr); return 255
        print(f"orch: {hn} task {tid} not done yet (wait exit {rc}); retrying", file=sys.stderr); time.sleep(30 if rc == 255 or t is None else 5)
    rd = runs_dir(cfg, h)
    if not quiet:
        if h.get("local"): subprocess.run(["cat", f"{rd}/{jid}.log"])
        else: subprocess.run([*LSSH, h["ssh"], f"cat {qp(f'{rd}/{jid}.log')}"], stdin=subprocess.DEVNULL)
    rc, o, e = hrun(h, f"cat {qp(f'{rd}/{jid}.rc')} 2>/dev/null")
    try: return int(o.strip())
    except ValueError: return task_rc(t)

def cmd_run(cfg, a):
    hn = a.host
    if hn not in cfg.hosts: raise Err(f"unknown host {hn}")
    h = cfg.hosts[hn]
    if a.lane == "land" and not h.get("local"): raise Err("the land lane is the Mac's")
    cmd = a.command[1:] if a.command[:1] == ["--"] else a.command
    if not cmd: raise Err("no command")
    cmd = cmd[0] if len(cmd) == 1 else shlex.join(cmd)   # one argument is shell text; several are quoted words
    src = str(Path(a.wt).resolve()); name = Path(src).name
    if not Path(src).is_dir(): raise Err(f"worktree {src} not found")
    unit = a.unit or os.environ.get("ORCH_UNIT")
    why = tree_guard(cfg, src, behind=a.lane in ("gates", "land"))   # behind main matters for gates and landing only (item 5)
    if why and not a.allow_unmerged: raise Err(f"refused: {src} {why} (--allow-unmerged to run anyway)")
    jid = f"{re.sub(r'[^A-Za-z0-9_-]', '_', name)[:40]}-{time.strftime('%m%d-%H%M%S')}-{os.getpid()}"
    if DRY: say(job_script(cfg, hn, h, a, name, cmd, jid)); return
    if not h.get("local"): sync_wt(cfg, hn, h, src, name)
    rd = runs_dir(cfg, h)
    if h.get("local"): Path(rd).mkdir(parents=True, exist_ok=True)
    rc, o, e = hrun(h, f"mkdir -p {qp(rd)} && cat > {qp(f'{rd}/{jid}.sh')} && {ensure_lanes(h, cfg)}", inp=job_script(cfg, hn, h, a, name, cmd, jid))
    if not rc: rc, o, e = write_cap(cfg, hn, h)
    if rc: raise Err(f"writing the job to {hn} failed: {(e or o).strip()[-120:]}")
    label = f"unit:{unit}" if unit else f"run:{name}"   # unit:<name>: check reports it once that unit is closed (M3)
    rc, o, e = hrun(h, f"{pueue(h)} add -g {shlex.quote(a.lane)} -l {shlex.quote(label)} -w {qp(rd)} --print-task-id"
                       + (f" -o {int(a.priority)}" if a.priority else (" -o 10" if a.lane == "gates" else "")) + f" -- {pq('bash ' + qp(f'{rd}/{jid}.sh'))}")
    if rc: raise Err(f"pueue add on {hn} failed: {(e or o).strip()[-120:]}")
    tid = o.strip()
    if not DRY:   # the tree this job uses, for orch busy (row 53): one line per job, dropped once the job has ended
        bd_ = cfg.f("runs") / "busy"; bd_.mkdir(parents=True, exist_ok=True); (bd_ / jid).write_text(f"{hn}:{tid}\t{src}\n")
    wrap = os.environ.get("ORCH_WRAP")   # queued from inside another orch job or gate (a wrapper): record it, so cancel follows (row 49)
    if wrap and re.fullmatch(r"[\w.-]+", wrap):
        wd = cfg.f("runs") / "wrap"; wd.mkdir(parents=True, exist_ok=True)
        with open(wd / wrap, "a") as f: f.write(f"{hn}:{tid} {jid}\n")
    print(f"orch: queued {hn}:{tid} ({a.lane}, {label}) job {jid}; collect with: orch collect {hn}:{tid}", file=sys.stderr)
    if a.no_wait: say(f"{hn}:{tid}"); return
    return finish_job(cfg, hn, h, tid, jid)

def tree_guard(cfg, wt, behind=True):
    """Why a tree must not be built or gated (issues 33, 41): a merge in progress, conflict markers in changed files, or (behind:
    the gates and land lanes and orch gate only, never an agent's own jobs; orch-fixes9 item 5) more than [landing] max_behind
    (default 10) commits behind the landing branch. None when fine or not a git tree."""
    g = lambda *x: sh(["git", "-C", str(wt), *x])
    if g("rev-parse", "--git-dir")[0]: return None
    if g("rev-parse", "-q", "--verify", "MERGE_HEAD")[0] == 0: return "has a merge in progress (MERGE_HEAD)"
    rc, o, e = g("diff", "--name-only", "--diff-filter=U")
    if o.strip(): return f"has unmerged files: {' '.join(o.split()[:3])}"
    rc, o, e = g("grep", "-n", "-I", "-E", "^(<<<<<<<|>>>>>>>) ", "--", ".")
    if rc == 0 and o.strip(): return f"has conflict markers ({o.splitlines()[0][:80]})"
    if not behind: return None
    br = cfg.c.get("landing", {}).get("branch") or "main"; mx = cfg.c.get("landing", {}).get("max_behind", 10)
    rc, o, e = g("rev-list", "--count", f"HEAD..{br}")
    if rc == 0 and o.strip().isdigit() and int(o) > mx: return f"is {o.strip()} commits behind {br} (max {mx}): merge {br} first"
    return None

BUSY_PATTERNS = ["mutants"]   # [busy] patterns default: tools that edit the tree in place while they run (mutation testing)

def busy_reasons(cfg, wt, hs=None, ps=None):
    """Why the tree wt is in use (row 53): an orch job queued or running on it (any host and lane; a job whose host does not
    answer counts as busy), an open unit's own jobs when the unit's cwd is wt (a remote agent's lane jobs on its copy), or a
    local process matching [busy] patterns (default: mutation testing, which edits sources in place) that runs in or names
    the tree. A periodic WIP snapshot must not commit while any holds."""
    names = {str(Path(wt).absolute()), str(Path(wt).resolve())}; wt = Path(wt).resolve(); why = []
    bdir = cfg.f("runs") / "busy"; recs = []
    for f in sorted(bdir.glob("*")) if bdir.is_dir() else []:
        try: ref, src = f.read_text().strip().split("\t", 1)
        except ValueError: continue
        recs.append((f, ref, Path(src)))
    hosts = {r.split(":")[0] for _, r, _ in recs}
    units = []
    try: units = Beads(cfg).units()
    except Err: pass
    mine = [u for u in units if u.get("cwd") and Path(u["cwd"]).resolve() == wt]
    if hs is None:   # a unit's jobs may run on any host; job records name theirs
        hs = probe_all(cfg) if mine else {n: probe(n, cfg.hosts[n], cfg=cfg) for n in hosts if n in cfg.hosts}
    for f, ref, src in recs:
        hn, _, tid = ref.partition(":"); p = hs.get(hn) or {}
        t = ((p.get("pueue") or {}).get("tasks") or {}).get(tid)
        if p.get("ok") and (t is None or task_rc(t) is not None):
            if not DRY: f.unlink(missing_ok=True)   # ended or removed: the record goes
            continue
        if src.resolve() == wt or wt in src.resolve().parents:
            st = t["status"] if p.get("ok") else None; st = st if isinstance(st, str) else next(iter(st or {}), "")
            why.append(f"job {ref} ({f.name}) " + (f"is {st.lower()}" if p.get("ok") else f"on unreachable {hn}: assumed running"))
    for u in mine:
        why += [f"unit {u['name']}'s job {j}" for j in unit_jobs(hs, u["name"])]
    pats = cfg.c.get("busy", {}).get("patterns", BUSY_PATTERNS)
    if pats:
        rx = re.compile("|".join(re.escape(x) for x in pats))
        for l in (ps if ps is not None else sh(["ps", "-axo", "pid=,command="])[1]).splitlines():
            pid, _, c = l.strip().partition(" ")
            if not pid.isdigit() or not rx.search(c) or int(pid) == os.getpid(): continue
            cwd = proc_cwd(int(pid))
            if any(n in c for n in names) or (cwd and (cwd == wt or wt in cwd.parents)):
                why.append(f"process {pid} ({c.strip()[:80]})")
    return why

def proc_cwd(pid):
    """A local process's working directory, or None."""
    try: return Path(os.readlink(f"/proc/{pid}/cwd")).resolve()
    except OSError: pass
    rc, o, e = sh(["lsof", "-a", "-d", "cwd", "-p", str(pid), "-Fn"], timeout=10)
    n = next((l[1:] for l in o.splitlines() if l.startswith("n")), None)
    return Path(n).resolve() if rc == 0 and n else None

def cmd_busy(cfg, a):
    """orch busy <wt>: exit 0 (and say why) while a job or a mutation run uses the tree, 1 when it is free (row 53)."""
    cfg.ro = True   # read-only on every host (the probe leaves the overload tracker alone)
    why = busy_reasons(cfg, a.wt)
    for w in why: say(f"busy: {w}")
    if not why: say(f"free: no orch job, unit job or [busy] process uses {Path(a.wt).resolve()}")
    return 0 if why else 1

def cmd_cancel(cfg, a):
    """Cancel an orch job (<host>:<task>) that outlived its intent (issue 36): see cancel_job."""
    for l in cancel_job(cfg, a.job, force=a.force): say(l)

WRAP_RX = re.compile(r"\bORCH_WRAP=([\w.-]+)")

def wrap_token(t):
    """The token under which a task records the jobs it queues: its job id (job scripts), or ORCH_WRAP=<token> (gates)."""
    m = WRAP_RX.search((t or {}).get("command", "")); return m.group(1) if m else job_of(t)

def wrapped_jobs(cfg, tok):
    try: return [l.split()[0] for l in (cfg.f("runs") / "wrap" / tok).read_text().splitlines() if l.strip()]
    except OSError: return []

def stop_job_cmd(h, jid):
    """Shell that stops what a job left behind, by name: its podman container (runner podman) or its systemd scope (Linux)."""
    if not jid or h.get("local"): return ""
    if h.get("runner") == "podman": return f"podman stop -t 5 orch-run-{jid} >/dev/null 2>&1; "
    return f"systemctl --user stop orch-{jid}.scope >/dev/null 2>&1; "

def cancel_job(cfg, ref, force=False, depth=0):
    """Cancel job <host>:<task>: its files are saved here first (runs/<jid>.*; refused when that fails, unless force: nothing is
    removed before it is collected), then pueue kill and remove, then its container or scope is stopped by name, and every job
    it queued itself (a wrapper: a gate or a job whose script ran orch run; row 49) is cancelled the same way."""
    hn, _, tid = ref.partition(":")
    if hn not in cfg.hosts or not tid.isdigit(): raise Err("expected <host>:<task id>")
    h = cfg.hosts[hn]; t = task_status(h, tid)
    if t is None: raise Err(f"no task {tid} on {hn}")
    if t.get("group") not in LANES and not str(t.get("label", "")).startswith(("unit:", "run:", "gate:")): raise Err(f"{hn}:{tid} is not an orch lane job ({t.get('label')}); stop units with orch stop")
    jid = job_of(t); tok = wrap_token(t); inner = wrapped_jobs(cfg, tok) if tok else []; out = []
    if DRY:
        out.append(f"+ save {hn}:{tid}'s files; {stop_job_cmd(h, jid)}{pueue(h)} kill {tid}; remove" + (f"; then follow its jobs {', '.join(inner)}" if inner else ""))
    else:
        if jid and not h.get("local"):
            loc = cfg.f("runs"); loc.mkdir(exist_ok=True)
            r = sh(["rsync", "-a", "-e", " ".join(SSH), f"{h['ssh']}:{runs_dir(cfg, h)}/{jid}.*", f"{loc}/"], timeout=300)
            if r[0] and not force: raise Err(f"refused: {hn}:{tid}'s files could not be saved here ({r[2].strip()[-80:]}); --force cancels anyway")
        elif not jid: save_task_log(cfg, h, {"name": f"_cancelled/{hn}-{tid}"}, tid)
        hrun(h, f"{pueue(h)} kill {tid} 2>/dev/null; {stop_job_cmd(h, jid)}sleep 2; {pueue(h)} remove {tid} 2>/dev/null; true", timeout=60)
        out.append(f"cancelled {hn}:{tid} ({t.get('label')}); its files are in {cfg.f('runs') if jid and not h.get('local') else runs_dir(cfg, h) if jid else cfg.p('out', 'out') / '_cancelled'}")
    for r in inner:
        if depth > 3: break
        try:
            st = task_rc(task_status(cfg.hosts[r.split(':')[0]], r.split(':')[1])) if r.split(":")[0] in cfg.hosts else 0
            if st is None: out += cancel_job(cfg, r, force, depth + 1)
        except Err as e: out.append(f"{r}: {e}")
    return out

def agent_ended(u):
    """The unit's agent is gone: an API run ended, a tmux session or herdr agent is gone (an idle herdr agent is alive)."""
    return u.get("state") == "gone" if u.get("via") == "herdr" else u.get("state") in ENDED

def orphan_jobs(cfg, hs, units):
    """Jobs whose owner is gone (item 3): [(ref, why)]. A lane job of a closed unit, or of an open unit whose agent ended and is
    not parked; a job a wrapper queued (row 49) whose wrapper is no longer queued or running here."""
    names = {u["name"]: u for u in units}; out = []
    for hn, p in hs.items():
        for tid, t in ((p.get("pueue") or {}).get("tasks") or {}).items():
            lab = t.get("label") or ""
            if task_rc(t) is not None or not lab.startswith("unit:"): continue
            u = names.get(lab[5:])
            if not u: out.append((f"{hn}:{tid}", f"its unit {lab[5:]} is closed"))
            elif agent_ended(u) and not u.get("_park") and not u.get("parked"): out.append((f"{hn}:{tid}", f"its unit {u['name']}'s agent ended ({u['state']}) and is not parked"))
    live = {wrap_token(t) for p in hs.values() for t in ((p.get("pueue") or {}).get("tasks") or {}).values() if task_rc(t) is None}
    try: recs = list((cfg.f("runs") / "wrap").iterdir())
    except OSError: recs = []
    for f in recs:
        if f.name in live: continue
        for r in wrapped_jobs(cfg, f.name):
            st = job_state(hs, r)[0]
            if st in ("queued", "admission", "running") and r not in {x for x, _ in out}: out.append((r, f"its wrapper {f.name} has ended"))
            # records of wrappers that ended long ago and whose jobs are done are cleared by the watcher
    return out

def job_of(t):
    m = re.search(r"/runs/([^/ ]+)\.sh", (t or {}).get("command", ""))
    return m.group(1) if m else None

def collect_job(cfg, ref):
    hn, _, tid = ref.partition(":")
    if hn not in cfg.hosts or not tid.isdigit(): raise Err("expected <host>:<task id>")
    h = cfg.hosts[hn]; t = task_status(h, tid)
    if t is None: raise Err(f"no task {tid} on {hn} (unreachable, or cleaned)")
    jid = job_of(t); rc = task_rc(t)
    if rc is None: say(f"{hn}:{tid} is {next(iter(t['status'])) if isinstance(t['status'], dict) else t['status']}, not finished"); return 3
    local = cfg.f("runs"); local.mkdir(exist_ok=True)
    if jid and not h.get("local"):
        r = sh(["rsync", "-a", "-e", " ".join(SSH), f"{h['ssh']}:{runs_dir(cfg, h)}/{jid}.*", f"{local}/"], timeout=300)
        if r[0]: raise Err(f"copy from {hn} failed: {r[2].strip()[-120:]}")
    if jid and (local / f"{jid}.log").exists(): sys.stdout.write((local / f"{jid}.log").read_text())
    try: rc = int((local / f"{jid}.rc").read_text().strip())
    except Exception: pass
    say(f"orch: {hn}:{tid} ({t.get('label')}) exit {rc}; files in {local}/{jid}.*")
    return rc

GATE_LINE = re.compile(r"^\S+ \S+ (\S+) .*RESULT: (\S+)")

GATE_DEFAULT = ('cd "$ORCH_ROOT" && bash "$1"; rc=$?; r=PASS; [ $rc -eq 0 ] || r=FAIL; '
                'printf "%s %s EXIT_tests=%s RESULT: %s\\n" "$(date "+%Y-%m-%d %H:%M:%S")" "$2" $rc $r >> "$3"; exit $rc')

def cmd_gate(cfg, a):
    """Run out/<name>/tests.sh as a gates-lane task on this machine. paths.gate_runner (a project script called with <name>)
    runs it when set; otherwise orch runs tests.sh itself and appends '<date> <time> <name> EXIT_tests=<rc> RESULT: PASS|FAIL'
    to paths.gate_log, the line orch check reads. --host passes the test host in paths.gate_host_env (default ORCH_TEST_HOST).
    --unit (default $ORCH_UNIT) records the gate on that unit, for the landing check."""
    out = cfg.p("out", "out"); t = out / a.name / "tests.sh"
    if not t.is_file(): raise Err(f"{t} not found")
    h = cfg.hosts[next(n for n, x in cfg.hosts.items() if x.get("local"))]
    env = {"ORCH_LANE": "gates", "ORCH_ROOT": str(cfg.root)} | ({cfg.paths.get("gate_host_env", "ORCH_TEST_HOST"): a.host} if a.host else {})
    pre = " ".join(f"{k}={shlex.quote(v)}" for k, v in env.items())
    rh = cfg.paths.get("gate_runner") or cfg.paths.get("run_handoff")
    run = (shlex.quote(str(cfg.root / rh)) + " " + shlex.quote(a.name)) if rh else \
          shlex.join(["sh", "-c", GATE_DEFAULT, "gate", str(t), a.name, str(cfg.p("gate_log", "out/gates.log"))])
    unit = a.unit or os.environ.get("ORCH_UNIT")
    if unit:   # a gate refuses its unit's tree mid-merge, with conflict markers, or too far behind the landing branch (item 41)
        try:
            bd0, u0 = get_unit(cfg, unit)
            why = tree_guard(cfg, u0["cwd"]) if own_tree(cfg, u0, bd0.units()) else None
            if why and not a.allow_unmerged: raise Err(f"refused: {unit}'s tree {u0['cwd']} {why} (--allow-unmerged to gate anyway)")
        except Err as e:
            if str(e).startswith("refused"): raise
    if unit and not DRY:
        try:
            bd, u = get_unit(cfg, unit)
            if a.name not in u.get("gates", []): u["gates"] = [*u.get("gates", []), a.name]; bd.save(u)
        except Err as e: say(f"note: gate not recorded on {unit}: {e}")
    X(h, ensure_lanes(h, cfg))
    tok = f"gate-{re.sub(r'[^A-Za-z0-9_-]', '_', a.name)[:40]}-{time.strftime('%m%d-%H%M%S')}-{os.getpid()}"   # cancel follows the jobs it queues
    rc, o, e = X(h, f"env {pre} {pueue(h)} add -g gates -l {shlex.quote('gate:' + a.name)} -w {shlex.quote(str(cfg.root))} --print-task-id -o {int(a.priority)} -- {pq(f'env ORCH_WRAP={tok} {run}')}")
    if rc: raise Err("pueue add failed: " + (e or o).strip()[:100])
    if DRY: return
    tid = o.strip(); say(f"queued gate {a.name} as {next(n for n, x in cfg.hosts.items() if x.get('local'))}:{tid}")
    if not a.wait: return
    subprocess.run(["sh", "-c", f"{pueue(h)} wait -q {tid}"])
    lines = [l for l in cfg.p("gate_log").read_text().splitlines() if (m := GATE_LINE.match(l)) and m.group(1) == a.name]
    say(lines[-1] if lines else f"no RESULT line for {a.name}")
    return 0 if lines and lines[-1].endswith("RESULT: PASS") else 1

def lane_findings(cfg, hs, units=()):
    """Per host and lane: queued work with free slots (stalled), queued work while the host has room (idle), a host with free
    slots while another waits, and jobs over their class age limit."""
    F, free, backlog = [], {}, {}
    for n, p in hs.items():
        t = p.get("pueue")
        if not p["ok"] or not t: continue
        h = cfg.hosts[n]; groups = t.get("groups") or {}; tasks = list((t.get("tasks") or {}).values())
        for lane in LANES:
            g = groups.get(lane)
            if not g: continue
            mine = [x for x in tasks if x.get("group") == lane]
            st = lambda x: x["status"] if isinstance(x["status"], str) else next(iter(x["status"]))
            q = [x for x in mine if st(x) == "Queued"]; r = [x for x in mine if st(x) == "Running"]; par = g.get("parallel_tasks", 1)
            wt = int(p.get(f"wait_{lane}", 0) or 0)   # running tasks still waiting in orch's own admission
            if q and (g.get("status") != "Running" or len(r) < par):
                F.append((f"stalled:{n}:{lane}", f"{n} {lane} STALLED: {len(q)} queued, {len(r)} of {par} slots running, group {g.get('status')}"))
            elif q and not wt and lane != "land" and len(r) < (h.get("gate_slots", slots(h, cfg)) if lane == "gates" else slots(h, cfg)) and \
                    (p["cap_admit"].strip() == "yes" if "cap_admit" in p else host_cap(cfg, n, p, list(units))["free"] > 0):
                # idle by the admission's own verdict (row 48): work queued in pueue, none held by admission, and admission would
                # take one more now; jobs waiting inside their scripts are held by admission, never idle
                F.append((f"idle:{n}:{lane}", f"{n} {lane} IDLE: {len(q)} queued in pueue, {len(r)} running, and admission would admit one now"))
            if q: backlog.setdefault(lane, []).append(n)
            elif len(r) < par and not wt and p.get("cap_admit", "yes").strip() == "yes": free.setdefault(lane, []).append(n)   # free by admission (row 48)
            for x in mine:
                s = x["status"]; info = s.get(st(x), {}) if isinstance(s, dict) else {}
                try: since = time.mktime(time.strptime(info.get("enqueued_at", "")[:19], "%Y-%m-%dT%H:%M:%S"))
                except ValueError: continue
                if st(x) in ("Queued", "Running") and now() - since > lane_age(cfg, lane) * 60:
                    F.append((f"age:{n}:{x['id']}", f"{n}:{x['id']} {lane} {x.get('label')} {st(x).lower()} {int((now() - since) / 60)} min, over the {lane_age(cfg, lane)} min limit"))
        if int(p.get("old_rule", 0) or 0):
            F.append((f"old-rule:{n}", f"{n}: {p['old_rule']} job(s) still wait under the old cap rule ({p.get('old_rule_jobs', '').strip()[:120]}): "
                                        "re-queue them with orch run, then stop the old tasks"))
        lg, lr = int(p.get("legacy_wait", 0) or 0), int(p.get("legacy_run", 0) or 0)
        if lg and lr < h.get("legacy_slots", 3):
            F.append((f"stalled:{n}:legacy", f"{n} old-script queue STALLED: {lg} waiting, {lr} of {h.get('legacy_slots', 3)} running (its own admission holds them)"))
    for lane, ns in backlog.items():
        for f in free.get(lane, []):
            if cfg.hosts[f].get("local") == cfg.hosts[ns[0]].get("local") and not (lane == "land"):
                F.append((f"idle:{f}:{lane}:vs", f"{f} has free {lane} slots while {', '.join(ns)} has a backlog"))
    return F

# ---------------------------------------------------------------- land: merge main, gate the merged tree, squash-land (register item 41)
MERGE_BRIEF = """# Brief: {m}: merge {br} into {unit}'s branch

TIER: {tier}
ITEM: {item}

`orch land {unit}` stopped: merging the current `{br}` into the branch `{branch}` of `{wt}` conflicts in:
{files}

In `{wt}`: run `git merge {br}`, resolve every conflict keeping both sides' intent (read each side's commits), build and test
through the lanes, commit the merge. Do not land: when it is committed, the orchestrator runs `orch land {unit}` again, which
gates the merged tree and squash-lands it. Write REPORT.md with what each conflict was and how it was resolved.
"""

def git(wt, *a, timeout=120): return sh(["git", "-C", str(wt), *a], timeout=timeout)

def cmd_land(cfg, a):
    """orch land <unit>: in the unit's worktree, merge the current landing branch ([landing] branch, default main); on a conflict
    stop (the tree is left as it was) and dispatch a merge unit merge-<unit> (--no-dispatch: only say so); gate the merged tree
    on [landing] final_gate_host with [landing] final_gate (a command run through orch run, gates lane); then squash-land: one
    commit whose tree is the gated tree and whose parent is the landing branch tip that was merged. When the landing branch is
    checked out (the main checkout), it is moved there with git merge --ff-only, so that checkout's files follow; a landing
    branch that moved meanwhile, or a dirty main checkout, stops it. --dry-run checks the merge with git merge-tree and prints
    each step, changing nothing."""
    ld = cfg.c.get("landing", {}); br = ld.get("branch") or "main"
    u = next((x for x in Beads(cfg).units() if x["name"] == a.unit), None) or all_units(cfg).get(a.unit)
    if not u: raise Err(f"no unit {a.unit}")
    wt = Path(u.get("cwd", "/"))
    if not own_tree(cfg, u, [x for x in Beads(cfg).units()]) or not wt.is_dir(): raise Err(f"{a.unit} has no worktree of its own ({wt}): nothing to land")
    rc, branch, e = git(wt, "symbolic-ref", "--short", "HEAD"); branch = branch.strip()
    if rc: raise Err(f"{wt} is not on a branch")
    if branch == br: raise Err(f"{wt} is on {br} itself")
    if git(wt, "status", "--porcelain", "--untracked-files=no")[1].strip(): raise Err(f"{wt} has uncommitted changes: commit them first")
    if git(wt, "rev-parse", "-q", "--verify", "MERGE_HEAD")[0] == 0: raise Err(f"{wt} has a merge in progress (MERGE_HEAD): finish or abort it")
    base = git(wt, "rev-parse", br)[1].strip()
    if not base: raise Err(f"no branch {br}")
    ahead = int(git(wt, "rev-list", "--count", f"{br}..HEAD")[1].strip() or 0); behind = int(git(wt, "rev-list", "--count", f"HEAD..{br}")[1].strip() or 0)
    if not ahead: raise Err(f"{branch} has no commits over {br}: nothing to land")
    if landed(cfg, u): raise Err(f"{a.unit} is already landed: {br} holds its tree ({branch} has no change since): orch close {a.unit}")
    say(f"land {a.unit}: {branch} in {wt}, {ahead} commit(s) ahead of {br} ({base[:9]}), {behind} behind")
    # 1. merge the current landing branch (dry run: merge-tree only)
    rc, o, e = git(wt, "merge-tree", "--write-tree", "--name-only", "HEAD", br)
    if rc not in (0, 1) and not DRY:   # git before 2.38 has no merge-tree --write-tree: a trial merge, always aborted (tree clean)
        rc2, o2, e2 = git(wt, "merge", "--no-commit", "--no-ff", br, timeout=600)
        cf_ = git(wt, "diff", "--name-only", "--diff-filter=U")[1]; git(wt, "merge", "--abort")
        if rc2 and not cf_.strip(): raise Err(f"git merge-tree and a trial merge failed: {(e or o).strip()[:80]}; {(e2 or o2).strip()[:80]}")
        rc, o = (1, "-\n" + cf_) if cf_.strip() else (0, "")
    elif rc not in (0, 1): raise Err(f"git merge-tree failed: {(e or o).strip()[:120]}")
    if rc == 1:
        files = [l for l in o.split("\n\n")[0].splitlines()[1:] if l.strip()][:20] or ["(see git merge)"]   # tree id, then the conflicted paths
        say(f"STOP: merging {br} conflicts in {len(files)} file(s): {', '.join(files[:6])}")
        m = f"merge-{a.unit}"[:32]
        if a.no_dispatch or DRY: say(f"{'would dispatch' if DRY else 'dispatch with'}: orch launch {m} --kind implement --cwd {wt} (brief {cfg.p('briefs', 'briefs') / (m + '.md')})"); return 3
        bp = cfg.p("briefs", "briefs") / f"{m}.md"
        if not bp.exists(): atomic_write(bp, MERGE_BRIEF.format(m=m, br=br, unit=a.unit, branch=branch, wt=wt, tier=(u.get("tier") or "normal").upper(),
                                                              item=u.get("item") or a.unit, files="\n".join(f"- `{f}`" for f in files)))
        cmd_launch(cfg, argparse.Namespace(unit=m, kind="implement", tier=u.get("tier") or "normal", host=None, model=None, brief=str(bp), cwd=str(wt),
                                           budget=None, test_host=u.get("build"), allow_main=False, of=None, report=None, resume_of=None, item=u.get("item"),
                                           dry_run=False, share_with=a.unit))
        return 3
    if behind:
        if DRY: say(f"+ git -C {wt} merge --no-edit {br}  (merge-tree: clean)")
        else:
            rc, o, e = git(wt, "merge", "--no-edit", br, timeout=600)
            if rc: git(wt, "merge", "--abort"); raise Err(f"git merge {br} failed although merge-tree was clean: {(e or o).strip()[-160:]}; aborted")
            say(f"merged {br} into {branch}")
    # 2. gate the merged tree on the final-gate host
    gh, gc = ld.get("final_gate_host"), ld.get("final_gate")
    if a.no_gate: say("gate skipped (--no-gate)")
    elif not gh or not gc: raise Err("set [landing] final_gate_host and final_gate (the command that gates a merged tree) in orch.toml, or --no-gate")
    else:
        ra = argparse.Namespace(host=gh, lane="gates", unit=a.unit, wt=str(wt), subdir=None, usb=False, priority=10, no_wait=False, allow_unmerged=False, command=[gc])
        if DRY: say(f"+ orch run --host {gh} --lane gates --unit {a.unit} --wt {wt} -- {gc}"); 
        else:
            grc = cmd_run(cfg, ra)
            if grc: raise Err(f"final gate on {gh} failed (exit {grc}): not landed; the merge stays committed in {wt}")
            say(f"final gate on {gh}: PASS")
    # 3. squash-land: tree of the gated HEAD, parent = the landing tip that was merged
    if DRY: say(f"+ git commit-tree HEAD^{{tree}} -p {base[:9]}; move {br} (ff-only in its checkout); {ahead} commit(s) squashed"); return 0
    if git(wt, "rev-parse", br)[1].strip() != base: raise Err(f"{br} moved while {a.unit} was gated: run orch land {a.unit} again (it merges the new tip)")
    tree = git(wt, "rev-parse", "HEAD^{tree}")[1].strip()
    subj = git(wt, "log", "--format=%s", f"{base}..HEAD", "--no-merges")[1].splitlines()
    msg = f"{a.unit}: land {branch} ({len(subj)} commit(s), squashed)\n\n" + "\n".join(f"- {s}" for s in subj[:40]) + "\n"
    rc, new, e = sh(["git", "-C", str(wt), "commit-tree", tree, "-p", base, "-F", "-"], inp=msg)
    if rc: raise Err(f"git commit-tree failed: {e.strip()[:120]}")
    new = new.strip(); wl = git(wt, "worktree", "list", "--porcelain")[1]
    co = next((blk.split("\n")[0][9:] for blk in wl.split("\n\n") if f"branch refs/heads/{br}" in blk), None)
    if co:
        rc, o, e = git(co, "merge", "--ff-only", new, timeout=300)
        if rc: raise Err(f"{co} (where {br} is checked out) did not take the landing commit {new[:9]} fast-forward: {(e or o).strip()[-160:]}")
    else:
        rc, o, e = git(wt, "update-ref", f"refs/heads/{br}", new, base)
        if rc: raise Err(f"update-ref {br} failed: {e.strip()[:120]}")
    say(f"landed {a.unit}: {br} {base[:9]} -> {new[:9]} ({len(subj)} commit(s) squashed); push and close are separate (orch close {a.unit})")
    if u.get("id"): Beads(cfg).comment(u["id"], f"{ts()} landed on {br} as {new[:9]}")
    cfg.touch("changed")
    return 0

SECRETS = [re.compile(x.encode()) for x in ("sk" + "-ant-[A-Za-z0-9_-]{20,}", "sk" + "-or-[A-Za-z0-9_-]{20,}", "sk" + "-proj-[A-Za-z0-9_-]{20,}",
    "\\bsk" + "-[a-f0-9]{32,}\\b", "AK" + "IA[0-9A-Z]{16}", "gh" + "p_[A-Za-z0-9_-]{20,}", "xo" + "x[A-Za-z0-9_-]{10,}",
    # a real PEM block only: the dashed BEGIN line, then a base64 line (a mention of the words in prose is not a key)
    "-----" + "BEGIN( [A-Z0-9]+)* PRIV" + "ATE KEY-----\\r?\\n[A-Za-z0-9+/=]{16,}\\r?$")]
SECRETS[-1] = re.compile(SECRETS[-1].pattern, re.M)

def cmd_commit_state(cfg, a):
    """Stage everything, scan exactly what is staged (L9), commit and push; unstage again if a secret is found."""
    if DRY: say("+ orch index; git add -A; scan staged files; git commit; git push"); return
    write_index(cfg)   # out/INDEX.md is committed with the state (orch-swarm item 3)
    rc, o, e = sh(["git", "add", "-A"], cwd=cfg.root, timeout=120)
    if rc: raise Err("git add failed: " + e.strip()[:80])
    rc, o, e = sh(["git", "diff", "--cached", "--name-only", "-z"], cwd=cfg.root)
    paths = [x for x in o.split("\0") if x]
    hit = []
    for x in paths:
        try: b = (cfg.root / x).read_bytes()
        except OSError: continue
        if any(r.search(b) for r in SECRETS): hit.append(x)
    if hit: sh(["git", "reset", "-q"], cwd=cfg.root); raise Err("refused (unstaged again), possible secrets in: " + ", ".join(hit))
    if not paths: say("nothing to commit"); return
    for cmd in (["git", "commit", "-m", a.message], push_cmd(cfg.root, cfg)):
        rc, o, e = sh(cmd, cwd=cfg.root, timeout=120)
        if rc: raise Err(f"{shlex.join(cmd[:2])} failed: {(e or o).strip()[-200:]}")
    say(f"committed {len(paths)} path(s) and pushed")

def push_cmd(repo, cfg=None):
    """git push; on a branch without an upstream, push --set-upstream to [git] remote (default origin, else the only remote),
    so the next check can count unpushed commits (orch-fixes7)."""
    if sh(["git", "-C", str(repo), "rev-parse", "--abbrev-ref", "@{u}"])[0] == 0: return ["git", "push"]
    rem = ((cfg.c.get("git", {}) if cfg else {}).get("remote")) or ""
    if not rem:
        rs = sh(["git", "-C", str(repo), "remote"])[1].split()
        rem = "origin" if "origin" in rs or not rs else rs[0]
    return ["git", "push", "--set-upstream", rem, "HEAD"]

# ---------------------------------------------------------------- transcripts (orch-swarm item 5)
# One condenser for Claude Code (jsonl under ~/.claude/projects) and Codex (rollout jsonl under ~/.codex/sessions) transcripts.
# It runs where the transcript is: here, or on the agent's host as `python3 -` with this source on stdin (standard library only).
CONDENSE = r'''
import glob, json, os, re, sys
mode, grep, tail, since, cwd = sys.argv[1:6]; tail = int(tail); since = float(since); pats = sys.argv[6:]
rx = re.compile(grep, re.I) if grep else None
def flat(x):
    if isinstance(x, list): return " ".join(flat(y) for y in x)
    if isinstance(x, dict): return str(x.get("text") or x.get("content") or x.get("output") or json.dumps(x))
    return str(x or "")
def show(tag, full, n):
    full = re.sub(r"\s+", " ", full).strip()
    m = rx.search(full) if rx else None
    if m and len(full) > n: a = max(0, m.start() - n // 3); return f"{tag}{'...' if a else ''}{full[a:a + n]}{'...' if a + n < len(full) else ''}"
    return tag + (full if len(full) <= n else full[:n] + "...")
def tool(name, inp):
    if isinstance(inp, str):
        try: inp = json.loads(inp)
        except Exception: pass
    k = next((k for k in ("command", "cmd", "file_path", "path", "pattern", "url", "query", "description") if isinstance(inp, dict) and inp.get(k)), None)
    return f"> {name}: ", flat(inp[k]) if k else (inp if isinstance(inp, str) else json.dumps(inp)), 160
def items(f):
    for l in open(f, errors="replace"):
        try: o = json.loads(l)
        except Exception: continue
        t = o.get("type")
        if t in ("user", "assistant") and isinstance(o.get("message"), dict):      # Claude Code
            c = o["message"].get("content"); who = "USER: " if t == "user" else "AGENT: "
            if isinstance(c, str): yield who, c, 600; continue
            for b in c or []:
                if not isinstance(b, dict): continue
                if b.get("type") == "text" and b.get("text", "").strip(): yield who, b["text"], 600
                elif b.get("type") == "tool_use": yield tool(b.get("name"), b.get("input"))
                elif b.get("type") == "tool_result": yield ("< ERROR " if b.get("is_error") else "< "), flat(b.get("content")), 200
        elif t == "response_item":                                                  # Codex
            p = o.get("payload") or {}; pt = p.get("type")
            if pt == "message" and p.get("role") in ("user", "assistant"):
                tx = flat(p.get("content"))
                if tx.strip() and not tx.lstrip().startswith(("<", "# AGENTS.md")): yield ("USER: " if p["role"] == "user" else "AGENT: "), tx, 600
            elif pt in ("function_call", "custom_tool_call", "local_shell_call"): yield tool(p.get("name") or pt, p.get("arguments") or p.get("input") or p.get("action"))
            elif pt in ("function_call_output", "custom_tool_call_output"): yield "< ", flat(p.get("output")), 200
fs = []
for p in pats: fs += glob.glob(os.path.expanduser(p), recursive=True)
fs = sorted(set(fs), key=os.path.getmtime)
if mode == "newest": fs = fs[-1:]
if mode == "codex-cwd":   # Codex sessions of a cwd (no thread id known): their session_meta line names it
    def meta_cwd(f):
        try: return (json.loads(open(f, errors="replace").readline()).get("payload") or {}).get("cwd")
        except Exception: return None
    fs = [f for f in fs if os.path.getmtime(f) >= since and meta_cwd(f) == cwd]
if not fs: print("(no transcript found)"); sys.exit(3)
out = []
for f in fs:
    body = [show(tag, full, n) for tag, full, n in items(f) if not rx or rx.search(full)]
    out.append((f, body))
if tail > 0:   # the last N lines over all sessions, newest session last
    keep, left = [], tail
    for f, body in reversed(out):
        if left <= 0: break
        keep.insert(0, (f, body[-left:])); left -= len(body[-left:])
    out = keep
print("\n".join(f"## {f}\n" + "\n".join(b) for f, b in out))
'''

def unit_any(cfg, name):
    """An open unit, else the latest record of a closed one."""
    try: u = next((u for u in Beads(cfg).units() if u["name"] == name), None)
    except Err: u = None
    return u or all_units(cfg).get(name)

def unit_sessions(cfg, u):
    """The agent session ids of a unit's runs (api.json and each run's api-<run>.json: Claude session_id, Codex thread_id)."""
    od = cfg.p("out", "out") / u["name"]; sids = []
    for f in sorted(od.glob("api*.json"), key=lambda p: p.stat().st_mtime):
        try: d = json.loads(f.read_text())
        except Exception: continue
        sid = d.get("session_id") or d.get("thread_id")
        if sid and re.fullmatch(r"[A-Za-z0-9-]{8,64}", sid): sids.append(sid)
    return list(dict.fromkeys(sids))

def read_transcript(cfg, u, grep="", tail=40):
    """(rc, condensed text) of the unit's transcript(s), read on the host that holds them."""
    h = cfg.hosts.get(u.get("host"), {"local": True}); kind = cfg.models.get(u.get("model"), {}).get("kind")
    sids = unit_sessions(cfg, u); cwd = u.get("rcwd") or u.get("cwd") or ""
    esc = re.sub(r"[^A-Za-z0-9-]", "-", cwd)
    if kind == "opencode": return 3, "(opencode keeps its sessions in its own database: not readable by orch; read the agent's report)"
    codex = kind == "codex" or (kind == "api" and "codex" in json.dumps(cfg.prov.get(cfg.models.get(u.get("model"), {}).get("provider"), {}).get("cmd", "")))
    if codex:
        mode, pats = ("ids", [f"~/.codex/sessions/**/*{s}*.jsonl" for s in sids]) if sids else ("codex-cwd", ["~/.codex/sessions/**/rollout-*.jsonl"])
    elif sids: mode, pats = "ids", [f"~/.claude/projects/*/{s}.jsonl" for s in sids]
    elif h.get("local"):
        f = transcript_of(cfg, u); mode, pats = "ids", [str(f)] if f else []
        if not f: return 3, "(no transcript found)"
    else: mode, pats = "newest", [f"~/.claude/projects/{esc}/*.jsonl"]   # a remote Claude agent with no session id yet: its newest there
    argv = [mode, grep, str(tail), str(u.get("started", 0) - 60), cwd, *pats]
    if h.get("local"): rc, o, e = sh([sys.executable, "-", *argv], inp=CONDENSE, timeout=120)
    else: rc, o, e = hrun(h, f"{h.get('agent_env', '')}\npython3 - {shlex.join(argv)}", inp=CONDENSE, timeout=120)
    return rc, (o or e).rstrip()

def cmd_transcript(cfg, a):
    u = unit_any(cfg, a.unit)
    saved = cfg.p("out", "out") / a.unit / "transcript.md"
    if not u and not saved.is_file(): raise Err(f"no unit {a.unit}")
    rc, txt = read_transcript(cfg, u, a.grep or "", a.tail) if u else (3, "")
    if rc and saved.is_file():   # the remote copy is gone: the condensed copy orch collect saved
        L = saved.read_text().splitlines()
        if a.grep: L = [l for l in L if re.search(a.grep, l, re.I)]
        txt = f"(saved copy {saved})\n" + "\n".join(L[-a.tail:] if a.tail > 0 else L); rc = 0
    say(txt); return 0 if rc == 0 else 1

def save_transcript(cfg, u):
    """out/<unit>/transcript.md: the whole condensed transcript (collect; it outlives the remote copy)."""
    rc, txt = read_transcript(cfg, u, "", 0)
    if rc == 0 and txt and not DRY: atomic_write(cfg.p("out", "out") / u["name"] / "transcript.md", txt + "\n")
    return rc == 0

# ---------------------------------------------------------------- peers (orch-swarm item 4)
def card_fields(cfg, name):
    """The board card's fields ({state, step, ...}) of an agent, {} without a card."""
    try: return dict(m.groups() for m in re.finditer(r"^- (\w+): ?(.*)$", (board_dir(cfg) / "agents" / f"{name}.md").read_text(), re.M))
    except OSError: return {}

def unit_changes(cfg, u, units=()):
    """(branch, [files changed so far]) of a unit's tree: locally its commits since it left the landing branch plus uncommitted
    and untracked files; on a remote host the files that differ from the tree it was sent (base/<unit>). A shared tree (the
    project root, another open unit's cwd) has none of its own."""
    h = cfg.hosts.get(u.get("host"), {})
    if not h.get("local"):
        if u.get("via") in ("failed", "starting") or "root" not in h: return "?", []
        n = u["name"]
        rc, o, e = hrun(h, f"cd {qp(h['root'])} && [ -d base/{n} ] && diff -rq {DIFF_X} base/{n} worktrees/{n} 2>/dev/null; true", timeout=60)
        fs = []
        for l in o.splitlines():
            m = re.match(rf"Files base/{re.escape(n)}/(.+) and worktrees/{re.escape(n)}/.+ differ$", l) or re.match(rf"Only in (?:base|worktrees)/{re.escape(n)}/?(.*): (.+)$", l)
            if m: fs.append(m.group(1) if m.lastindex == 1 else str(Path(m.group(1)) / m.group(2)) if m.group(1) else m.group(2))
        rc, b, _ = hrun(h, f"git -C {qp(h['root'] + '/base/' + n)} rev-parse --abbrev-ref HEAD 2>/dev/null")
        return (b.strip() or "?"), sorted(set(fs))
    cwd = u.get("cwd")
    if not cwd or not Path(cwd).is_dir() or not own_tree(cfg, u, units or [u]): return "?", []
    br = sh(["git", "-C", cwd, "rev-parse", "--abbrev-ref", "HEAD"])[1].strip() or "?"
    lb = cfg.c.get("landing", {}).get("branch") or "main"
    mb = sh(["git", "-C", cwd, "merge-base", "HEAD", lb])[1].strip()
    fs = set(sh(["git", "-C", cwd, "diff", "--relative", "--name-only", mb, "--", "."])[1].split("\n")) if mb else set()
    top = sh(["git", "-C", cwd, "rev-parse", "--show-toplevel"])[1].strip()
    fs |= {str(Path(top, l[3:].split(" -> ")[-1].strip('"')).relative_to(Path(cwd).resolve())) for l in
           sh(["git", "-C", cwd, "status", "--porcelain", "-uall", "--", "."])[1].splitlines() if len(l) > 3 and top}
    skip = [cfg.state.resolve(), board_dir(cfg).resolve()]   # orch's own files and the board are nobody's change (as in close)
    return br, sorted(f for f in fs if f and not any((Path(cwd) / f).resolve().is_relative_to(x) for x in skip))

def transcript_where(cfg, u):
    """Where the unit's agent transcript is (for peers.md): a local path, or <host>:<path> on the host that ran it."""
    h = cfg.hosts.get(u.get("host"), {}); sid = api_out(cfg, u).get("session_id")
    if h.get("local"):
        f = transcript_of(cfg, u) if not sid else next(iter((Path.home() / ".claude/projects").glob(f"*/{sid}.jsonl")), None)
        return str(f) if f else "-"
    esc = re.sub(r"[^A-Za-z0-9-]", "-", u.get("rcwd") or "")
    return f"{u['host']}:~/.claude/projects/{esc}/" + (f"{sid}.jsonl" if sid else "(newest .jsonl)")

def peer_rows(cfg, units):
    """One row per running unit: name, host, model, branch, files changed, step, jobs it waits on, report, transcript."""
    live = [u for u in units if u.get("state") not in ENDED + ("failed",) or u.get("_park")]
    with cf.ThreadPoolExecutor(8) as ex: ch = list(ex.map(lambda u: unit_changes(cfg, u, units), live))
    rows = []
    for u, (br, fs) in zip(live, ch):
        c = card_fields(cfg, u["name"])
        rows.append({"name": u["name"], "host": u.get("host"), "model": u.get("model"), "branch": br, "files": fs, "state": u.get("state"),
                     "step": c.get("step") or c.get("state") or "-", "jobs": u.get("_park") or unit_jobs(getattr(cfg, "_hs", {}), u["name"]),
                     "report": str(report_path(cfg, u)) if cfg.hosts.get(u.get("host"), {}).get("local") else f"{u['host']}:{cfg.hosts[u['host']].get('root')}/out/{u['name']}/REPORT.md",
                     "transcript": transcript_where(cfg, u)})
    return rows

def peers_text(rows):
    L = [f"# Peers ({ts()}; written by orch check and the watcher; one line per running unit)"]
    for r in rows:
        fs = ", ".join(r["files"][:12]) + (f" (+{len(r['files']) - 12} more)" if len(r["files"]) > 12 else "")
        L.append(f"- {r['name']} | host {r['host']} | {r['model']} | branch {r['branch']} | {r['state']} | step: {r['step'][:80]} | "
                 f"waits on: {', '.join(r['jobs']) or '-'} | files: {fs or '-'} | report {r['report']} | transcript {r['transcript']}")
    if not rows: L.append("- none running")
    return "\n".join(L) + "\n"

def peer_findings(cfg, units):
    """Writes the board folder's peers.md (a writer only: the board sync then carries it to every host) and returns
    overlap:<a>:<b> for two running units that change the same file."""
    rows = peer_rows(cfg, units); F = []
    if not cfg.ro and not DRY and board_dir(cfg).is_dir(): atomic_write(board_dir(cfg) / "peers.md", peers_text(rows))
    for i, a in enumerate(rows):
        for b in rows[i + 1:]:
            both = sorted(set(a["files"]) & set(b["files"]))
            if both: F.append((f"overlap:{a['name']}:{b['name']}", f"{a['name']} and {b['name']} both change {', '.join(both[:4])}"
                               + (f" (+{len(both) - 4})" if len(both) > 4 else "") + ": tell them (board.sh direct), or land one first"))
    return F

def cmd_peers(cfg, a):
    cfg.ro = True; hs = probe_all(cfg); cfg._hs = hs
    try: units = Beads(cfg).units()
    except Err as e: raise Err(f"beads unavailable: {e}")
    for u in units:
        u["state"] = unit_state(u, hs, {}) if u.get("via") != "herdr" else unit_state(u, hs, herdr_agents(cfg))
        if not verdict(cfg, u) and u["state"] in ENDED: u["_park"] = (u.get("parked") or {}).get("jobs") or waiting_line_jobs(cfg, u)
    say(peers_text(peer_rows(cfg, units)).rstrip())

# ---------------------------------------------------------------- reports index (orch-swarm item 3)
RESULT_RX = re.compile(r"^\W*(result|summary|outcome|conclusion)s?\b\W*", re.I)

def report_summary(text):
    """(verdict, one-line result) of a report: its final VERDICT line (else line 1), and a 'Result:'/'Summary:' line, else the
    last content line before the final verdict."""
    L = [l.rstrip() for l in text.splitlines()]
    vi = next((i for i in range(len(L) - 1, -1, -1) if L[i].startswith("VERDICT:")), None)
    v = L[vi][8:].strip() if vi is not None else "none"
    res = next((RESULT_RX.sub("", l) for l in L if RESULT_RX.match(l) and len(RESULT_RX.sub("", l)) > 3), None)
    if not res:
        body = [l for l in L[1:vi if vi and vi > 0 else len(L)] if l.strip() and not l.lstrip().startswith(("#", "VERDICT:", "|---", "```"))]
        res = body[-1] if body else ""
    return (v[:24] or "none"), re.sub(r"\s+", " ", res.strip(" -*"))[:140]

def write_index(cfg):
    """out/INDEX.md, one line per unit (verdict, result, report path), newest first; a copy in the board folder (index.md) so
    the board sync carries it to every host. Returns the number of units."""
    od = cfg.p("out", "out"); rows = []
    for rp in od.glob("*/REPORT.md"):
        try: v, r = report_summary(rp.read_text(errors="replace")); rows.append((rp.stat().st_mtime, rp.parent.name, v, r, rp))
        except OSError: continue
    rows.sort(reverse=True)
    text = (f"# Reports index ({ts()}; orch index, regenerated at orch commit-state)\n"
            + "".join(f"- {n} | {v} | {r or '-'} | {rp}\n" for _, n, v, r, rp in rows))
    if not DRY and not cfg.ro:
        atomic_write(od / "INDEX.md", text)
        if board_dir(cfg).is_dir(): atomic_write(board_dir(cfg) / "index.md", text)
    return len(rows)

def cmd_index(cfg, a):
    n = write_index(cfg); say(f"{cfg.p('out', 'out') / 'INDEX.md'}: {n} unit(s)")

# ---------------------------------------------------------------- session memory (orch-swarm item 1, 7)
# .orch/MEMORY.md is the session's curated memory: Decisions / Facts / Pitfalls, one dated line per entry. Only the orchestrator
# writes it (orch remember / forget); every agent's brief starts with it (brief_header) and the orchestrator's SessionStart hook
# injects it. An entry may carry a subject ([key]): a newer entry on the same subject replaces the older one, never sits beside it.
MEM_SECTIONS = {"decision": "Decisions", "fact": "Facts", "pitfall": "Pitfalls"}
MEMORY_DEFAULTS = {"cap_lines": 30, "review_days": 14, "agent_docs": ["AGENTS.md"]}
MEM_RX = re.compile(r"^- (\d{4}-\d{2}-\d{2}) (?:\[([^\]]+)\] )?(.*?)(?: \(source: (.+)\))?$")

def mset(cfg, k): return cfg.c.get("memory", {}).get(k, MEMORY_DEFAULTS[k])
def memory_path(cfg): return cfg.f("MEMORY.md")

def memory_read(cfg):
    """[(section, date, key or None, text, source or None)] in file order."""
    try: lines = memory_path(cfg).read_text().splitlines()
    except OSError: return []
    sec, out = None, []
    for l in lines:
        if l.startswith("## "): sec = l[3:].strip(); continue
        m = MEM_RX.match(l)
        if m and sec: out.append((sec, m.group(1), m.group(2), m.group(3), m.group(4)))
    return out

def mem_line(e):
    sec, d, k, t, s = e
    return f"- {d} " + (f"[{k}] " if k else "") + t + (f" (source: {s})" if s else "")

def memory_write(cfg, entries):
    L = ["# Session memory", "(curated by the orchestrator with orch remember / orch forget; one dated line per entry)"]
    for sec in MEM_SECTIONS.values():
        L += ["", f"## {sec}"] + [mem_line(e) for e in entries if e[0] == sec]
    atomic_write(memory_path(cfg), "\n".join(L) + "\n")

def memory_text(cfg):
    """MEMORY.md for a brief or the SessionStart context, or "" when it holds no entry."""
    return memory_path(cfg).read_text().strip() if memory_read(cfg) else ""

def memory_history(cfg, e, why):
    with cfg.f("memory-history.md").open("a") as f: f.write(f"{ts()} {why} ({e[0]}): {mem_line(e)[2:]}\n")

def refuse_agent(what):
    if os.environ.get("ORCH_ROLE") == "agent": raise Err(f"refused: {what} is the orchestrator's (an agent proposes with board.sh post <you> learned <text>)")

def cmd_remember(cfg, a):
    refuse_agent("orch remember")
    kind = next(k for k in MEM_SECTIONS if getattr(a, k))
    text = re.sub(r"\s+", " ", a.text).strip()
    if not text: raise Err("nothing to remember")
    if kind == "fact" and not a.source: raise Err("a fact needs --source <path|sha|job> (where it can be checked)")
    es = memory_read(cfg)
    if any(e[3] == text for e in es): raise Err("already remembered (exact duplicate)")
    key = slug(a.key) if a.key else None
    old = [e for e in es if key and e[2] == key]
    new = (MEM_SECTIONS[kind], time.strftime("%Y-%m-%d"), key, text, a.source)
    if DRY: say(f"+ remember {mem_line(new)}" + (f" (replaces {len(old)} on [{key}])" if old else "")); return
    for e in old: memory_history(cfg, e, "replaced")
    memory_write(cfg, [e for e in es if e not in old] + [new])
    if a.learned: learned_mark(cfg, a.learned, "remembered")
    cfg.touch("changed"); say(f"remembered ({MEM_SECTIONS[kind]})" + (f", replacing the older entry on [{key}]" if old else "") + f": {text}")

def cmd_forget(cfg, a):
    refuse_agent("orch forget")
    es = memory_read(cfg); q = a.text.strip()
    hit = [es[int(q) - 1]] if q.isdigit() and 0 < int(q) <= len(es) else [e for e in es if e[3] == q] or [e for e in es if q in e[3] or q == e[2]]
    if len(hit) != 1: raise Err(f"{'no' if not hit else len(hit)} entries match {q!r}" + ("; give its number (orch memory) or more text" if hit else ""))
    if DRY: say(f"+ forget {mem_line(hit[0])}"); return
    memory_history(cfg, hit[0], "forgotten"); memory_write(cfg, [e for e in es if e != hit[0]])
    cfg.touch("changed"); say(f"forgotten (moved to {cfg.f('memory-history.md').name}): {hit[0][3]}")

def cmd_memory(cfg, a):
    es = memory_read(cfg)
    if a.keep:
        refuse_agent("orch memory --keep")
        if not (0 < a.keep <= len(es)): raise Err(f"no entry {a.keep}")
        e = es[a.keep - 1]; es[a.keep - 1] = (e[0], time.strftime("%Y-%m-%d"), *e[2:])
        if not DRY: memory_write(cfg, es)
        say(f"kept (re-dated): {e[3]}"); return
    for i, e in enumerate(es, 1): say(f"{i:3} {e[0][:-1].lower():8} {mem_line(e)[2:]}")
    if not es: say(f"(no entries in {memory_path(cfg)})")

def mem_source_gone(cfg, s):
    """True when a cited source is a path that no longer exists (a sha or a job id is not checked here)."""
    if not s or re.fullmatch(r"[0-9a-f]{7,40}", s) or JOBREF.fullmatch(s) or not ("/" in s or s.endswith((".md", ".py", ".toml", ".log", ".json"))): return False
    p = Path(os.path.expanduser(s.split(":")[0] if re.match(r"^[^/]+:\d+$", s) else s))
    return not (p if p.is_absolute() else cfg.root / p).exists()

RULE_STOP = {"a", "an", "the", "of", "on", "in", "to", "for", "and", "or", "is", "are", "be", "by", "with", "at", "from", "owner",
             "must", "always", "never", "only", "all", "every", "use", "do", "not", "no"}

def rule_subject(key):
    """A standing rule's subject: the first three words of its beads memory key that are not filler (claude-api-on-the-new-key-cap
    and claude-api-on-the-new-key-keychain share 'claude api new')."""
    w = [x for x in re.split(r"[^a-z0-9]+", key.lower()) if x and x not in RULE_STOP and not x.isdigit()]
    return "-".join(w[:3]) if len(w) >= 2 else None

def rule_findings(cfg):
    """rule-subject:<subject> when two standing rules (beads memories) are on the same subject: a newer rule replaces the older
    (bd remember <text> --key <the old key>), it never sits beside it (orch-swarm item 7)."""
    rc, o, e = sh(["bd", "memories", "--json"], cwd=cfg.beads)
    try: mem = json.loads(o) if rc == 0 and o.strip() else {}
    except Exception: return []
    if not isinstance(mem, dict): return []
    by = {}
    for k in mem: by.setdefault(rule_subject(k), []).append(k)
    return [(f"rule-subject:{sj}", f"{len(ks)} standing rules on one subject ({', '.join(sorted(ks)[:4])}): keep the current one under one key "
             f"(bd remember \"<rule>\" --key {sorted(ks)[0]}) and bd forget the others") for sj, ks in by.items() if sj and len(ks) > 1]

def learned_mark(cfg, lid, how):
    """Record that learned post <agent>:<n> was remembered or rejected (check then stops listing it)."""
    lid = lid.removeprefix("learned:"); d = cfg.jget("learned.json"); d[lid] = {"how": how, "t": int(now())}
    if not DRY: cfg.f("learned.json").write_text(json.dumps(d))

def memory_findings(cfg):
    es = memory_read(cfg); F = []
    if len(es) > mset(cfg, "cap_lines"):
        F.append(("memory-long", f"MEMORY.md holds {len(es)} entries, over [memory] cap_lines {mset(cfg, 'cap_lines')}: orch forget what no longer guides the agents"))
    cut = now() - mset(cfg, "review_days") * 86400
    seen = {}
    for i, (sec, d, k, t, s) in enumerate(es, 1):
        if mem_source_gone(cfg, s): F.append((f"memory-source:{i}", f"memory entry {i} cites {s}, which is gone: check it, then orch forget {i} or remember it again with a live source"))
        try:
            if time.mktime(time.strptime(d, "%Y-%m-%d")) < cut: F.append((f"memory-review:{i}", f"memory entry {i} is from {d} (over {mset(cfg, 'review_days')} days): still true? orch memory --keep {i} (re-dates it), or orch forget {i}"))
        except ValueError: pass
        if k: seen.setdefault(k, []).append(i)
    F += [(f"memory-subject:{k}", f"memory entries {', '.join(map(str, v))} are on the same subject [{k}]: keep one (orch forget the other)") for k, v in seen.items() if len(v) > 1]
    return F

# ---------------------------------------------------------------- init, doctor, queue (orch-fixes7: shareable setup)
def init_project(root, a):
    """A new project: write a commented starter orch.toml (from example.orch.toml next to orch.py), create the state, briefs and
    out folders, and say what is left. Never overwrites an orch.toml."""
    root = Path(root).resolve(); t = root / "orch.toml"
    if t.exists(): raise Err(f"{t} exists")
    ex = ORCH_SELF.parent / "example.orch.toml"
    if not ex.is_file(): print(f"orch: {ex} not found (install copies it next to orch.py)", file=sys.stderr); return 2
    name = a.name or slug(root.name) or "project"
    host = (os.uname().nodename.split(".")[0].lower() or "local").replace(" ", "-")
    text = ex.read_text().replace('name = "myproject"', f'name = "{name}"').replace('workspace = "myproject"', f'workspace = "{name}"')
    text = text.replace("[hosts.laptop]", f"[hosts.{host}]").replace('hosts = ["laptop"]', f'hosts = ["{host}"]')
    if DRY: print(text); return 0
    atomic_write(t, text)
    for d in (".orch", "briefs", "out"): (root / d).mkdir(exist_ok=True)
    say(f"wrote {t} (this machine is [hosts.{host}]); created .orch/, briefs/, out/")
    say("next: edit orch.toml (hosts, models, the API key's secret store), run `bd init` here if there is no .beads/, then `orch doctor`")
    return 0

def cmd_init(cfg, a):
    """In a project with an orch.toml: turn the old state docs in paths.state_docs into a one-line pointer to .orch/HANDOFF.md
    (fixes5 item 6); the old text is kept in .orch/history-<name> first."""
    for x in cfg.paths.get("state_docs", []):
        p = cfg.root / x
        if not p.is_file(): continue
        t = p.read_text(); ptr = f"Moved: the current state and handoff are in {cfg.state.name}/HANDOFF.md (orch check regenerates it). Old text: {cfg.state.name}/history-{p.name}\n"
        if t == ptr: say(f"{x}: already a pointer"); continue
        if DRY: say(f"+ keep {x} in {cfg.state.name}/history-{p.name}; write the pointer"); continue
        k = cfg.f(f"history-{p.name}")
        k.write_text((k.read_text() if k.exists() else "") + f"\n\n<!-- {ts()} moved from {x} -->\n" + t)
        atomic_write(p, ptr); say(f"{x}: now a pointer (old text in {k})")
    say(f"{cfg.root / 'orch.toml'} exists; run orch doctor to check the setup")

def cmd_doctor(cfg, a): return doctor(cfg, a)

def doctor(cfg, a):
    """Check a setup end to end and say what to fix: tools, the installed release, hooks, watcher, config, secret store,
    ledger, beads and hosts. Exit 1 when anything FAILs."""
    import shutil
    res = []
    def r(ok, what, fix=""): res.append((ok, what, fix)); say(f"{'ok  ' if ok is True else 'WARN' if ok is None else 'FAIL'} {what}" + (f"  -> {fix}" if fix and ok is not True else ""))
    path = clean_env()["PATH"]; which = lambda t: shutil.which(t, path=path)
    r(sys.version_info >= (3, 11), f"python {sys.version.split()[0]} (3.11+ for tomllib)", "install Python 3.11 or newer")
    for t, need in (("git", True), ("ssh", True), ("rsync", True), ("bd", True), ("pueue", True), ("herdr", False), ("tmux", False)):
        r(True if which(t) else (False if need else None), f"tool {t}" + (f" ({which(t)})" if which(t) else " missing"),
          {"bd": "brew install beads (or see github.com/steveyegge/beads)", "pueue": "brew install pueue; brew services start pueue"}.get(t, f"install {t}"))
    if which("pueue"): rc, o, e = sh(["pueue", "status"], clean=True); r(rc == 0, "pueued answers", "start it: brew services start pueue (macOS) or systemctl --user enable --now pueued")
    me = Path.home() / ".local/bin/orch"
    tgt = me.resolve() if me.exists() else None
    rel = tgt and ".local/share/orch/" in str(tgt)
    r(bool(rel), f"installed orch: {me} -> {tgt or 'missing'}", "run ./install from the orch repo (it copies a tested release; never a link to the working tree)")
    sk = Path.home() / ".claude/skills/orchestrating"
    r(True if sk.exists() and ".local/share/orch/" in str(sk.resolve()) else None if sk.exists() else False,
      f"skill {sk} -> {sk.resolve() if sk.exists() else 'missing'}", "run ./install")
    try: hk = json.loads((Path.home() / ".claude/settings.json").read_text()).get("hooks", {})
    except Exception: hk = {}
    miss = [ev for ev in ("SessionStart", "UserPromptSubmit", "PreToolUse", "Stop") if not any("orch hook " + ev in h.get("command", "") for e in hk.get(ev, []) for h in e.get("hooks", []))]
    r(not miss, "Claude Code hooks " + ("installed" if not miss else "missing: " + ", ".join(miss)), "run ./install")
    if sys.platform == "darwin": r(sh(["launchctl", "list", "com.orch.watch"])[0] == 0 or None, "watcher com.orch.watch loaded", "run ./install")
    else: r(sh(["systemctl", "--user", "is-active", "orch-watch.timer"])[0] == 0 or None, "watcher orch-watch.timer active", "run ./install")
    if cfg is None:
        r(False, f"no orch.toml in {Path.cwd()} or a parent", "orch init"); return 1
    say(f"-- project {cfg.name} ({cfg.root})")
    pl = Path.home() / ".config/orch/projects"
    r(cfg.root in projects() or None, f"project listed in {pl} (the watcher visits it)", f"run ./install --project {cfg.root}")
    if not cfg.hosts: r(False, "no [hosts.*] in orch.toml", "add [hosts.<this machine>] local = true")
    elif not any(h.get("local") for h in cfg.hosts.values()): r(False, "no host has local = true", "mark this machine's [hosts.<name>] local = true")
    for m, c in cfg.models.items():
        if c.get("provider") not in cfg.prov: r(False, f"model {m}: provider {c.get('provider')} has no [providers] table", "add it")
        if c.get("launcher"): r(None, f"model {m}: launcher {c['launcher']} is no longer used (orch runs API agents itself)", "remove the key")
        if c.get("kind") == "api" and not c.get("api_id"): r(False, f"model {m}: kind api needs api_id (the model id the API takes)", "set api_id")
        if c.get("kind") in ("claude", "codex", "opencode") or c.get("kind") == "api":
            t = "claude" if c.get("kind") == "api" else c["kind"]
            if not which(t): r(False if c.get("kind") == "api" else None, f"model {m}: {t} not on PATH", f"install {t}")
    for tier, lst in cfg.route.items():
        for m in lst:
            if m not in cfg.models: r(False, f"routing {tier}: unknown model {m}", "fix [routing]")
    for k, d in (("briefs", "briefs"), ("out", "out")):
        r(cfg.p(k, d).is_dir() or None, f"paths.{k} {cfg.p(k, d)}", f"mkdir {cfg.p(k, d)}")
    b = board_script(cfg)
    r(os.access(b, os.X_OK) or None, f"message board {b}", "optional: agents post progress through it (paths.board)")
    rc, o, e = sh(["bd", "list", "-n", "1", "--json"], cwd=cfg.beads)
    r(rc == 0, f"beads in {cfg.beads}", f"run bd init in {cfg.beads} ({(e or o).strip()[:80]})")
    for n, pv in cfg.prov.items():
        if not pv.get("enabled"): continue
        api = any(c.get("provider") == n and c.get("kind") == "api" for c in cfg.models.values())
        if api:
            try: var, key = read_secret(pv); r(True, f"provider {n}: API key readable from the secret store ({var}, {len(key)} chars, not shown)"); del key
            except Err as e: r(False, f"provider {n}: {e}", "macOS: security add-generic-password -s <item> -a $USER -w; elsewhere: a mode-600 key_file")
        if "ledger" in pv:
            runs, bad, notes = ledger_read(cfg, pv)
            r(not bad, f"provider {n}: ledger {pv['ledger']} " + ("valid" if not bad else f"MALFORMED ({bad[0][:80]})") + f", ${spend(runs):.2f} committed" + (f" of ${pv['cap_usd']}" if "cap_usd" in pv else ""), "orch ledger repair")
        elif api: r(None, f"provider {n}: no ledger, so no spend record or cap", "set ledger (and cap_usd)")
    if not a.no_hosts:
        with cf.ThreadPoolExecutor(8) as ex:
            ps = dict(zip(cfg.hosts, ex.map(lambda kv: probe(*kv), cfg.hosts.items())))
        for n, p in ps.items():
            if not p["ok"]: r(False, f"host {n}: unreachable ({p['err']})", f"ssh {cfg.hosts[n].get('ssh', '')} must work with keys (BatchMode)"); continue
            r(p.get("pueue") is not None or None, f"host {n}: reachable" + ("" if p.get("pueue") is not None else ", but pueue does not answer there"), "./install --hosts-only")
    fails = sum(1 for ok, *_ in res if ok is False); warns = sum(1 for ok, *_ in res if ok is None)
    say(f"doctor: {len(res)} checks, {fails} FAIL, {warns} WARN"); return 1 if fails else 0

def cmd_queue(cfg, a):
    """Read-only: each host's pueue status (or one task's log), so the orchestrator never needs ssh <host> pueue by hand."""
    for n, h in cfg.hosts.items():
        if a.host and n != a.host: continue
        rc, o, e = hrun(h, f"{pueue(h)} " + (f"log {int(a.log)}" if a.log is not None else "status"), timeout=30)
        say(f"== {n}" + ("" if rc == 0 else f" (exit {rc}: {(e or o).strip()[-100:]})")); say(o.rstrip())

# ---------------------------------------------------------------- hooks (Claude Code and Codex share one format)
# PreToolUse shell rules (audit H2, M5). The command is parsed, not pattern-matched: heredoc bodies are data unless fed to a
# shell or ssh; $( ), backticks and <( ) are judged as commands of their own; the rest is split on ; && || | & ( ) and newlines,
# and every segment is judged by its command word after wrappers (sudo, env, timeout, nice, nohup, xargs, command, exec, ...)
# and an absolute path are stripped. bash/sh/zsh -c, eval and ssh <host> <cmd> are judged recursively. Nothing passes because
# it starts with orch, bd, pueue, herdr or board.sh: those tools have their own allow-lists below.
BD_OK = set("list show ready create update close reopen comment comments note label tag assign q query search find-duplicates duplicates count "
            "status statuses types stale history diff lint dep graph children blocked epic remember recall memories forget prime info where "
            "context help version heartbeat defer undefer priority promote set-state state unclaim reclaim todo kv".split())
PUEUE_OK = {"status", "log", "follow", "wait", "help", "group", "completions"}   # read-only, here or over ssh (group: listing only)
HERDR_NO = {("pane", "close"), ("pane", "run"), ("pane", "send-text"), ("pane", "send-keys"), ("agent", "send-keys"), ("tab", "close"),
            ("workspace", "close"), ("worktree", "remove"), ("server", "stop")}
WRAP = {"sudo": "-u -g -h -p -C", "doas": "-u", "env": "-u -C -S", "timeout": "-s -k --signal --kill-after", "nice": "-n", "nohup": "",
        "command": "", "exec": "-a", "builtin": "", "time": "", "caffeinate": "-t -w", "stdbuf": "-i -o -e", "setsid": "", "ionice": "-c -n -p",
        "xargs": "-n -P -I -L -s -E -d -a --max-args --max-procs --replace --delimiter --arg-file", "chronic": "", "unbuffer": ""}
SHELLS = {"bash", "sh", "zsh", "dash", "ksh", "fish"}
INTERP = re.compile(r"^(python[\d.]*|perl|ruby|node|osascript)$")
INTERP_BAD = re.compile(r"rmtree|os\.(remove|unlink|rmdir|kill|killpg)|\.unlink\(|unlink\s*\(|\bsignal\.SIG|subprocess.*\b(rm|kill|pkill)\b|system\s*\(.*\b(rm|kill)\b|do shell script.*\b(rm|kill)\b")
DESTRUCT = {"kill": "kill by hand: use orch stop", "pkill": "kill by hand: use orch stop", "killall": "kill by hand: use orch stop",
            "truncate": "truncating files", "shred": "shred", "dd": "dd", "reboot": "reboot", "shutdown": "shutdown", "halt": "halt",
            "diskutil": "diskutil", "srm": "srm"}
QUOTED_TEXT = re.compile(r"'[^']*'|\"(?:\\.|[^\"\\])*\"")

def unquoted(text):
    """text without its quoted strings that hold whitespace (messages and prose: data); a quoted path stays."""
    return QUOTED_TEXT.sub(lambda m: m.group(0) if not re.search(r"\s", m.group(0)) else "''", text)

def scan_subst(c):
    """Replace $( ), backticks, <( ) and >( ) outside single quotes by a placeholder; turn unquoted newlines into ';' and drop
    comments. Returns (text, [inner texts])."""
    out, inner, i, q = [], [], 0, None
    while i < len(c):
        ch = c[i]
        if q == "'":
            out.append(ch); q = None if ch == "'" else q; i += 1; continue
        if ch == "\\" and i + 1 < len(c): out.append(c[i:i + 2]); i += 2; continue
        if ch == "'" and q is None: q = "'"; out.append(ch); i += 1; continue
        if ch == '"': q = None if q == '"' else ('"' if q is None else q); out.append(ch); i += 1; continue
        if q is None and ch == "#" and (i == 0 or c[i - 1] in " \t\n;&|("):
            while i < len(c) and c[i] != "\n": i += 1
            continue
        if q is None and ch == "\n": out.append(" ; "); i += 1; continue
        if (ch == "$" or (ch in "<>" and q is None)) and c[i + 1:i + 2] == "(" and c[i + 2:i + 3] != "(":
            d, j, qq = 1, i + 2, None
            while j < len(c) and d:
                x = c[j]
                if qq: qq = None if x == qq else qq
                elif x in "'\"": qq = x
                elif x == "(": d += 1
                elif x == ")": d -= 1
                j += 1
            inner.append(c[i + 2:j - 1]); out.append(" __SUBST__ "); i = j; continue
        if ch == "`":
            j = c.find("`", i + 1); j = len(c) if j < 0 else j
            inner.append(c[i + 1:j]); out.append(" __SUBST__ "); i = j + 1; continue
        out.append(ch); i += 1
    return "".join(out), inner

HEREDOC = re.compile(r"<<-?\s*(['\"]?)([A-Za-z_][\w.-]*)\1")

def split_heredocs(c):
    """(command text without heredoc bodies, [(line that opened it, body)])."""
    lines, out, docs, i = c.split("\n"), [], [], 0
    while i < len(lines):
        l = lines[i]; out.append(l); i += 1
        for m in HEREDOC.finditer(l):
            body = []
            while i < len(lines) and lines[i].strip() != m.group(2): body.append(lines[i]); i += 1
            i += 1; docs.append((l, "\n".join(body)))
    return "\n".join(out), docs

def words_of(text):
    lx = shlex.shlex(text, posix=True, punctuation_chars=";&|()<>"); lx.whitespace_split = True; lx.commenters = ""
    try: return list(lx)
    except ValueError: return text.split()

def strip_wrappers(w):
    """Drop keywords, assignments and wrapper commands in front of the real command word."""
    while w:
        b = os.path.basename(w[0])
        if w[0] in ("do", "then", "else", "elif", "if", "while", "until", "!", "{", "}", "time", "done", "fi", "esac"): w = w[1:]; continue
        if re.match(r"^[A-Za-z_]\w*=", w[0]): w = w[1:]; continue
        if b in WRAP:
            val = set(WRAP[b].split()); w = w[1:]
            while w and (w[0].startswith("-") or (b == "env" and "=" in w[0]) or (b == "timeout" and re.match(r"^[\d.]+[smhd]?$", w[0]))):
                o = w.pop(0)
                if o in val and w: w.pop(0)
                if b == "timeout" and re.match(r"^[\d.]+[smhd]?$", o): break
            continue
        break
    return w

def segments(text):
    """Split parsed words into command segments, with the redirection targets of each."""
    segs, cur, redir, w = [], [], [], words_of(text)
    i = 0
    while i < len(w):
        t = w[i]
        if t in (";", "&&", "||", "|", "&", "(", ")", ";;", "|&", "&;"):
            if cur or redir: segs.append((cur, redir))
            cur, redir = [], []; i += 1; continue
        if re.fullmatch(r"\d*(>|>>|>\||&>|&>>)", t) or (t.endswith(">") and set(t) <= set("0123456789&>|")):
            if i + 1 < len(w) and not w[i + 1] in ("&",):
                tgt = w[i + 1]
                if tgt == "&" and i + 2 < len(w): i += 3; continue   # 2>&1 style
                redir.append(tgt); i += 2; continue
            i += 1; continue
        if t in (">&", "<&", "<", "<<", "<<<", "<<-", "<>"): i += 2; continue
        if re.fullmatch(r"\d*>&\d*-?|\d*<&\d*-?", t): i += 1; continue
        cur.append(t); i += 1
    if cur or redir: segs.append((cur, redir))
    return segs

def write_ok(cfg, cwd, tgt, ok_dirs):
    """A redirection target the orchestrator may write: outside the project and the worktrees, or inside an allowed path."""
    if tgt.startswith("/dev/") or tgt in ("__SUBST__", "-") or tgt.startswith("$"): return True
    p = Path(os.path.expanduser(tgt)); p = (p if p.is_absolute() else Path(cwd) / p).resolve()
    guarded = [cfg.root.resolve(), cfg.p("worktrees", "worktrees").resolve()]
    if not any(p == g or g in p.parents for g in guarded): return True
    return any(p == o or o in p.parents for o in ok_dirs)

def judge_words(cfg, w, cwd, ok_dirs, remote, depth):
    w = strip_wrappers(w)
    if not w: return None
    b = os.path.basename(w[0]); args = w[1:]
    if b in SHELLS:
        for i, x in enumerate(args):
            if x == "-c" or (x.startswith("-") and not x.startswith("--") and "c" in x[1:]):
                return judge(cfg, args[i + 1] if i + 1 < len(args) else "", cwd, ok_dirs, remote, depth + 1)
        return None
    if b == "eval": return judge(cfg, " ".join(args), cwd, ok_dirs, remote, depth + 1)
    if b in ("ssh", "mosh"):
        i = 0
        while i < len(args) and args[i].startswith("-"):
            i += 2 if re.fullmatch(r"-[bcDEeFIiJLlmOoPpQRSWw]", args[i]) else 1
        rest = args[i + 1:]
        return judge(cfg, " ".join(rest), cwd, ok_dirs, True, depth + 1) if rest else None
    if b in DESTRUCT: return DESTRUCT[b]
    if b in ("mkfs",) or b.startswith("mkfs."): return "mkfs"
    if b == "rm" and any(x in ("-r", "-R", "--recursive") or (re.fullmatch(r"-[A-Za-z]+", x) and re.search(r"[rR]", x)) for x in args if x != "--"):
        return "rm -r by hand"
    if b == "sed" and any(x.startswith("--in-place") or re.fullmatch(r"-[A-Za-z]*i\S*", x) for x in args): return "in-place edit"
    if b == "perl" and any(re.fullmatch(r"-\w*i\S*", x) for x in args): return "in-place edit"
    if INTERP.match(b):
        code = " ".join(args[i + 1] for i, x in enumerate(args[:-1]) if x in ("-c", "-e", "-E"))
        if INTERP_BAD.search(code): return f"destructive {b} one-liner"
    if b == "find" and any(x in ("-delete", "-exec", "-execdir", "-ok", "-okdir") for x in args):
        if "-delete" in args: return "find -delete"
        k = next(i for i, x in enumerate(args) if x in ("-exec", "-execdir", "-ok", "-okdir"))
        if k + 1 < len(args) and os.path.basename(args[k + 1]) in ("rm", "mv", "unlink", "shred", "truncate", "rmdir"): return f"find -exec {os.path.basename(args[k + 1])}"
        why = judge_words(cfg, [x for x in args[k + 1:] if x not in (";", "+", "{}")], cwd, ok_dirs, remote, depth + 1)
        if why: return "find -exec: " + why
    if b == "rsync" and any(x.startswith(("--delete", "--remove-source-files")) for x in args): return "rsync --delete by hand"
    if b == "git":
        i = 0
        while i < len(args) and args[i].startswith("-"): i += 2 if args[i] in ("-C", "-c", "--git-dir", "--work-tree") else 1
        sub, ga = (args[i], args[i + 1:]) if i < len(args) else ("", [])
        if sub == "reset" and any(x in ("--hard", "--merge", "--keep") for x in ga): return "git reset --hard"
        if sub == "clean": return "git clean"
        if sub == "push" and any(x in ("-f", "--force", "--mirror", "--delete", "-d", "--prune") or x.startswith(("--force", "+")) or (x.startswith(":") and len(x) > 1) for x in ga): return "git push --force/--delete"
        if sub in ("checkout", "switch") and any(x in ("--", ".", "-f", "--force", "--discard-changes") for x in ga): return f"git {sub} that discards changes"
        if sub == "restore": return "git restore"
        if sub == "branch" and any(x in ("-D", "--delete", "-d", "-f", "--force") for x in ga): return "git branch delete"
        if sub == "stash" and ga[:1] and ga[0] in ("drop", "clear"): return "git stash drop"
        if sub == "worktree" and ga[:1] and ga[0] in ("remove", "prune"): return "git worktree remove"
        if sub == "sparse-checkout": return "sparse-checkout"
        if sub in ("filter-branch", "filter-repo", "update-ref", "gc", "prune"): return f"git {sub}"
        if sub == "reflog" and ga[:1] and ga[0] in ("expire", "delete"): return "git reflog expire"
    if b == "pueue":
        i = 0
        while i < len(args) and args[i].startswith("-"): i += 2 if args[i] in ("-c", "--config", "-p", "--profile", "--color") else 1
        sub = args[i] if i < len(args) else "status"
        if sub not in PUEUE_OK or (sub == "group" and len(args) > i + 1 and not args[i + 1].startswith("-")):
            return f"pueue {sub} by hand: use orch run/stop/close (pueue limits are orch's)"
    if b == "bd":
        sub = next((x for x in args if not x.startswith("-")), "")
        if sub and sub not in BD_OK: return f"bd {sub} by hand"
    if b == "herdr":
        a2 = [x for x in args if not x.startswith("-")][:2]
        if tuple(a2) in HERDR_NO: return f"herdr {' '.join(a2)} by hand: orch launch/stop/close manage panes"
    if b == "board.sh" and args[:1] == ["close"]: return "board.sh close by hand: orch close does it"
    if b == "orch" and args[:1] == ["close"] and "--force" in args: return "orch close --force (owner: never on shared repos)"
    if b == "orch" and args[:1] == ["api-run"]: return "orch api-run by hand: orch launch queues it (budget, ledger, lanes)"
    if b == "launchctl" and args[:1] and args[0] in ("bootout", "remove", "unload", "kill", "disable"): return f"launchctl {args[0]}"
    if b == "systemctl" and any(x in ("stop", "restart", "kill", "disable", "mask", "reboot", "poweroff") for x in args): return "systemctl stop/restart"
    if b in ("podman", "docker") and args[:1] and args[0] in ("rm", "kill", "stop", "rmi", "prune", "system", "volume", "restart"): return f"{b} {args[0]} by hand"
    if b == "tmux" and any(x.startswith("kill-") for x in args): return "tmux kill by hand: use orch stop"
    return None

GIT_MUT = {"add", "commit", "push", "reset", "checkout", "switch", "clean", "stash", "merge", "rebase", "pull", "am", "apply", "cherry-pick", "revert", "rm", "mv"}

def git_sub(args):
    i = 0
    while i < len(args) and args[i].startswith("-"): i += 2 if args[i] in ("-C", "-c", "--git-dir", "--work-tree") else 1
    return args[i] if i < len(args) else ""

MUTATORS = {"rm", "mv", "cp", "ln", "rsync", "touch", "chmod", "chown", "install", "rmdir", "unlink", "tee"}

def judge(cfg, c, cwd, ok_dirs, remote=False, depth=0):
    """Why the shell command c is refused, or None."""
    if depth > 6: return "command nested too deeply to judge"
    text, docs = split_heredocs(c)
    for line, body in docs:   # a heredoc fed to a shell or ssh is commands; any other is data
        lw = strip_wrappers(words_of(scan_subst(line.split("<<")[0])[0]))
        fed = [x for x in (strip_wrappers(w) for w, _ in segments(scan_subst(line)[0])) if x]   # `cat <<EOF | bash` feeds a shell too
        if not (lw and os.path.basename(lw[0]) in SHELLS | {"ssh", "eval"} and "-c" not in lw):
            lw = next((x for x in fed[1:] if os.path.basename(x[0]) in SHELLS | {"ssh", "eval"} and "-c" not in x), lw)
        if lw and (os.path.basename(lw[0]) in SHELLS or os.path.basename(lw[0]) in ("ssh", "eval")) and not any(x == "-c" for x in lw):
            why = judge(cfg, body, cwd, ok_dirs, remote or os.path.basename(lw[0]) == "ssh", depth + 1)
            if why: return why
        elif lw and INTERP.match(os.path.basename(lw[0])) and INTERP_BAD.search(body): return f"destructive {os.path.basename(lw[0])} script"
    text, inner = scan_subst(text)
    for x in inner:
        why = judge(cfg, x, cwd, ok_dirs, remote, depth + 1)
        if why: return why
    # A loop is judged from command words only (orch-fixes7): `for`/`while`/`until`/`select` or xargs/parallel in command
    # position, over worktrees named outside quoted text; a commit message or an echo that says "while" or "worktrees" is data.
    segs = segments(text)
    loop = any(w and (w[0] in ("for", "while", "until", "select") or os.path.basename(w[0]) in ("xargs", "parallel")) for w, _ in segs) and re.search(r"\bworktrees?\b", unquoted(text))
    for w, redir in segs:
        if w and w[0] == "cd" and len(w) > 1 and not remote: cwd = str((Path(cwd) / os.path.expanduser(w[1])).resolve())
        if w and w[0] in ("for", "case", "select", "function", "in"): continue
        why = judge_words(cfg, w, cwd, ok_dirs, remote, depth)
        if why: return why
        if not remote:
            for t in redir:
                if not write_ok(cfg, cwd, t, ok_dirs): return f"writing {t} by hand"
        sw = strip_wrappers(w)
        if loop and sw and (os.path.basename(sw[0]) in MUTATORS or (sw[0] == "git" and git_sub(sw[1:]) in GIT_MUT)):
            return "loop that changes worktrees"
    return None

def edit_ok_dirs(cfg):
    """Paths the orchestrator may write: its state dir, briefs, orch.toml, its own plan files (~/.claude/plans: plan mode writes
    there), and the project's status checklist and old state docs (paths.checklist, paths.state_docs) (audit M7)."""
    ok = [cfg.state, cfg.p("briefs", "briefs"), cfg.root / "orch.toml", Path.home() / ".claude/plans"]   # its own plan files (plan mode)
    if cfg.paths.get("checklist"): ok.append(cfg.p("checklist"))
    ok += [cfg.root / x for x in cfg.paths.get("state_docs", [])]
    return [p.resolve() for p in ok]

def patch_paths(ti):
    """Target paths of an apply_patch call (Codex): '*** Add|Update|Delete File: <path>' and '*** Move to: <path>'."""
    txt = "\n".join(v for v in (ti.values() if isinstance(ti, dict) else [ti]) if isinstance(v, str))
    return re.findall(r"^\*\*\* (?:Add File|Update File|Delete File|Move to): (.+?)\s*$", txt, re.M)

def pretool_why(cfg, d):
    """Why a PreToolUse call of the orchestrator is refused, or None."""
    tool, ti = d.get("tool_name", ""), d.get("tool_input") or {}
    cwd = d.get("cwd") or str(cfg.root); ok = edit_ok_dirs(cfg)
    inside = lambda fp: any(fp == o or o in fp.parents for o in ok)
    if tool == "apply_patch" or (isinstance(ti, dict) and any(isinstance(v, str) and "*** Begin Patch" in v for v in ti.values())):
        ps = patch_paths(ti)
        bad = [p for p in ps if not inside((Path(p) if Path(p).is_absolute() else Path(cwd) / p).resolve())]
        return "editing files by hand" if bad or not ps else None
    if tool in ("Edit", "Write", "MultiEdit", "NotebookEdit"):
        fp = Path(ti.get("file_path") or ti.get("notebook_path") or "/x")
        return None if inside((fp if fp.is_absolute() else Path(cwd) / fp).resolve()) else "editing files by hand"
    c = ti.get("command") if isinstance(ti, dict) else None
    if c is None and isinstance(ti, dict): c = ti.get("cmd")
    if c is None: return None
    c = shlex.join(c) if isinstance(c, list) and not (len(c) >= 3 and c[0] in SHELLS and c[1] in ("-c", "-lc")) else (c[2] if isinstance(c, list) else c)
    return judge(cfg, c, cwd, ok)

def deny_log(cfg, d, why):
    """.orch/denied.log: every refused tool call, so a wrong refusal can be found and fixed (orch-fixes7)."""
    ti = d.get("tool_input") or {}
    c = ti.get("command") or ti.get("cmd") or ti.get("file_path") or "" if isinstance(ti, dict) else ti
    try:
        with cfg.f("denied.log").open("a") as f: f.write(f"{ts()} {d.get('tool_name', '')} ({why}): {json.dumps(c)[:400]}\n")
    except OSError: pass

def out(o): print(json.dumps(o))

def ctx(ev, text): out({"hookSpecificOutput": {"hookEventName": ev, "additionalContext": text}})

def block(reason): out({"decision": "block", "reason": reason})

def agent_hook(ev, d):
    rp = os.environ.get("ORCH_REPORT")
    if ev != "Stop" or not rp: return
    try: t = Path(rp).read_text()
    except OSError: t = ""
    first = t.splitlines()[0] if t else ""
    ok = re.search(r"^VERDICT: (DONE|BLOCKED|FAILED)\b", t, re.M) and "PENDING" not in first and re.search(r"exit(\s+code)?s?\b", t, re.I)
    if not ok: block(f"Not finished: {rp} must hold the real results and exit codes and end with a final 'VERDICT: DONE' line (line 1 is no longer PENDING).")

ORCH_MARK = "[orch] "   # every prompt orch itself sends starts with this, so UserPromptSubmit never files it as an instruction (M4)

def cmd_hook(ev):
    try: d = json.loads(sys.stdin.read() or "{}")
    except Exception: d = {}
    if os.environ.get("ORCH_ROLE") == "agent": return agent_hook(ev, d)
    sid = d.get("session_id")
    if not sid: return
    # The project is the one whose registered session this is, wherever the session's shell is (H3). Only a pending
    # registration (orch register without a session id, or the watcher's new orchestrator) is claimed from the cwd, within
    # 10 min. No variable (ORCH_ROLE) takes a registration over (H4).
    root = session_root(sid)
    if not root:
        root = find_root(d.get("cwd"))
        if not root: return
        cfg = Cfg(root); reg = cfg.f("session").read_text().strip() if cfg.f("session").exists() else ""
        if not (reg.startswith("pending:") and now() - int(reg[8:] or 0) < 600): return
        cfg.f("session").write_text(sid); cfg.f("session_kind").write_text(hook_kind(d) + "\n")
        record_session_proc(cfg)
    else: cfg = Cfg(root)
    if session_alive(cfg) is not True: record_session_proc(cfg)
    if d.get("transcript_path"): cfg.f("transcript").write_text(d["transcript_path"])
    if ev == "SessionStart":   # cached state only: the hook has a 60 s limit, and the check runs as the session's first act (M14)
        parts = [handoff_path(cfg).read_text() if handoff_path(cfg).exists() else "", memory_text(cfg)]   # MEMORY.md (orch-swarm item 2)
        rc, o, e = sh(["bd", "prime"], cwd=cfg.beads, timeout=20); parts.append(o if rc == 0 else f"(bd prime unavailable: {e.strip()[:80]})")
        parts.append("The Live state above is from the last check. You are the orchestrator: dispatch, monitor, verify, land, clean up, report. "
                     "First run orch check, act on each line, orch ack. See the orchestrating skill.")
        ctx(ev, "\n\n".join(parts)[:30000])
    elif ev == "UserPromptSubmit":
        pr = (d.get("prompt") or "").strip()
        orchs = pr.startswith((ORCH_MARK, "orch cycle:", WAKE, "You are the orchestrator. " + WAKE)) or pr in ("/clear", "/compact") or pr.startswith("/")
        if pr and not orchs and "<task-notification>" not in pr and "[SYSTEM NOTIFICATION" not in pr:
            try:
                i = Beads(cfg).create("instr: " + re.sub(r"\s+", " ", pr)[:70], "instruction", pr[:4000]); cfg.touch("changed")
                ctx(ev, f"Filed as instruction {i}: close it as done, or make it a standing rule with bd remember \"<rule>\" --key <subject> "
                    "(a rule on a subject that already has one replaces it: use that rule's key, bd memories); if it affects several agents, also orch remember --decision.")
            except Err: pass
    elif ev == "PreToolUse":
        why = pretool_why(cfg, d)
        if why: deny_log(cfg, d, why)
        if why: out({"hookSpecificOutput": {"hookEventName": ev, "permissionDecision": "deny",
                     "permissionDecisionReason": f"Orchestrators do not operate by hand ({why}). Use orch launch/stop/collect/close, or brief an agent."}})
    elif ev == "Stop":
        n = cfg.jget("stops.json"); c = n.get(sid, 0) + 1 if d.get("stop_hook_active") else 0; n[sid] = c; cfg.jput("stops.json", n)
        if c >= 3: return
        op = cfg.jget("open.json"); late = [k for k, t in op.items() if now() - t > cfg.deadline]
        stale = handoff_stale(cfg, cfg.jget("running.json").get("n", 0) > 0)
        if late or stale:
            block("Do not go idle: " + ("unacknowledged past deadline: " + ", ".join(late[:6]) + ". Run orch check, act, orch ack. " if late else "") + " ".join(stale))

def hook_kind(d):
    tp = d.get("transcript_path") or ""
    return "codex" if ("codex" in tp or os.environ.get("CODEX_THREAD_ID")) else "claude"

# ---------------------------------------------------------------- watch (launchd, one pass)
URGENT = ("unit:", "board:", "question:", "overlap:", "orphan:", "host:", "margin:", "stalled:", "spend:", "instructions", "beads", "old-rule:", "burner:", "ledger:", "script:", "idle-backlog:", "landing:",
          "idle-with-backlog", "scheduler:", "pressure:", "direct:", "budget80:", "waiting:", "waste", "report-due", "parked:")

def cmd_watch(cfg, a):
    log = lambda m: cfg.f("watch.log").open("a").write(f"{ts()} {m}\n")
    if getattr(a, "alert", False): board_alerts(cfg, log); return   # board.sh .notify: a new question or block, at once
    if not cfg.paths.get("board") and (board_dir(cfg) / ".hosts").is_file() and (board_dir(cfg) / ".hosts").read_text().strip():
        board(cfg, "sync", timeout=180)   # the shipped board: merge the hosts' outboxes, push the board (peers, index) to them
    F, live, hs, units = run_check(cfg, cycle=False, writer=True)
    board_alerts(cfg, log)
    tend_parked(cfg, hs, units, log)   # park, resume when the jobs finished, wrap up capped runs (orch-fixes9)
    for r, why in orphan_jobs(cfg, hs, units):   # nothing whose owner is gone keeps running or waiting (item 3)
        try: log(f"orphan {r} ({why}): " + "; ".join(cancel_job(cfg, r)))
        except Err as e: log(f"orphan {r} ({why}): not cancelled: {e}")
    live = {wrap_token(t) for p in hs.values() for t in ((p.get("pueue") or {}).get("tasks") or {}).values() if task_rc(t) is None}
    for f in (cfg.f("runs") / "wrap").glob("*") if (cfg.f("runs") / "wrap").is_dir() else []:   # finished wrappers' records, after a day
        if f.name not in live and now() - f.stat().st_mtime > 86400 and all(job_state(hs, r)[0] in ("done", "gone") for r in wrapped_jobs(cfg, f.name)): f.unlink()
    # [fill] watcher = true (owner autonomy: "launch within capacity"): launch ready backlog units up to capacity, at most every
    # [fill] every_min (default 10) minutes, only when check found something that fits (idle-with-backlog)
    fc = cfg.c.get("fill", {})
    if fc.get("watcher") and any(k == "idle-with-backlog" for k, _ in F) and now() - cfg.mtime("last_fill") > fc.get("every_min", 10) * 60:
        cfg.touch("last_fill")
        try:
            import io, contextlib
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf): cmd_fill(cfg, argparse.Namespace(max=fc.get("max_per_pass")))
            log("fill: " + " | ".join(l.strip() for l in buf.getvalue().splitlines())[:600])
        except Exception as e: log(f"fill failed: {e}")
    running = any(u.get("state") in ("working", "queued") for u in units)
    op = cfg.jget("open.json"); late = [k for k, t in op.items() if now() - t > cfg.deadline]
    overdue = (running or F) and now() - cfg.mtime("last_cycle") > cfg.cycle
    pane = cfg.f("pane").read_text().strip() if cfg.f("pane").exists() else ""
    pl = herdr("pane", "list")
    if pl is None: log("herdr did not answer (error or timeout): nothing started or woken"); return
    present = pane in {p.get("pane_id") for p in pl.get("panes", [])}
    ag = herdr("agent", "get", pane) if pane and present else None
    if present and ag is None: log(f"herdr agent get {pane} failed: nothing started"); return
    if not present or not (ag or {}).get("agent"):
        # A new orchestrator only when every sign says the registered one is gone (H4, fixes5 item 1): its pane is absent from
        # a successful pane list, its process (pid and start time recorded at register) is not running, and its transcript has
        # not changed for 20 min.
        alive = session_alive(cfg)
        tr = cfg.f("transcript").read_text().strip() if cfg.f("transcript").exists() else ""
        quiet = now() - (os.path.getmtime(tr) if tr and os.path.exists(tr) else 0) > 20 * 60
        if alive or not quiet:
            log(f"pane {pane or '-'} not found, but the registered session is {'still running' if alive else 'writing its transcript'}: nothing started"); return
        if not (F or running): return
        if not any(p.get("enabled") for p in cfg.prov.values()): log("orchestrator gone; no provider enabled"); return
        if now() - cfg.mtime("last_wake") < 600: return
        kind = (cfg.f("session_kind").read_text().strip() if cfg.f("session_kind").exists() else "") or cfg.c.get("orchestrator", {}).get("kind", "claude")
        oc = cfg.c.get("orchestrator", {}); args = oc.get("args", []) if oc.get("kind", "claude") == kind else []
        cfg.touch("last_wake"); log(f"orchestrator gone (pane absent, process ended, transcript quiet): starting a new {kind} one")
        cfg.f("session").write_text(f"pending:{int(now())}")   # its first hook event claims the registration
        pane, _ = new_tab(cfg, "orchestrator", cfg.root); wait_shell(pane, "orchestrator")
        sh(["herdr", "agent", "start", "orchestrator", "--kind", kind, "--pane", pane, "--timeout", "90000", "--", *args], timeout=100)
        cfg.f("pane").write_text(pane); herdr("agent", "prompt", "orchestrator", ORCH_MARK + "You are the orchestrator. Run orch register, then " + WAKE); return
    st = ag["agent"].get("agent_status")
    if st == "working": return
    tr = cfg.f("transcript").read_text().strip() if cfg.f("transcript").exists() else ""
    big = tr and os.path.exists(tr) and os.path.getsize(tr) / 4 > cfg.reset_tokens
    urgent = [k for k, _ in F if k.startswith(URGENT)]   # acked findings are already out of F; informational ones do not hold a reset (L4)
    if big and not urgent and not handoff_stale(cfg, False):
        if cfg.f("reset_asked").exists():
            cfg.f("reset_asked").unlink(); log("context reset: /clear"); herdr("agent", "prompt", pane, "/clear"); return
        cfg.touch("reset_asked"); log("context large: asked for final notes")
        herdr("agent", "prompt", pane, ORCH_MARK + "Context is large: finish the Orchestrator notes in .orch/HANDOFF.md, then stop."); return
    if (overdue or late) and now() - cfg.mtime("last_wake") > 600:
        cfg.touch("last_wake"); log(f"wake: overdue={bool(overdue)} late={late[:3]}"); herdr("agent", "prompt", pane, ORCH_MARK + WAKE)

# ---------------------------------------------------------------- main
def main():
    global DRY
    ap = argparse.ArgumentParser(prog="orch"); sp = ap.add_subparsers(dest="cmd", required=True)
    def add(n, *args, dry=False):
        p = sp.add_parser(n)
        for x in args: p.add_argument(*x[0], **x[1])
        if dry: p.add_argument("--dry-run", action="store_true")
        return p
    A = lambda *n, **k: (n, k)
    add("check", A("--brief", action="store_true"), A("--escalate", action="store_true"))
    add("capacity"); add("status"); add("watch", A("--alert", action="store_true", help="only tell the orchestrator about new board questions and blocks"))
    add("learned", A("--reject", help="reject learned post <agent>:<n> (check stops listing it)"), A("--why", help="why it is rejected"))
    add("launch", A("unit"), A("--kind", choices=["implement", "review", "audit", "cleanup"], required=True), A("--tier", choices=["critical", "normal"], default="normal"),
        A("--host"), A("--model"), A("--brief"), A("--cwd"), A("--budget", type=float, help="USD budget for this unit (overrides the provider's budget_per_unit)"),
        A("--test-host", help="host where the unit's builds and tests run; the agent is placed there"), A("--allow-main", action="store_true", help="allow a main checkout as cwd"), A("--of", help="unit whose implementer's vendor a review must avoid"),
        A("--report", help="a resumed unit: the report it continues (default out/<unit>/REPORT.md)"), A("--resume-of", help="a resumed unit: the unit whose report it continues"),
        A("--item", help="the backlog item this unit works on (orch backlog)"), dry=True)
    add("api-run", A("unit"), A("--run", required=True), A("--model", required=True), A("--budget", type=float, required=True), A("--brief", required=True),
        A("--cwd", required=True), A("--report"), A("--resume-session", help="continue this agent session"), A("--prompt-file", help="the prompt (default: the brief's)"))
    add("park", A("unit"), dry=True)
    add("resume", A("unit"), A("--message", help="resume with this text instead of its jobs' results"), A("--force", action="store_true", help="resume although its jobs have not finished"), dry=True)
    add("ledger", A("action", choices=["check", "repair"]), A("--provider"), dry=True)
    add("doctor", A("--no-hosts", action="store_true", help="skip the ssh checks"))
    add("backlog", A("action", choices=["import", "list", "set"]), A("args", nargs="*", help="set: <item id> actor=<agent|owner|hardware|...>"), dry=True)
    add("queue", A("host", nargs="?"), A("--log", type=int, help="print this task's log"))
    add("stop", A("unit"), A("--force", action="store_true", help="stop although its remote copy has uncollected work"), dry=True)
    add("collect", A("unit", help="a unit, or <host>:<task id> for an orch run job"), dry=True)
    add("run", A("--host", required=True), A("--lane", choices=LANES, default="jobs"), A("--unit"), A("--wt", required=True),
        A("--subdir", help="run from this subdirectory of the worktree"), A("--usb", action="store_true", help="a job that needs the host's USB devices (container.usb_args, usb_lock)"),
        A("--priority", type=int, default=0), A("--detach", "--no-wait", dest="no_wait", action="store_true", help="queue, print <host>:<task>, return (agents: then write WAITING <ids> and end the turn)"),
        A("--allow-unmerged", action="store_true", help="run on a tree with a merge in progress, conflict markers or far behind the landing branch"),
        A("command", nargs=argparse.REMAINDER), dry=True)
    add("gate", A("name"), A("--host", help="test host for the whole gate (passed in paths.gate_host_env)"), A("--unit", help="the unit this gate checks (default $ORCH_UNIT)"), A("--priority", type=int, default=10),
        A("--wait", action="store_true", help="wait and print the RESULT line; exit 0 on PASS"),
        A("--allow-unmerged", action="store_true", help="gate a tree mid-merge, with conflict markers or far behind the landing branch"), dry=True)
    add("busy", A("wt", help="a worktree: exit 0 while an orch job, a unit's job or a mutation run uses it, else 1"))
    add("cancel", A("job", help="<host>:<task id> of an orch run/gate job"), A("--force", action="store_true", help="cancel although its files could not be saved"), dry=True)
    add("fill", A("--max", type=int, help="launch at most this many"), dry=True)
    add("report", A("--brief", action="store_true", help="summary lines only"), A("--sent", action="store_true", help="record that the report was sent (clears report-due)"))
    add("land", A("unit"), A("--no-gate", action="store_true", help="skip the final gate (it is still refused mid-merge)"),
        A("--no-dispatch", action="store_true", help="on a conflict, only say what merge unit to dispatch"), dry=True)
    add("close", A("unit"), A("--force", action="store_true"), A("--reason"), dry=True)
    add("commit-state", A("-m", "--message", default="orch: state"), dry=True)
    add("ack", A("problem"), A("decision"))
    m = add("remember", A("text"), A("--source", help="where it can be checked: a path, a commit sha or a job (a fact needs one)"),
            A("--key", help="its subject: a newer entry on the same subject replaces the older one"), A("--learned", help="the learned post it accepts (<agent>:<n>)"), dry=True)
    g = m.add_mutually_exclusive_group(required=True)
    for k in MEM_SECTIONS: g.add_argument(f"--{k}", action="store_true")
    add("forget", A("text", help="the entry's number (orch memory), its subject, or its text"), dry=True)
    add("index", dry=True); add("peers")
    add("transcript", A("unit"), A("--grep", help="only the lines matching this regex (case-insensitive)"), A("--tail", type=int, default=40, help="the last N lines (0: all)"))
    add("memory", A("--keep", type=int, help="re-date entry N after review (it stays)"), dry=True)
    add("init", A("--name", help="project name for a new orch.toml (default: the folder's name)"), dry=True)
    add("board-close", A("agent", help="a board card that is not an open unit"), dry=True)
    add("register", A("session", nargs="?"), dry=True)
    add("hook", A("event", choices=["SessionStart", "UserPromptSubmit", "PreToolUse", "Stop"]))
    a = ap.parse_args()
    if a.cmd == "hook":
        try: cmd_hook(a.event)
        except Exception as e: print(f"orch hook: {e}", file=sys.stderr)
        return 0
    DRY = getattr(a, "dry_run", False)
    root = find_root(os.getcwd()) if a.cmd in ("init", "doctor") else find_root()   # never $ORCH_ROOT for setup commands
    if a.cmd == "init" and not root: return init_project(Path.cwd(), a)
    if a.cmd == "doctor" and not root: return doctor(None, a)
    if not root: print("orch: no orch.toml here or in a parent (orch init writes a starter one)", file=sys.stderr); return 2
    try: cfg = Cfg(root)
    except (tomllib.TOMLDecodeError, OSError) as e: print(f"orch: {root / 'orch.toml'}: {e}", file=sys.stderr); return 2
    try: r = globals()["cmd_" + a.cmd.replace("-", "_")](cfg, a)
    except Err as e: print(f"orch: {e}", file=sys.stderr); return 1
    return r if isinstance(r, int) else 0

if __name__ == "__main__": sys.exit(main())
